window.COURSE = {"structure":{"title_ru":"Анализ больших данных","title_kk":"Үлкен деректерді талдау","language":"ru","modules":[{"id":"m1","title_ru":"Основы больших данных и бизнес-аналитики","title_kk":"Үлкен деректер мен бизнес-аналитика негіздері","blocks":[{"id":"b1.1","title_ru":"Понятие больших данных","title_kk":"Үлкен деректер ұғымы","lessons":[{"id":"l01","number":1,"title_ru":"Введение в большие данные","title_kk":"Үлкен деректерге кіріспе","sources":["lecture-01","practice-01"],"elements":{"theory":{"file":"lessons/01/theory.html","chars":4937,"images":1},"examples":{"file":"lessons/01/examples.html","chars":1709,"images":0},"tasks":{"file":"lessons/01/tasks.html","chars":1562,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/01/questions.json","count":6},"tests":{"file":"lessons/01/tests.json","count":10}}},{"id":"l02","number":2,"title_ru":"Аналитика данных","title_kk":"Деректер аналитикасы","sources":["lecture-02","practice-02"],"elements":{"theory":{"file":"lessons/02/theory.html","chars":1683,"images":2},"examples":{"file":"lessons/02/examples.html","chars":9557,"images":0},"tasks":{"file":"lessons/02/tasks.html","chars":1278,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/02/questions.json","count":5},"tests":{"file":"lessons/02/tests.json","count":10}}}]},{"id":"b1.2","title_ru":"Бизнес-аналитика (BI) и OLAP","title_kk":"Бизнес-аналитика (BI) және OLAP","lessons":[{"id":"l03","number":3,"title_ru":"Жизненный цикл аналитики данных","title_kk":"Деректер аналитикасының өмірлік циклі","sources":["lecture-03","practice-04"],"elements":{"theory":{"file":"lessons/03/theory.html","chars":13095,"images":0},"examples":{"file":"lessons/03/examples.html","chars":1572,"images":0},"tasks":{"file":"lessons/03/tasks.html","chars":1307,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/03/questions.json","count":5},"tests":{"file":"lessons/03/tests.json","count":10}}},{"id":"l04","number":4,"title_ru":"Компоненты аналитики MS SQL Server","title_kk":"MS SQL Server аналитика компоненттері","sources":["lecture-04","practice-03"],"elements":{"theory":{"file":"lessons/04/theory.html","chars":3773,"images":0},"examples":{"file":"lessons/04/examples.html","chars":5615,"images":0},"tasks":{"file":"lessons/04/tasks.html","chars":1283,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/04/questions.json","count":5},"tests":{"file":"lessons/04/tests.json","count":10}}}]}]},{"id":"m2","title_ru":"Технологии хранения и обработки больших данных","title_kk":"Үлкен деректерді сақтау және өңдеу технологиялары","blocks":[{"id":"b2.1","title_ru":"Hadoop и MapReduce","title_kk":"Hadoop және MapReduce","lessons":[{"id":"l05","number":5,"title_ru":"Высокопроизводительные вычисления. Hadoop","title_kk":"Жоғары өнімді есептеулер. Hadoop","sources":["lecture-05","practice-05"],"elements":{"theory":{"file":"lessons/05/theory.html","chars":9176,"images":1},"examples":{"file":"lessons/05/examples.html","chars":2979,"images":0},"tasks":{"file":"lessons/05/tasks.html","chars":1352,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/05/questions.json","count":5},"tests":{"file":"lessons/05/tests.json","count":10}}},{"id":"l06","number":6,"title_ru":"Hadoop MapReduce 1.0 и 2.0","title_kk":"Hadoop MapReduce 1.0 және 2.0","sources":["lecture-06","practice-06"],"elements":{"theory":{"file":"lessons/06/theory.html","chars":6859,"images":1},"examples":{"file":"lessons/06/examples.html","chars":1340,"images":0},"tasks":{"file":"lessons/06/tasks.html","chars":1231,"images":0},"selfcheck":{"file":"lessons/06/selfcheck.html","chars":743,"images":0},"questions":{"file":"lessons/06/questions.json","count":6},"tests":{"file":"lessons/06/tests.json","count":10}}}]},{"id":"b2.2","title_ru":"NoSQL базы данных","title_kk":"NoSQL дерекқорлары","lessons":[{"id":"l07","number":7,"title_ru":"Масштабирование и многоуровневое хранение данных","title_kk":"Масштабтау және деректерді көпдеңгейлі сақтау","sources":["lecture-07","practice-07"],"elements":{"theory":{"file":"lessons/07/theory.html","chars":12556,"images":4},"examples":{"file":"lessons/07/examples.html","chars":1633,"images":0},"tasks":{"file":"lessons/07/tasks.html","chars":1317,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/07/questions.json","count":5},"tests":{"file":"lessons/07/tests.json","count":10}}},{"id":"l08","number":8,"title_ru":"MongoDB","title_kk":"MongoDB","sources":["lecture-08","practice-08"],"elements":{"theory":{"file":"lessons/08/theory.html","chars":3988,"images":0},"examples":{"file":"lessons/08/examples.html","chars":1488,"images":0},"tasks":{"file":"lessons/08/tasks.html","chars":1193,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/08/questions.json","count":5},"tests":{"file":"lessons/08/tests.json","count":10}}}]}]},{"id":"m3","title_ru":"Визуализация и интеллектуальный анализ данных","title_kk":"Деректерді визуализациялау және зияткерлік талдау","blocks":[{"id":"b3.1","title_ru":"Визуализация данных и язык R","title_kk":"Деректерді визуализациялау және R тілі","lessons":[{"id":"l09","number":9,"title_ru":"Визуализация данных и результатов анализа","title_kk":"Деректер мен талдау нәтижелерін визуализациялау","sources":["lecture-09","practice-09"],"elements":{"theory":{"file":"lessons/09/theory.html","chars":4340,"images":0},"examples":{"file":"lessons/09/examples.html","chars":915,"images":0},"tasks":{"file":"lessons/09/tasks.html","chars":930,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/09/questions.json","count":5},"tests":{"file":"lessons/09/tests.json","count":10}}},{"id":"l10","number":10,"title_ru":"Графики и диаграммы","title_kk":"Графиктер мен диаграммалар","sources":["lecture-10","labs"],"elements":{"theory":{"file":"lessons/10/theory.html","chars":5787,"images":3},"examples":{"file":"lessons/10/examples.html","chars":1276,"images":0},"tasks":{"file":"lessons/10/tasks.html","chars":1805,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/10/questions.json","count":5},"tests":{"file":"lessons/10/tests.json","count":10}}},{"id":"l11","number":11,"title_ru":"Типы данных","title_kk":"Деректер типтері","sources":["lecture-11","practice-10","practice-11","labs"],"elements":{"theory":{"file":"lessons/11/theory.html","chars":8715,"images":0},"examples":{"file":"lessons/11/examples.html","chars":1690,"images":0},"tasks":{"file":"lessons/11/tasks.html","chars":4161,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/11/questions.json","count":5},"tests":{"file":"lessons/11/tests.json","count":10}}}]},{"id":"b3.2","title_ru":"Интеллектуальный и статистический анализ","title_kk":"Зияткерлік және статистикалық талдау","lessons":[{"id":"l12","number":12,"title_ru":"Классификация задач анализа данных","title_kk":"Деректерді талдау есептерінің жіктелуі","sources":["lecture-12","practice-12","labs"],"elements":{"theory":{"file":"lessons/12/theory.html","chars":8751,"images":1},"examples":{"file":"lessons/12/examples.html","chars":1038,"images":0},"tasks":{"file":"lessons/12/tasks.html","chars":1198,"images":0},"selfcheck":{"file":"lessons/12/selfcheck.html","chars":287,"images":0},"questions":{"file":"lessons/12/questions.json","count":6},"tests":{"file":"lessons/12/tests.json","count":10}}},{"id":"l13","number":13,"title_ru":"Статистические методы анализа данных","title_kk":"Деректерді талдаудың статистикалық әдістері","sources":["lecture-13","practice-13","labs"],"elements":{"theory":{"file":"lessons/13/theory.html","chars":10750,"images":0},"examples":{"file":"lessons/13/examples.html","chars":1461,"images":0},"tasks":{"file":"lessons/13/tasks.html","chars":2473,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/13/questions.json","count":5},"tests":{"file":"lessons/13/tests.json","count":10}}}]},{"id":"b3.3","title_ru":"Классификация и кластеризация","title_kk":"Жіктеу және кластерлеу","lessons":[{"id":"l14","number":14,"title_ru":"Метрический классификатор","title_kk":"Метрикалық классификатор","sources":["lecture-14","labs"],"elements":{"theory":{"file":"lessons/14/theory.html","chars":4086,"images":0},"examples":{"file":"lessons/14/examples.html","chars":1400,"images":0},"tasks":{"file":"lessons/14/tasks.html","chars":2401,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/14/questions.json","count":5},"tests":{"file":"lessons/14/tests.json","count":10}}},{"id":"l15","number":15,"title_ru":"Алгоритм K-means","title_kk":"K-means алгоритмі","sources":["lecture-15","practice-14","practice-15","labs"],"elements":{"theory":{"file":"lessons/15/theory.html","chars":5703,"images":6},"examples":{"file":"lessons/15/examples.html","chars":1717,"images":0},"tasks":{"file":"lessons/15/tasks.html","chars":1292,"images":0},"selfcheck":{"file":null,"chars":0,"images":0},"questions":{"file":"lessons/15/questions.json","count":5},"tests":{"file":"lessons/15/tests.json","count":10}}}]}]}],"labs":[{"id":"A1","title":"Введение в RStudio","lesson":11},{"id":"A2","title":"Обработка данных","lesson":11},{"id":"A3","title":"Анализ данных","lesson":13},{"id":"A4","title":"Визуализация данных","lesson":10},{"id":"A5","title":"Моделирование данных","lesson":14},{"id":"B1","title":"Основы работы с RStudio","lesson":11},{"id":"B2","title":"Работа с данными","lesson":11},{"id":"B3","title":"Очистка данных","lesson":11},{"id":"B4","title":"Основные статистики","lesson":13},{"id":"B5","title":"Визуализация данных","lesson":10},{"id":"B6","title":"Сводные таблицы","lesson":11},{"id":"B7","title":"Фильтрация и сортировка данных","lesson":11},{"id":"B8","title":"Работа с датами","lesson":11},{"id":"B9","title":"Линейная регрессия","lesson":14},{"id":"B10","title":"Кластеризация","lesson":15},{"id":"B11","title":"Работа с текстовыми данными","lesson":12},{"id":"B12","title":"Временные ряды","lesson":13},{"id":"B13","title":"Корреляция и ковариация","lesson":13},{"id":"B14","title":"Оценка модели","lesson":14}]},"lessons":{"01":{"theory":"<h3>Большие данные: определение</h3>\n<p>Большие данные – комплексный набор методов, подходов и инструментов обработки структурированных и неструктурированных данных колоссальных объемов. Главной целью обработки Big Data является быстрое и эффективное использование всех видов информации в условиях непрерывного изменения и прироста в больших объёмах.</p>\n<p>Говоря простым языком, Big data представляет собой безмерный объем информации, который не может быть обработан стандартными инструментами и аппаратными средствами. Основными задачами Big Data являются хранение и обработка информации гигантских объёмов данных.</p>\n<p>Большие данные по сравнению с обычными данными требуют иной подход к обработке. При обработке Big data используются собственные инструменты и технологии, которые предназначены для данных со сверхбольшим объёмом информации.</p>\n<br/>\n<h3>Big Data терминология</h3>\n<p>Термин Big Data был предложен Клиффордом Линчем (Clifford Lynch) (рисунок 1.1), редактором журнала Nature, который 3 сентября 2008 года выпустил отдельный номер, главной темой которого была «Как могут повлиять на будущее науки, технологии, открывающие возможности работы с большими объёмами данных?» (Оригинал: «Big data: How do your data grow?»). Термин «Большие данные» был предложен по аналогии с терминами «Большая нефть», «Большая руда» и т. д.</p>\n<p>Размер больших данных в 2012 году определялся от нескольких десятков терабайт до петабайт (250). Термин большие данные может быть причислен к данным, связанным с высочайшей изменчивостью источников данных, а также обладающим сложными взаимосвязями и трудностями изменения или удаления отдельных записей. Большие данные характеризуются гигантским объёмом, значительной скоростью поступления данных, а также</p>\n<p>многообразием самих данных. Для таких данных требуются новейшие способы обработки, которая в дальнейшем может привести к улучшению методов принятия решений, оптимизации процессов и поиска закономерностей.</p>\n<img src=\"images/lecture-01-01.jpg\"/>\n<p>Рисунок 1.1 – Клиффорд Линч</p>\n<h3>История появления термина Big Data</h3>\n<p>К 2011 году понятие Big Data стало набирать популярность, в основном, в крупных корпорациях таких как Microsoft, IBM, Oracle, EMC, HP и др.</p>\n<p>В 2011 году исследовательская компания Gartner отмечает большие данные как тренд номер два в информационно-технологической инфраструктуре после виртуализации. По прогнозам подразумевается, что внедрение технологий Big Data крупно повлияет на информационные технологии в сферах производства, здравоохранении, торговли, государственного управлении, а также в отраслях, в которых регистрируются индивидуальные перемещения ресурсов. С 2013 года большие данные начинают преподавать в университетах в рамках вузовских программ по науке о данных, вычислительным наукам и инженерии.</p>\n<br/>\n<h3>Причины появления Big Data</h3>\n<p>Инновационные разработки в области Big Data начинались не в маленьких стартапах, как это часто бывает в IT-индустрии, а в больших компаниях. Так, например, технология распределенной обработки данных MapReduce была разработана компанией Google, a Hadoop, являющийся</p>\n<p>свободным программным обеспечением для выполнения распределенных вычислений на кластерах из сотен и тысяч узлов, сразу после создания активно поддержала компания Yahoo. Большинство программных продуктов в области Big Data являются свободными, а их адаптацией и продвижением занимаются те самые стартапы. Традиционные поставщики решений в области хранения и обработки данных, такие как IBM и 3</p>\n<p>EMC внимательно относятся к новым разработкам в области Больших Данных и стараются использовать их в своих продуктах совместно с собственными технологиями.</p>\n<h3>Характеристики Big Data</h3>\n<p>Существует множество характеристик для Больших данных, но здесь будут рассматриваться самые основные.</p>\n<p>Сфера Больших Данных характеризуется следующими признаками: Volume (объем): накопленная база данных представляет собой гигантский объем информации, для которого обработка и хранение традиционными способами являются трудоёмкими процессами. Такой объем нуждается в новых подходах и в более усовершенствованных инструментах.</p>\n<ul><li><p>Velocity (скорость): данный признак указывает как на увеличивающуюся скорость накопления, так и на скорость обработки данных. В последнее время стали более востребованы технологии обработки данных в реальном времени.</p></li><li><p>Variety (многообразие): данная характеристика означает возможность одновременной обработки структурированной и неструктурированной информации различных форматов. Главным отличием структурированной информации является возможность классификации. Примером такой информации может служить информация о клиентских транзакциях.</p></li><li><p>Veracity (достоверность данных): в настоящее время достоверность имеющихся данных является важнейшим критерием для пользователей. Недостоверная информация приводит к затруднению анализа данных.</p></li><li><p>Value (ценность накопленной информации): Большие Данные должны быть полезны в усовершенствовании бизнес-процессов, составлении отчетности или оптимизации расходов компаний.</p></li></ul>\n<p>Первые три характеристики определяют так называемый принцип «Трёх V» (рисунок 1.2).</p>\n","examples":"<h3>Пример 1. Оценка набора данных по модели «5V»</h3>\n<p><strong>Ситуация.</strong> Интернет-магазин ежедневно записывает 40 млн событий: клики, просмотры товаров, добавления в корзину. Кроме того, приходят отзывы покупателей (свободный текст), фотографии товаров и данные платёжной системы. События поступают непрерывно, рекомендации покупателю нужно показывать в течение секунды.</p><p><strong>Разбор по характеристикам:</strong></p><ul><li><strong>Volume (объём)</strong> — 40 млн событий в сутки за несколько лет дают сотни терабайт; хранить и обрабатывать их на одном сервере традиционной СУБД трудоёмко.</li><li><strong>Velocity (скорость)</strong> — данные поступают потоком, а рекомендация нужна почти в реальном времени.</li><li><strong>Variety (многообразие)</strong> — одновременно есть структурированные данные (транзакции), неструктурированные (тексты отзывов) и мультимедийные (фотографии).</li><li><strong>Veracity (достоверность)</strong> — часть кликов делают боты, в отзывах встречается спам; без очистки выводы будут искажены.</li><li><strong>Value (ценность)</strong> — анализ поведения позволяет повысить продажи за счёт персональных рекомендаций.</li></ul><p><strong>Вывод.</strong> Набор данных обладает всеми тремя признаками «Трёх V» (объём, скорость, многообразие), поэтому для его обработки нужны технологии больших данных, а не только традиционная реляционная СУБД.</p>\n<h3>Пример 2. Перевод единиц объёма данных</h3>\n<p><strong>Задача.</strong> Wal-Mart каждый час пополняет базу данных на 2,5 петабайта. Сколько это терабайт и сколько данных накопится за сутки?</p><p><strong>Решение.</strong></p><ol><li>Используем десятичные приставки: 1 ПБ = 10<sup>15</sup> байт, 1 ТБ = 10<sup>12</sup> байт, следовательно 1 ПБ = 1000 ТБ.</li><li>2,5 ПБ = 2,5 × 1000 = <strong>2500 ТБ</strong> в час.</li><li>За сутки: 2,5 ПБ × 24 = <strong>60 ПБ</strong>, то есть 0,06 эксабайта (1 ЭБ = 1000 ПБ).</li></ol><p><strong>Замечание.</strong> В двоичной системе 1 ПБ = 2<sup>50</sup> байт ≈ 1,126 × 10<sup>15</sup> байт. Для оценок масштаба разница несущественна, но в расчётах всегда указывайте, какую систему вы используете.</p>\n","tasks":"<h3>Задание 1. Классификация источников данных</h3>\n<p><strong>Цель:</strong> Научиться отличать структурированные данные от неструктурированных и оценивать источники по характеристикам Big Data.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Выберите организацию (банк, больница, университет, магазин или другую).</li>\n<li>Перечислите не менее 6 источников данных этой организации.</li>\n<li>Для каждого источника укажите тип данных: структурированные, слабоструктурированные или неструктурированные.</li>\n<li>Оцените каждый источник по признакам Volume, Velocity и Variety: высокий, средний или низкий уровень.</li>\n<li>Сделайте вывод, какие источники требуют технологий больших данных и почему.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Таблица из 6 и более строк и обоснованный вывод (3–5 предложений).</p>\n<p><strong>Форма представления:</strong> Таблица со столбцами: «Источник», «Тип данных», «Volume», «Velocity», «Variety», «Комментарий»; ниже — вывод.</p>\n<details class='hint'><summary>Подсказка</summary><p>Структурированные данные легко разложить по столбцам таблицы (например, транзакции). Тексты, изображения, видео и аудио — неструктурированные.</p></details>\n<h3>Задание 2. Расчёт объёма данных</h3>\n<p><strong>Цель:</strong> Закрепить навык перевода единиц измерения объёма информации.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Google обрабатывает 5 ПБ данных в час. Вычислите объём данных, обрабатываемый за сутки и за год (365 дней).</li>\n<li>Переведите полученные значения в эксабайты и зеттабайты (используйте десятичные приставки).</li>\n<li>Сравните годовой объём с суммарным объёмом информации на Земле (около 1 ЗБ, по данным лекции).</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Три числа с единицами измерения и одно предложение-сравнение.</p>\n<p><strong>Форма представления:</strong> Ход вычислений по шагам, итоговые значения выделены.</p>\n<details class='hint'><summary>Подсказка</summary><p>1 ЭБ = 1000 ПБ, 1 ЗБ = 1000 ЭБ.</p></details>\n","selfcheck":"","questions":[{"id":"q01-1","type":"single","level":1,"text":"Кто предложил термин Big Data?","options":["Клиффорд Линч","Аналитики Gartner","Разработчики Google","Компания Yahoo"],"correct":0,"explain":"Термин предложил Клиффорд Линч, редактор журнала Nature, в специальном номере от 3 сентября 2008 года."},{"id":"q01-2","type":"multiple","level":1,"text":"Какие характеристики входят в принцип «Трёх V»? Отметьте все верные.","options":["Volume","Velocity","Variety","Veracity","Value"],"correct":[0,1,2],"explain":"«Три V» — это объём (Volume), скорость (Velocity) и многообразие (Variety). Veracity и Value — дополнительные характеристики, расширяющие модель до «5V»."},{"id":"q01-3","type":"truefalse","level":1,"text":"Верно ли, что первые разработки в области Big Data появились в небольших стартапах?","correct":false,"explain":"Неверно. Инновации появились в крупных компаниях: MapReduce разработала Google, а Hadoop активно поддержала Yahoo."},{"id":"q01-4","type":"input","level":2,"text":"Какая характеристика Big Data отвечает за достоверность данных? Введите английское название.","answers":["Veracity"],"explain":"Veracity — достоверность. Недостоверные данные затрудняют анализ и приводят к ошибочным выводам."},{"id":"q01-5","type":"single","level":2,"text":"Система получает данные с датчиков 1000 раз в секунду и должна реагировать мгновенно. Какая характеристика Big Data здесь главная?","options":["Volume","Velocity","Variety","Value"],"correct":1,"explain":"Velocity описывает скорость поступления и обработки данных, в том числе обработку в реальном времени."},{"id":"q01-6","type":"input","level":2,"text":"В каком году компания Gartner назвала большие данные трендом номер два в ИТ-инфраструктуре? Введите год.","answers":["2011"],"explain":"В 2011 году Gartner поставила большие данные на второе место среди трендов после виртуализации."}],"tests":""},"02":{"theory":"<p><strong>Анализ данных </strong>– это совокупность методов и средств извлечения их организованных данных для принятия решений (рисунок 1.8-1.9).</p>\n<p><strong>Основные этапы анализа данных:</strong></p>\n<ol><li><p>Гипотеза</p></li><li><p>Сбор и систематизация данных</p></li><li><p>Подбор модели</p></li><li><p>Тестирование и интерпретация результатов</p></li><li><p>Использование</p></li></ol>\n<img src=\"images/lecture-02-01.png\"/>\n<img src=\"images/lecture-02-02.png\"/>\n<p><strong>Задачи, решаемые Big Data:</strong></p>\n<ul><li><p>Управление документами и доступом</p></li><li><p>Выявление мошенничества</p></li><li><p>Системы гарантирования доходов</p></li><li><p>Анализ текучести клиентов</p></li><li><p>Мониторинг интеллектуальных счётчиков</p></li><li><p>Мониторинг оборудования</p></li><li><p>Оптимизация ценовой политики</p></li><li><p>Оптимизация автомобильного движения</p></li><li><p>Анализ социальных сетей</p></li><li><p>Анализ поведения клиентов</p></li><li><p>Оптимизация ИТ инфраструктуры</p></li><li><p>Прогноз погоды</p></li><li><p>Разведка природных ресурсов</p></li><li><p>Управление контентом для предоставления в судебной практике</p></li><li><p>Аналитика в медицинских исследованиях</p></li><li><p>Управление гарантийными обязательствами</p></li><li><p>Анализ рекламных компаний</p></li><li><p>Оптимизация web</p></li><li><p>Исследования в области естественных наук</p></li><li><p>Статистика объёма данных</p></li></ul>\n<p>Каждый день в мире производится 2,5 квинтильона (1018) байтов данных. При этом 90% данных созданы за последние два года.</p>\n<p>Каждый час Wal-Mart совершает 1 миллион сделок, пополняя базу данных на 2,5 петабайта (1015) в 170 раз больше объема данных Библиотеки Конгресса США.</p>\n<p>Объем отправлений, доставляемых американской Почтовой службой за один год, равен 5 петабайтам, а Google обрабатывает такой же объем данных всего за один час.</p>\n<p>Суммарный объем всей существующей на земле информации составляет несколько больше одного зеттабайта (1021).</p>\n<p>Бизнесу во всем мире необходимо собрать, организовать, проанализировать все эти данные для достижения конкурентных преимуществ в конкретной сфере рынка, развития более эффективных деловых операций, увеличения удовлетворения запросов потребителей, выявления новых возможностей.</p>\n","examples":"<h2>Big data для операторов связи</h2>\n<br/><p>Для операторов связи методы больших данных рассматриваются в четырёх различных направлениях. Одни из них используются для улучшения внутренненой работы программы, другие играют роль дополнительного рыночного продукта для внешних клиентов.</p>\n<ul><li><p>высокоточный маркетинг (рrecise marketing) — адресное предложение продуктов и услуг тем потребителям, которые наиболее готовы к их приобретению (новые тарифные планы, дополнительные сервисы, платежные терминалы и пр.);</p></li><li><p>управление качеством услуг для клиента (Customer Experience Management) для повышения его удовлетворенности с целью предотвращения оттока пользователей;</p></li><li><p>оптимизация внутренней работы оператора и планирование развития (ROI-based Network Optimization and Planning) на основе учета всех объективных факторов и мнений потребителей с целью максимальных гарантий возврата инвестиций в кратчайшие сроки;</p></li><li><p>монетизация информационных активов (Data Asset Monetization) – продажа в той или иной форме (в том числе в виде долевого участия в проектах) имеющихся у оператора данных своим партнерам, чтобы они могли с их помощью решать свои задачи.</p></li></ul>\n<p>Развернув решение больших данных, мобильный оператор смог начать собирать и анализировать существенно больше информации о поведении и интересах своих клиентов, в том числе об интенсивности использования связи и географическом местоположении. Причем все эти сведения можно было увязывать с данными о работе самой сотовой сети, в том числе о ее загрузке, о возникающих сбоях и пр.</p>\n<p>Возможности применения подобных методов видны по полученным результатам. Так, в начале 2013 г. эффективность маркетинговых предложений (для клиентов, которые их приняли) при общей массовой рассылке составляла 0,7%. К концу года за счет простой сегментации абонентов (по возрасту, полу, сроку подписки) эта величина была доведена до 4%, а в течение 2014-го повышена сначала до 11% (учет интенсивности использования услуг и местоположение клиентов) и затем до 24% (учет предпочтительных вариантов получения предложения – голосовые звонки, SMS, э-почта, социальные сети и пр.). За год удалось сократить число нерезультативных обращений к клиентам на 11 млн., существенно снизив затраты на рекламные кампании.</p>\n<p>На основе анализа 85 параметров поведения абонентов была выделена «группа риска», потенциально готовая к уходу от услуг оператора. Внутри нее также была проведена определенная сегментация, и для каждой категории клиентов выработан комплекс мероприятий по повышению уровня их лояльности (скидки, другие тарифные планы, подарки и пр.). Заказчик провел исследование, разделив «группу риска» на две подгруппы: с первой проводились специальные действия по удержанию, с другой ничего не делалось. Анализ такой работы за год показал, что компания смогла существенно сократить отток своих действующих потребителей, удержав более 200 тыс. абонентов; при этом нужно учитывать, что стоимость удержания клиента всегда значительно ниже, чем привлечения нового пользователя.</p>\n<p>До использования больших данных расширение географической сети оператора фактически выполнялось только на основе информации о плотности застройки и населения, но внедрив это решение, China Unicom перешел к развитию свой деятельности на базе многофакторного анализа, который учитывал такие показатели, как реальная загруженность трафика и востребованность услуг (например, с учетом места работы людей), «ценность» клиентов (по уровню жизни), требования к качеству связи (расстояние между станциями приема), востребованность разных категорий услуг (от этого зависит использование различной аппаратуры) и пр.</p>\n<p>В плане монетизации клиентских данных для внешних партнеров были приведены два примера: во-первых, оптимизация размещения наружной рекламы, причем как в географическом плане (место проживания, работа или транспортные коммуникации нужных клиентов), так и с учетом времени для динамической рекламы (в зависимости от времени суток, дней недели и сезонов года состав публики может меняться), а во-вторых, аналогичные предложения по развитию торговых сетей (с учётом местоположения и ассортимента). Кроме того, очень выгодным оказывается целевая рассылка мобильной рекламы в реальном времени в соответствии с графиком занятости человека, его интересов и физического пребывания (например, рассылка информации о фильмах-боевиках, которыми клиент интересуется, именно в его свободное время и с учетом близлежащих кинотеатров). Общий отраслевой опыт показывает, что такие адресные методы позволяют повышать доходы от распространения рекламы в разы.</p>\n<br/>\n<h2>Big data в банках</h2>\n<p>Массовое внедрение технологий анализа больших данных осложнено тем, что банки зачастую используют разрозненные или просто устаревшие платформы. Тем не менее, уже есть примеры того, как сотрудники, отвечающие за информационную безопасность, предотвращали мошеннические операции. Помимо технологии Big Data эксперты также считают, что бороться с мошенниками позволяет внедрение современных систем идентификации пользователей. Одним из примеров является так называемая непрерывная поведенческая идентификация, анализирующая поведение клиентов на протяжении длительного времени. Это делается при помощи привязки счета к мобильному телефону.</p>\n<p>Большие данные способны решать практически все ключевые задачи банков: привлечение клиентов, повышение качества услуг, оценка заемщиков, противодействие мошенничеству и др. Повышая скорость и качество формирования отчетности, увеличивая глубину анализа данных, участвуя в противодействии отмыванию незаконных средств, эти технологии помогают банкам соответствовать требованиям регуляторов.</p>\n<p>Основные задачи, для которых банки используют технологии анализа больших данных, – это оперативное получение отчетности, скоринг, недопущение проведения сомнительных операций, мошенничества и отмывания денег, а также персонализация предлагаемых клиентам банковских продуктов.</p>\n<p>Технологии больших данных применяются в основном для анализа клиентской среды. Дмитрий Шепелявый, заместитель генерального директора SAP СНГ, приводит несколько примеров: «Американский банк PNC данные о поведении своих клиентов на сайтах, информацию о покупках и образе жизни конвертирует в политику гибкого начисления процентных ставок, которая в итоге выражается в цифрах роста капитализации. Commonwealth Bank of Australia (CBA) анализирует все транзакции своих вкладчиков, дополняя этот анализ сбором данных о них в социальных сетях. Связав эти потоки данных, банк добился значительного снижения процента неуплаты по кредитам. А в России интересен опыт Уральского банка реконструкции и развития – они стали работать с информацией по клиентской базе для создания кредитных предложений, вкладов и других услуг, которые могут максимально заинтересовать конкретного клиента. Примерно за год применения ИТ-решений розничный кредитный портфель УБРиР вырос примерно на 55%».</p>\n<h2>Европейские программы, связанные с Big Data</h2>\n<ul><li><p>GRDI2020: Глобальная инфраструктура исследовательских данных (GRDI) в 10-летней перспективе. Инфраструктура разрабатывается для использования накапливаемых данных и знаний, производимых научным сообществом</p></li><li><p>ESFRI: Европейский стратегический форум в области исследовательских инфраструктур. Дорожная карта ESFRI 2010 ориентирована на инвестирование €20b, включая ежегодные €2b операционных затрат для поддержки стратегических политик для Пан-Европейских исследовательских инфраструктур</p></li><li><p>SIENA: Стандарты и интероперабельность в инициативе реализациии e- инфраструктур. Посвящена открытым, стандартизованным, интероперабельным грид и облачным вычислительным инфраструктурам</p></li><li><p>VENUS-C: Виртуальные многодисциплинарные среды, использующие облачные инфраструктуры. Совместная программа промышленных партнеров и научного сообщества пользователей облачных инфраструктур. Охватывает 10 тематических областей: биоразнообразие, химию, строительство и архитектуру, гражданскую оборону, науки о земле, социальные медиа, математику, механику и аэрокосмическую технику, здравоохранение, генетическую биологию, астрофизику.</p></li></ul>\n\n<h3>Пример 3. Этапы анализа данных на задаче оттока клиентов</h3>\n<p><strong>Ситуация.</strong> Мобильный оператор теряет клиентов и хочет понять, кто уйдёт в ближайший месяц. Пройдём все пять этапов анализа данных.</p><ol><li><strong>Гипотеза.</strong> Клиенты, у которых в последние месяцы снизилась активность и выросло число сбоев связи, чаще уходят.</li><li><strong>Сбор и систематизация данных.</strong> Объединяем данные биллинга, журналы сети (сбои), обращения в поддержку, сведения о тарифе и сроке подписки.</li><li><strong>Подбор модели.</strong> Выбираем модель классификации «уйдёт / не уйдёт» на основе 85 параметров поведения абонента.</li><li><strong>Тестирование и интерпретация.</strong> Проверяем модель на данных прошлого года: выделенная «группа риска» действительно ушла чаще. Определяем, какие признаки наиболее важны.</li><li><strong>Использование.</strong> Для группы риска запускаем программы удержания (скидки, другие тарифы); сравниваем с контрольной группой.</li></ol><p><strong>Результат</strong> (по данным примера China Unicom из раздела «Примеры»): удержано более 200 тыс. абонентов, а удержание клиента всегда дешевле привлечения нового.</p>\n<h3>Пример 4. Расчёт эффекта сегментации</h3>\n<p><strong>Задача.</strong> Оператор отправляет 1 000 000 маркетинговых предложений. При массовой рассылке откликаются 0,7% клиентов, после сегментации по возрасту, полу и сроку подписки — 4%. Сколько дополнительных откликов даёт сегментация?</p><p><strong>Решение.</strong></p><ul><li>Массовая рассылка: 1 000 000 × 0,007 = 7 000 откликов.</li><li>С сегментацией: 1 000 000 × 0,04 = 40 000 откликов.</li><li>Прирост: 40 000 − 7 000 = <strong>33 000</strong> откликов, то есть эффективность выросла в 40 000 / 7 000 ≈ <strong>5,7 раза</strong>.</li></ul><p><strong>Вывод.</strong> Даже простая сегментация на основе данных о клиентах многократно повышает отдачу; учёт местоположения и предпочтительного канала связи повышает её ещё сильнее (до 24% в примере).</p>\n","tasks":"<h3>Задание 1. Применение Big Data в отрасли</h3>\n<p><strong>Цель:</strong> Научиться связывать задачи бизнеса с задачами, решаемыми Big Data.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Выберите три задачи из списка «Задачи, решаемые Big Data» (например, выявление мошенничества, анализ текучести клиентов, прогноз погоды).</li>\n<li>Для каждой задачи укажите отрасль, источники данных и ожидаемый результат анализа.</li>\n<li>Для одной из задач опишите все пять этапов анализа данных: гипотеза, сбор, модель, тестирование, использование.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Описание трёх задач и подробная схема анализа для одной из них.</p>\n<p><strong>Форма представления:</strong> Таблица «Задача — Отрасль — Источники данных — Результат» и нумерованный список из пяти этапов.</p>\n<details class='hint'><summary>Подсказка</summary><p>Ориентируйтесь на примеры операторов связи и банков из раздела «Примеры».</p></details>\n<h3>Задание 2. Оценка эффективности маркетинга</h3>\n<p><strong>Цель:</strong> Научиться количественно оценивать пользу анализа данных.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Используя данные примера оператора связи (0,7%, 4%, 11%, 24%), рассчитайте число откликов на 500 000 предложений для каждого уровня.</li>\n<li>Вычислите, во сколько раз каждый следующий уровень эффективнее массовой рассылки.</li>\n<li>Сделайте вывод, какие данные дали наибольший прирост.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Четыре значения числа откликов, три коэффициента роста и вывод.</p>\n<p><strong>Форма представления:</strong> Таблица с расчётами и вывод из 2–3 предложений.</p>\n","selfcheck":"","questions":[{"id":"q02-1","type":"single","level":1,"text":"С какого этапа начинается анализ данных?","options":["Сбор и систематизация данных","Гипотеза","Подбор модели","Использование"],"correct":1,"explain":"Анализ начинается с гипотезы: сначала формулируют, что именно хотят проверить, и только затем собирают данные."},{"id":"q02-2","type":"input","level":2,"text":"Сколько байтов данных производится в мире каждый день, по данным лекции? Ответ введите в квинтильонах (число).","answers":["2,5","2.5"],"explain":"Каждый день производится 2,5 квинтильона (10^18) байтов данных."},{"id":"q02-3","type":"multiple","level":2,"text":"Какие задачи банки решают с помощью технологий больших данных? Отметьте все верные.","options":["Скоринг заёмщиков","Противодействие мошенничеству","Персонализация продуктов","Печать бумажных выписок"],"correct":[0,1,2],"explain":"Банки используют Big Data для отчётности, скоринга, борьбы с мошенничеством и отмыванием денег, а также для персонализации продуктов. Печать выписок не является задачей анализа данных."},{"id":"q02-4","type":"truefalse","level":1,"text":"Верно ли, что 90% мировых данных созданы за последние два года (по данным лекции)?","correct":true,"explain":"Верно, в лекции приводится именно эта оценка: большая часть данных создана совсем недавно."},{"id":"q02-5","type":"single","level":3,"text":"Какое направление использования Big Data у операторов связи означает продажу данных партнёрам?","options":["Precise marketing","Customer Experience Management","ROI-based Network Optimization","Data Asset Monetization"],"correct":3,"explain":"Data Asset Monetization — монетизация информационных активов, то есть продажа данных партнёрам в той или иной форме."}],"tests":""},"03":{"theory":"<br/>\n<p>Приведем жизненный пример того, как и при каких условиях необходимо производить анализ данных.</p>\n<p>Представим, для аналитика стоит задача оценить продажи ряда магазинов (куда поставляется товар) и каждый магазин ведет свой учет проданных товаров. Реальность такова, что формы учета будут заполнены разными способами, то есть у них будет разная структура и разный формат хранения (некоторая форма таблиц).</p>\n<p>Решим эту задачу способом, который первый приходит в голову, то есть предоставим простейший способ решения данной задачи. Пусть у нас есть N таблиц и нам нужно их собрать вместе в одну таблицу. Напишем N скриптов, которые преобразуют эти таблицы, и один сборщик, который собирает их вместе. У такого подхода есть положительные и отрицательные стороны. К минусам можно отнести: необходимо поддерживать N скриптов одновременно (где N в порядках тысяч); при изменении структуры отчетов магазинов во времени (например, в магазине появился новый сотрудник) необходимо искать и переписывать отдельные скрипты; при появлении нового магазина, необходимо писать новый скрипт; при изменении формата отчетности необходимо вносить изменения во все скрипты; сложная отладка и поддержка, так как магазины не уведомляют об изменении структуры и не следуют никаким спецификациям.</p>\n<p>Немного усложним задачу и приблизим ее к реалиям современных компаний. Итак, производитель товаров на самом деле работает не напрямую с магазинами, а через некоторых посредников. Посредники посещают магазины и непосредственно своими действиями пытаются стимулировать продажи. Соответственно, они являются материально заинтересованными лицами и информацию, которую они выдают, приходится перепроверять.</p>\n<p>На основании вышесказанного давайте переформулируем задачу. Пусть у нас есть N магазинов и K дистрибьюторов. Можем ли мы агрегировать</p>\n<br/>\n<p>данные магазинов и сравнить их с результатами дистрибьюторов? При этом у всех данные имеют разную структуру и формат.</p>\n<p>Эта задача обладает несколькими основными характеристиками. Входные данные представляют собой огромное количество разнообразных форматов, к которым добавляются отчеты дистрибьюторов. Как правило, задача характеризуется очень низким качеством данных, в том числе дублированием, несогласованностью и ошибками. На основе полученных результатов и сравнения данных отдел по закупкам принимает решения о том, сколько, что, кому и по какой цене отгружать. То есть решение этой задачи непосредственно влияет на финансовые показатели компании, что безусловно важно.</p>\n<p>Существуют также другие варианты решения подобной задачи. Например, самописное решение. Компании производителю будет необходимо нанять специалиста не по профилю компании и критичное ПО будет зависеть от данного специалиста. Если он уйдет, то компания будет вынуждена срочно искать замену, которая сможет поддерживать ПО, и качество будет напрямую зависеть от нанятого специалиста.</p>\n<p>Также всегда есть возможность закупить ПО у третьей стороны. Отрицательной стороной такого подхода являются цена, качество и время интеграции. Как правило, цена и время интеграции слишком высоки для среднего производителя и в том числе требует существенных временных затрат сотрудников. Выбор поставщика также не тривиален.</p>\n<p>Есть вариант применить SaaS решения, но методология еще нова для рынка и многие компании скептически относятся к подобным сервисам.</p>\n<p>Процесс анализа на уровне компании в общем случае выглядит следующим образом: данные консолидируются, определенным образом трансформируются (агрегируются) и загружаются в систему для анализа.</p>\n<h2>Business Intelligence</h2>\n<p>Термин Business Intelligence был введен аналитиками Gartner как</p>\n<p>«процесс, ориентированный на бизнес-пользователя и включающий доступ и</p>\n<br/>\n<p>исследование информации, ее анализ, выработку интуиции и понимания, которые ведут к улучшенному и неформальному принятию решений».</p>\n<p>Иными словами, можно сказать, что BI – это методы и инструменты для перевода необработанной информации в осмысленную, удобную форму. При этом технологии BI обрабатывают большие объемы неструктурированных данных, чтобы найти стратегические возможности для бизнеса.</p>\n<p>Business Intelligence имеет отношение к процессу превращения данных в знания, а знаний - в действия бизнеса для получения выгоды; является деятельностью конечного пользователя, которую облегчают различные аналитические и групповые инструменты и приложения, а также инфраструктура хранилища данных.</p>\n<p>Главная цель BI состоит в том, чтобы интерпретировать большое количество данных, заостряя внимание лишь на ключевых факторах эффективности, моделируя исход различных вариантов действий, отслеживая результаты принятия решений.</p>\n<h2>BI-платформа</h2>\n<p>Для анализа данных на сегодняшний день существует множество решений. BI-платформа – это такая программа, которая предоставляет пользователю удобные инструменты анализа фактически любых данных (будь то файл Excel либо промышленное хранилище данных). Проще говоря, BI- платформа – это продвинутая система отчетности.</p>\n<p>Современные системы класса BI располагают следующими основными функциями: возможность подключения к различным источникам данных (от файла Excel до универсального ODBC подключения); возможность построения как простых отчетов (типа график или таблица), так и сложных параметризированных отчетов с комбинированной структурой и ссылочными связями (Drill-Trough, Drill-Up/Drill-Down); возможность прозрачной работы с разными источниками данных (например, Excel и SQL Server) с полноценной обработкой связей между ними; возможность интерактивной работы с данными (формирование отчетов «на лету»); возможность представления реляционных</p>\n<br/>\n<p>данных как многомерные; возможность распределения прав доступа, используя как внутренние источники аутентификации, так и внешние (NTLM, LDAP и т. д.); возможность запуска формирования отчетов как вручную, так и автоматически по расписанию; возможность автоматической рассылки сформированных отчетов; возможность построения отчетов в различных форматах (Excel, HTML, PDF и т. д.).</p>\n<p>BI состоит из множества компонентов и обладает различными характеристиками: многомерная агрегация и размещение данных в хранилищах; денормализация баз данных; маркировка и стандартизация данных (ETL); отчетность в режиме реального времени с аналитическими оповещениями; статистические выводы и вероятностное моделирование.</p>\n<p>BI должна быть разделена на этапы: информационный поиск, аналитическая обработка в реальном времени (OLAP), предупреждения об отклонениях от ожидаемых показателей, бизнес-аналитика, бизнес-отчётность.</p>\n<p>Разница между Business Intelligence и аналитикой заключается в том, что последняя включает в себя комплекс методов для анализа уже чистых данных. В отличии от аналитики, основная задача BI – принятие решений для бизнеса.</p>\n<h2>ETL-процесс</h2>\n<p>В области аналитики данных часто употребляется аббревиатура ETL (Extract, Transform, Load). Это термин, который переводится с английского дословно как «извлечение, преобразование, загрузка», является одним из основных процессов в управлении хранилищами данных.</p>\n<p>С точки зрения процесса ETL, архитектуру хранилища данных можно представить в виде трёх компонентов: источник данных, который содержит структурированные данные в виде таблиц, совокупности таблиц или просто файла (данные в котором разделены символами-разделителями); промежуточная область, содержащая вспомогательные таблицы, создаваемые временно и исключительно для организации процесса выгрузки; получатель данных, который является хранилищем данных или базой данных, в которую должны быть помещены извлечённые данные.</p>\n<br/>\n<h2>Средства BI</h2>\n<p>В соответствии с подходом аналитиков выделяют три основных типа инструментальных средств BI: средства предоставления информации, средства интеграции, средства анализа.</p>\n<p>Средства предоставления информации подразделяются на средства создания отчетов, которые дают возможность создавать форматированные интерактивные отчеты, и на информационные панели показателей, являющиеся одной из составных частей отчетов, представляющие информацию в виде интуитивно понятного графического изображения, включая диаграммы, круговые шкалы, светофоры и т.п. Также существуют такие инструменты, как генераторы нерегламентированных запросов – данная функция, известная также как создание отчетов в режиме самообслуживания, дает пользователям возможность получать ответы на возникающие вопросы.</p>\n<p>Наряду со средствами создания отдельных BI-приложений, BI- платформа должна предоставлять средства программной разработки для интеграции приложений в общий бизнес-процесс или обеспечивать их встраивание в другое приложение. BI-платформа должна давать разработчикам возможность создания BI-приложений без кодирования, на основе применения мастеров для визуального редактирования.</p>\n<h2>OLAP</h2>\n<p>Одним из средств анализа данных является технология OLAP (Online Analytical Processing — Оперативная аналитическая обработка данных). Это класс приложений и технологий, предназначенных для сбора, хранения и анализа многомерных данных в целях поддержки принятия управленческих решений. Технология OLAP позволяет аналитикам, менеджерам и управляющим сформировать свое собственное видение данных, используя быстрый, единообразный, оперативный доступ к разнообразным формам представления информации.</p>\n<p>Одновременный анализ по нескольким измерениям определяется как многомерный анализ. Каждое измерение включает направления консолидации</p>\n<br/>\n<p>данных, состоящие из последовательных уровней обобщения, где каждый вышестоящий уровень соответствует большей степени агрегации данных по соответствующему измерению.</p>\n<p>OLAP представляет собой инструмент для анализа больших объемов данных в режиме реального времени и обеспечивает следующие возможности работы с многомерными данными: гибкий просмотр информации, произвольные срезы данных, детализация, свертка или консолидация, вращение, сравнение во времени.</p>\n<h2>OLAP - Многомерный куб</h2>\n<p>В ячейках многомерного куба помещаются числовые параметры, предназначенные для анализа, например, объемов продаж. Измерениями OLAP- куба могут служить такие параметры, как время, продукты, регионы, продавцы. Продажи по времени в консолидированном виде могут представляться по годам, при детализации – по кварталам, месяцам и дням.</p>\n<br/>\n<h3>Построение модели</h3>\n<p>Жизненный цикл аналитики данных – это последовательность действий, которую нужно выполнить на наборе входных данных для эффективного достижения цели аналитики с помощью выбранных методов анализа. Жизненный цикл аналитики данных может включать в себя: выявление проблем анализа данных, сбор набора данных, проектирование, анализ данных, визуализацию данных.</p>\n<p>Для начала необходимо понять, какова реальная конечная цель проекта, какую пользу он может принести, оценить его критерии успешности или провала, выбрать технологии для сбора, трансформации и анализа данных. Нужно постараться ответить на такие дополнительные вопросы: достаточно ли у вас ресурсов на реализацию проекта? с кем вы будете контактировать по ходу проекта? достаточно ли у вас входных данных? были ли уже в компании попытки анализа? достаточно ли у вас времени на реализацию проекта? с какими проблемами вы можете столкнуться?</p>\n<p>В этап выявления проблемы (изучения) входят также такие пункты: определение набора необходимых знаний, которые нужны для ориентации в предметной области; наличие доступных ресурсов (люди, инструменты, данные); структурирование данных с точки зрения аналитики; изучение истории бизнеса.</p>\n<p>После изучения следует перейти к подготовке данных. Определите используемые программные средства, то есть выберите ПО, БД, инструменты анализа и визуализации. Получите, очистите и загрузите данные в систему, после чего оцените количество и качество данных.</p>\n<p>На этапе проектирования модели нужно определить методы, технологии, рабочие процессы, необходимые для расчета модели и объем данных. Также важно определить корреляцию между переменными: столбцами таблиц и полями данных.</p>\n<p>Построение модели заключается в том, чтобы разработать наборы данных для тестирования, обучения и производства. Затем оценить жизнеспособность и надежность данных для использования в модели. И в конечном итоге выбрать рабочее окружение, то есть аппаратные и программные средства, на которых можно настроить процесс.</p>\n<p>В результате предыдущего шага получились некие результаты. Теперь необходимо определить, удалось ли вам достичь результата на основе критериев проекта, а также определить ключевые результаты исследования. В зависимости от целевой аудитории можно разработать диаграммы и графики и сформулировать итоги и рекомендации.</p>\n<p>Последний этап – практическая реализация. В процессе этого этапа происходит доставка финальных рекомендаций, отчетов, кода и технических документов, запуск пилотного проекта, реализация модели в производственной среде и интеграция аналитических оценок в панель управления или в операционной системе.</p>\n<p>Начиная работать с большими данными, многие сталкиваются с трудностями, которые можно избежать, выполняя простейшие советы, такие как: всегда проводить глубокое изучение предметной области, разбивать задачу на более мелкие, делать аналитику гибкой и масштабируемой, предусмотреть возможность повторения каждого из этапов с возможностью внесения изменений в предыдущий этап, быть готовым к негативному результату, внимательно оценивать затраченное время на каждый этап.</p>\n","examples":"<h3>Пример 5. ETL-процесс для отчётов магазинов</h3>\n<p><strong>Ситуация.</strong> Три магазина присылают отчёты о продажах в разных форматах: магазин А — Excel с колонками «Дата, Товар, Кол-во», магазин Б — CSV с разделителем «;» и датой в формате ДД.ММ.ГГГГ, магазин В — CSV, где цена указана в тиынах.</p><p><strong>Extract (извлечение).</strong> Файлы загружаются из источников в промежуточную область без изменений.</p><p><strong>Transform (преобразование).</strong> В промежуточной области:</p><ul><li>названия колонок приводятся к единому виду: <code>date, store, product, qty, price</code>;</li><li>даты переводятся в формат ГГГГ-ММ-ДД;</li><li>цены магазина В делятся на 100, чтобы перевести их в тенге;</li><li>удаляются дубликаты и строки с пустым названием товара.</li></ul><p><strong>Load (загрузка).</strong> Очищенные строки загружаются в таблицу хранилища <code>sales</code>.</p><p><strong>Почему это лучше N отдельных скриптов.</strong> Правила преобразования описаны один раз для каждого формата; при появлении нового магазина достаточно добавить правило сопоставления колонок, а не писать новый скрипт целиком.</p>\n<h3>Пример 6. Операции OLAP на кубе продаж</h3>\n<p>Куб имеет три измерения: <strong>Время</strong> (год → квартал → месяц), <strong>Регион</strong> (страна → город), <strong>Товар</strong>; в ячейках — сумма продаж.</p><ul><li><strong>Срез:</strong> зафиксировать «Год = 2024» — получаем двумерную таблицу «Регион × Товар».</li><li><strong>Детализация (drill-down):</strong> перейти от 2024 года к его кварталам, чтобы увидеть, в каком квартале был спад.</li><li><strong>Свёртка (консолидация, drill-up):</strong> объединить города в страны.</li><li><strong>Вращение:</strong> поменять местами строки и столбцы: «Товар × Регион» вместо «Регион × Товар».</li><li><strong>Сравнение во времени:</strong> сопоставить продажи I квартала 2024 и I квартала 2025.</li></ul><p>Каждая операция выполняется мгновенно, потому что агрегаты по уровням обобщения рассчитаны заранее.</p>\n","tasks":"<h3>Задание 1. Проектирование ETL-процесса</h3>\n<p><strong>Цель:</strong> Научиться описывать этапы извлечения, преобразования и загрузки данных.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Придумайте 3 источника с разной структурой (например, журнал посещаемости в Excel, выгрузка из LMS в CSV, анкета в Google Forms).</li>\n<li>Опишите для каждого источника: формат, ключевые поля, возможные ошибки (дубликаты, пропуски, разные форматы дат).</li>\n<li>Определите целевую структуру таблицы хранилища.</li>\n<li>Распишите правила преобразования для каждого источника.</li>\n<li>Укажите, что произойдёт при появлении четвёртого источника.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Схема ETL из трёх компонентов (источник, промежуточная область, получатель) и правила преобразования.</p>\n<p><strong>Форма представления:</strong> Схема (рисунок или таблица) и список правил.</p>\n<details class='hint'><summary>Подсказка</summary><p>Вспомните пример с N магазинами и K дистрибьюторами из теории.</p></details>\n<h3>Задание 2. Многомерный анализ</h3>\n<p><strong>Цель:</strong> Освоить операции OLAP на учебном кубе.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Задайте куб с измерениями «Время», «Факультет», «Курс» и показателем «Средний балл».</li>\n<li>Для каждой операции (срез, детализация, свёртка, вращение, сравнение во времени) сформулируйте один вопрос, на который она отвечает.</li>\n<li>Укажите иерархию уровней обобщения для измерения «Время».</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Пять вопросов с указанием операции OLAP и иерархия измерения.</p>\n<p><strong>Форма представления:</strong> Таблица «Операция — Вопрос — Что меняется в кубе».</p>\n","selfcheck":"","questions":[{"id":"q03-1","type":"input","level":1,"text":"Как расшифровывается аббревиатура ETL? Введите три английских слова через запятую.","answers":["Extract, Transform, Load","extract transform load","Extract,Transform,Load"],"explain":"ETL — Extract, Transform, Load: извлечение, преобразование, загрузка."},{"id":"q03-2","type":"single","level":1,"text":"Какая компания ввела термин Business Intelligence?","options":["Microsoft","Gartner","Google","IBM"],"correct":1,"explain":"Термин Business Intelligence был введён аналитиками Gartner."},{"id":"q03-3","type":"multiple","level":2,"text":"Какие операции работы с многомерными данными обеспечивает OLAP? Отметьте все верные.","options":["Произвольные срезы","Детализация","Вращение","Шифрование"],"correct":[0,1,2],"explain":"OLAP обеспечивает гибкий просмотр, срезы, детализацию, свёртку, вращение и сравнение во времени. Шифрование — задача безопасности, а не анализа."},{"id":"q03-4","type":"truefalse","level":2,"text":"Верно ли, что промежуточная область в ETL хранит итоговые данные для аналитиков?","correct":false,"explain":"Неверно. Промежуточная область содержит временные вспомогательные таблицы для организации выгрузки; итоговые данные помещаются в получатель (хранилище)."},{"id":"q03-5","type":"single","level":3,"text":"На каком этапе жизненного цикла аналитики разрабатывают наборы данных для тестирования, обучения и производства?","options":["Выявление проблемы","Подготовка данных","Построение модели","Практическая реализация"],"correct":2,"explain":"Построение модели включает разработку наборов данных для тестирования, обучения и производства и выбор рабочего окружения."}],"tests":""},"04":{"theory":"<h2>(MDS, SSIS, SSAS)</h2>\n<br/>\n<p>Данных становится всё больше и больше, поэтому сейчас как никогда важно иметь необходимый инструментарий для анализа данных и принятия решений. Выделим четыре популярных аналитических системы: MS Excel Power Query, MS Power BI, Pyramid Analytics, Компоненты аналитики MS SQL server (MDS, SSIS, SSAS).</p>\n<h2>Power Query</h2>\n<p>Power Query позволяет искать и открывать данные из различных</p>\n<br/>\n<p>источников доступных онлайн и через корпоративные сети. Он умеет загружать в Excel данные разных типов, форматов и структур, а также из совершенно разных источников: из сети, из файла, из баз данных, из публичных источников данных и корпоративных репозиториев данных (встроена поддержка ETL), из ряда других источников: SharePoint List, OData feed, Active Directory, Facebook, etc.</p>\n<p>Power Query обладает как положительными характеристиками, так и отрицательными. Из плюсов можно выделить: работает как с табличными моделями, так и с многомерными, умеет подключать дополнительные источники. Минусы данной программы: сложен в освоении, достаточно медлителен, нет возможности разделения доступа, ограничения на размер файлов/записей.</p>\n<h2>MS Power BI</h2>\n<p>Power BI – это инструмент создания интерактивных бизнес отчетов с возможностью совместной работы, визуализации и интерактивной работы.</p>\n<p>Power BI обладает возможностью быстрой разработки информативных бизнес отчетов и панелей (в сети) – с возможностью взаимодействия и исследования данных. Также поддерживается автоматическое обновление BI- отчетов и визуализации при изменении данных, поддержка языка запросов, в том числе и Power Query, создание каталога данных с индексами для поиска, язык запросов близкий к естественному (для бизнес-аналитика) и возможность интерактивной работы. Поддерживается работа с мобильными устройствами.</p>\n<p>Power BI является новым современным продуктом с дружелюбным интерфейсом и легким в освоении. Из недостатков можно выделить то, что решение «сырое» (некоторые компоненты могут работать нестабильно), оно не работает с OLAP кубами и имеет урезанный функционал в сравнении с конкурентами.</p>\n<h2>Pyramid Analytics</h2>\n<p>Pyramid Analytics – облачная платформа бизнес-аналитики, имеющая три ключевых компонента: интеллектуальный анализ данных, интерактивная</p>\n<br/>\n<p>работа с данными и визуализацией, представление данных аудитории.</p>\n<p>Платформа обладает возможностью совместной аналитики и моделирования данных, а также рядом других полезных возможностей: интеграция с R, работа с Big Data, интерактивная визуализация данных.</p>\n<p>Продукт легок в освоении, работает с огромным количеством источников и имеет очень широкую функциональность. Главный и единственный недостаток – высокая цена.</p>\n<p>SQL Сервер позволяет проводить анализ внутри своей экосистемы. У него есть обширный набор компонент, сфокусируемся на трех наиболее известных.</p>\n<p>Master Data Services — процессы и инструменты управления мастер- данными компании. Мастер-данные – это данные бизнеса: о клиентах, продуктах, услугах, персонале, технологиях, материалах и т.д.</p>\n<p>SQL Server Integration Services — миграцияиинтеграцияданных.</p>\n<p>SQL Server Analysis Services - OLAP и data mining внутри SQL сервера.</p>\n<h2>Business Intelligence vs. Data Science</h2>\n<p>Business Intelligence отвечает на вопросы: что произошло в прошлом квартале? как много товара мы продали? в чем проблема? в какой ситуации? т.е. говорит в основном о том, что было в прошлом и анализирует исторические данные, полученные на текущий момент.</p>\n<p>BI оперирует структурированными данными, традиционными источниками и управляемыми наборами данных.</p>\n<p>Data Science отвечает на вопросы: а что, если…? какой оптимальный сценарий для нашего бизнеса? что будет дальше? т.е. ставит цель предугадать, сделать прогноз. Области применения – оптимизация, прогнозирование, статистический анализ.</p>\n<p>DS работает с большими структурированными и неструктурированными наборами данных.</p>\n<br/>\n","examples":"<h2>Пример многомерного куба</h2>\n<p>Возьмем для примера таблицу Invoices, которая содержит заказы фирмы. Поля в данной таблице будут следующие: дата заказа, страна, город, название заказчика, компания-доставщик, название товара, количество товара, сумма заказа.</p>\n<p>Какие агрегатные данные мы можем получить на основе этого представления? Обычно это ответы на следующие вопросы. Какова суммарная стоимость заказов, сделанных клиентами из определенной страны? Какова суммарная стоимость заказов, сделанных клиентами из определенной страны и доставленных определенной компанией? Какова суммарная стоимость заказов, сделанных клиентами из определенной страны в заданном году и доставленных определенной компанией?</p>\n<p>Все эти данные можно получить из этой таблицы вполне очевидными SQL-запросами с группировкой. Результатом этого запроса всегда будет столбец чисел и список атрибутов, его описывающих (например, страна) – это одномерный набор данных или, говоря математическим языком, вектор.</p>\n<p>Представим себе, что нам надо получить информацию по суммарной стоимости заказов из всех стран и их распределение по компаниям доставщиков – мы получим уже таблицу (матрицу) из чисел, где в заголовках колонок будут перечислены доставщики, в заголовках строк – страны, а в ячейках будет сумма заказов. Это – двумерный массив данных. Такой набор данных называется сводной таблицей (pivot table) или кросс-таблицей.</p>\n<p>Если же нам захочется получить те же данные, но еще в разрезе годов, тогда появится еще одно изменение, т.е. набор данных станет трехмерным (условным тензором 3-го порядка или 3-х мерным «кубом»).</p>\n<p>Очевидно, что максимальное количество измерений – это количество всех атрибутов (Дата, Страна, Заказчик и т.д.), описывающих наши агрегируемые данные (сумму заказов, количество товаров и т.п.)</p>\n<p>Также стоит добавить, что для удобства работы с OLAP существуют языки запросов к многомерным кубам, например, MDX.</p>\n<br/>\n<h2>Продвинутая визуализация</h2>\n<p>Инструменты продвинутой визуализации позволяют представлять данные для более эффективного их восприятия посредством использования интерактивных картинок и диаграмм вместо таблиц.</p>\n<p>Обычно пользователи в динамическом режиме могут менять графическое представление, использовать масштабирование, объединять данные, изменять цвета.</p>\n<br/>\n<h2>Предиктивное моделирование и Data Mining</h2>\n<p>Предиктивное моделирование (Predictive Modelling) – это процесс создания (или выбора) модели для предсказания вероятности наступления некоторого события.</p>\n<p>Интеллектуальный анализ данных (Data Mining) – компьютерная техника извлечения знаний, которая использует искусственный интеллект для распознавания образов и выделения значимых закономерностей из данных, находящихся в хранилищах или во входных / выходных потоках. Эти методы основываются на статистическом моделировании, нейронных сетях, генетических алгоритмах и др. Частная методология text mining решает задачи навигации в больших текстовых массивах, поиск взаимосвязей между ключевыми понятиями текстов, структуризация хранилищ документов, поиск информации, выраженный на естественном языке, распределение по рубрикам. Информация, найденная в процессе использования методов Data Mining, должна описывать новые связи между свойствами, предсказывать значения одних признаков на основе других и т.д. Найденные знания должны быть применимы и по отношению к новым данным с некоторой степенью достоверности. Когда извлеченные знания непрозрачны для пользователя, должны существовать методы постобработки, позволяющие привести их к интерпретируемому виду.</p>\n<p>Задачи, решаемые методами Data Mining, включают: классификацию – отнесение объектов (наблюдений, событий) к одному из заранее известных классов; регрессию, в том числе задачи прогнозирования; установление зависимости непрерывных выходных от входных переменных; кластеризацию – группировку объектов (наблюдений, событий) на основе данных (свойств), описывающих сущность этих объектов; ассоциацию – выявление закономерностей между связанными событиями; последовательные шаблоны – установление закономерностей между связанными во времени событиями, то есть обнаружение зависимости, согласно которой если произойдет событие X, то спустя заданное время произойдет событие Y; анализ отклонений – выявление наиболее нехарактерных шаблонов.</p>\n\n<h3>Пример 7. Выбор аналитической системы</h3>\n<p><strong>Ситуация.</strong> Небольшая компания (20 сотрудников) хочет строить интерактивные отчёты по продажам, смотреть их с телефона и не имеет большого бюджета. Данные хранятся в Excel и в одной базе SQL Server.</p><table><tr><th>Система</th><th>Подходит?</th><th>Обоснование</th></tr><tr><td>Power Query</td><td>Частично</td><td>Загрузит данные в Excel, но сложен в освоении, медленный и не разделяет доступ.</td></tr><tr><td>Power BI</td><td><strong>Да</strong></td><td>Интерактивные отчёты, совместная работа, мобильные устройства, лёгкое освоение.</td></tr><tr><td>Pyramid Analytics</td><td>Нет</td><td>Очень широкие возможности, но главный недостаток — высокая цена.</td></tr><tr><td>Компоненты SQL Server</td><td>Частично</td><td>SSAS даёт OLAP, но требует администрирования; для отчётов на телефоне нужен дополнительный инструмент.</td></tr></table><p><strong>Вывод.</strong> Для данной задачи оптимален Power BI. Если же компании понадобятся OLAP-кубы, нужно учесть, что Power BI с ними не работает, и добавить SSAS.</p>\n<h3>Пример 8. Вопросы BI и Data Science</h3>\n<p>Для одной сети кофеен сформулируем вопросы двух типов.</p><ul><li><strong>BI (прошлое, структурированные данные):</strong> «Сколько стаканов латте продано в прошлом квартале?», «В какой кофейне выручка упала сильнее всего?».</li><li><strong>Data Science (будущее, «а что, если…»):</strong> «Сколько молока закупить на следующую неделю?», «Что будет с выручкой, если поднять цену на 10%?», «Где открыть следующую кофейню?».</li></ul><p>Первые вопросы решаются отчётами и сводными таблицами по историческим данным, вторые — прогнозными и оптимизационными моделями, часто с привлечением неструктурированных данных (отзывы, погода, трафик).</p>\n","tasks":"<h3>Задание 1. Сравнительная таблица аналитических систем</h3>\n<p><strong>Цель:</strong> Систематизировать знания о Power Query, Power BI, Pyramid Analytics и компонентах SQL Server.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Составьте таблицу из четырёх систем.</li>\n<li>Для каждой укажите: назначение, основные возможности, достоинства, недостатки.</li>\n<li>Добавьте строку «Работа с OLAP-кубами» и заполните её по материалам лекции.</li>\n<li>Подберите систему для двух сценариев: студенческий проект без бюджета и крупный банк с собственным SQL Server.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Заполненная таблица и два обоснованных выбора.</p>\n<p><strong>Форма представления:</strong> Таблица и два абзаца с обоснованием.</p>\n<h3>Задание 2. Многомерный куб для таблицы заказов</h3>\n<p><strong>Цель:</strong> Научиться переходить от одномерного набора данных к сводной таблице и кубу.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Возьмите таблицу Invoices из раздела «Примеры» (дата, страна, город, заказчик, доставщик, товар, количество, сумма).</li>\n<li>Сформулируйте вопрос, ответом на который будет вектор (одно измерение).</li>\n<li>Сформулируйте вопрос, ответом на который будет сводная таблица (два измерения).</li>\n<li>Сформулируйте вопрос для трёхмерного куба.</li>\n<li>Укажите, какое максимальное число измерений можно получить из этой таблицы, и объясните почему.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Три вопроса разной размерности и ответ о максимальном числе измерений.</p>\n<p><strong>Форма представления:</strong> Нумерованный список с пояснениями.</p>\n","selfcheck":"","questions":[{"id":"q04-1","type":"single","level":1,"text":"Какой компонент SQL Server отвечает за OLAP и data mining?","options":["Master Data Services","SQL Server Integration Services","SQL Server Analysis Services","Power Query"],"correct":2,"explain":"SSAS (SQL Server Analysis Services) обеспечивает OLAP и data mining внутри SQL Server."},{"id":"q04-2","type":"truefalse","level":1,"text":"Верно ли, что Power BI работает с OLAP-кубами?","correct":false,"explain":"Неверно. Среди недостатков Power BI в лекции указано, что он не работает с OLAP-кубами."},{"id":"q04-3","type":"input","level":2,"text":"Как называется язык запросов к многомерным кубам, упомянутый в примере? Введите аббревиатуру.","answers":["MDX"],"explain":"MDX (MultiDimensional eXpressions) — язык запросов к многомерным кубам."},{"id":"q04-4","type":"multiple","level":2,"text":"На какие вопросы отвечает Data Science? Отметьте все верные.","options":["Что будет дальше?","Какой оптимальный сценарий?","Сколько товара мы продали в прошлом квартале?","А что, если…?"],"correct":[0,1,3],"explain":"Data Science нацелена на прогноз и оптимизацию. Вопрос о продажах прошлого квартала — типичный вопрос BI."},{"id":"q04-5","type":"single","level":3,"text":"Таблица «страны × компании-доставщики» с суммами заказов в ячейках — это…","options":["Вектор","Сводная таблица (двумерный массив)","Трёхмерный куб","Справочник мастер-данных"],"correct":1,"explain":"Два измерения (страна и доставщик) образуют сводную таблицу, или кросс-таблицу."}],"tests":""},"05":{"theory":"<br/>\n<h3>Hadoop</h3>\n<p>Hadoop – каркас с открытым исходным кодом, предназначенный для создания и запуска распределённых приложений, обрабатывающих большие объёмы данных.</p>\n<p>Hadoop обладает важными отличительными особенностями:</p>\n<ul><li><strong>Надёжность</strong>: архитектура разработана с учётом возможности частых отказов, содержит несколько копий данных. Это позволяет избежать потерю данных.</li><li><strong>Доступность: </strong>Hadoop работает на крупных кластерах, собранных из стандартных компьютеров</li><li><strong>Масштабируемость: </strong>при увеличении объема данных достаточно добавить новые узлы в кластер</li><li><strong>Простота: </strong>Hadoop позволяет пользователю быстро создавать эффективный параллельный код</li><li><strong>Эффективность: </strong>параллельная обработка данных на множестве компьютеров</li><li><strong>Кроссплатформенность: </strong>систему можно развернуть на базе любой операционной системы с виртуальной машиной Java (JVM)</li></ul>\n<h2>История Hadoop и Map Reduce</h2>\n<p>Создателем Hadoop является Дуг Каттинг. Проект Hadoop начал свое существование в рамках Apache Nutch – системы веб-поиска с открытым исходным кодом. Hadoop назван в честь плюшевого жёлтого слона сына Дуга. Жёлтый слон также является логотипом системы Hadoop (рисунок 3.1). Подпроекты данной системы также получили названия, связанные с темой животных. Для более мелких компонентов выбор названия делался в пользу</p>\n<br/>\n<p>содержательности и простоты. Название само говорит, какие функции выполняет определеный компонент. Так, например, Job Tracker занимается отслеживанием заданий Map Reduce. </p>\n<img src=\"images/lecture-05-01.png\"/>\n<p>Запуск проекта Nutch произошёл в 2002 году. Поисковая система была запущена в кратчайшие сроки. Вскоре разработчики пришли к выводу, что данную архитектуру не представляется возможным масштабировать на миллиарды web-страниц. Решение проблемы было найдено в 2003 году, когда компания Google опубликовала статью, в которой описывалась архитектура распределённой файловой системы – Google File System(GFS). Такая архитектура была способна решить проблему хранения огромных файлов, которые генерировались в процессе индексирования и обхода. Вдобавок использование данной распределённой системы сэкономило бы время, затрачиваемое на управление узлами хранения данных. Реализация данной системы началась через год, в 2004 году. Система получила название Nutch Distributed Filesystem (NDFS). Ее исходный код является открытым. В этом же году компания Google представила технологию Map Reduce. В 2005 году разработчики Nutch представили работоспособную реализацию Map Reduce. К середине года была выполнена адаптация существующих алгоритмов Nutch для предоставления возможности использования Map Reduce и NDFS. Hadoop был образован в феврале 2006 года, как подпроект Lucene.</p>\n<p>Тогда же Дуг Каттинг начал работать в компании Yahoo!. Компания Yahoo! специально выделила группу и ресурсы для развития системы Hadoop. В феврале 2008 года Yahoo продемонстрировала поисковый индекс,</p>\n<br/>\n<p>сгенерированный 10000-ядерным кластером Hadoop.</p>\n<p>В начале 2008 года Hadoop стал одним из ведущих проектов Apache. Данная технология стала использоваться не только в Yahoo, но в таких компаниях, как Facebook, Last.fm и New York Times.</p>\n<p>В апреле 2008 года был обновлен мировой рекорд по скорости сортировки терабайта данных с применением технологии Hadoop. Время сортировки составляло 209 секунд (предыдущий рекорд – 297 секунд). Кластер состоял из 910 узлов.</p>\n<p>В ноябре того же года компания Google представила собственную реализацию Map Reduce, способную отсортировать 1 терабайт за 68 секунд.</p>\n<p>После этого технология Hadoop стремительно вошла в повседневную деятельность крупных компаний. Данная технология выполняла роль платформы хранения и анализа данных общего назначения. В настоящее время существуют дистрибутивы Hadoop как от крупных общепризнанных фирм, включая EMC, IBM, Microsoft и Oracle, так и от компаний с узкой специализацией – таких, как Cloudera, Hortonworks и MapR.</p>\n<h2>HadoopDistributedFileSystem</h2>\n<p>Hadoop поставляется с распределенной файловой системой, которая называется HDFS (Hadoop Distributed File System). Данная файловая система спроектирована для хранения очень больших файлов с потоковой схемой доступа к данным в кластерах обычных машин. Большие файлы в данном случае - это файлы, имеющие размер сотни мегабайт, гигабайт и терабайт.</p>\n<p>В основу HDFS заложена концепция однократной записи/многократного чтения как самая эффективная схема обработки данных. Набор данных обычно генерируется или копируется из источника, после чего с ним выполняются различные аналитические операции. В каждой операции задействуется большая часть набора данных (или весь набор), поэтому время чтения всего набора данных важнее задержки чтения первой записи.</p>\n<p>Hadoop не требует дорогостоящего оборудования высокой надежности. Система спроектирована для работы на стандартном оборудовании с</p>\n<br/>\n<p>достаточно высокой вероятностью отказа отдельных узлов в кластере. Технология HDFS спроектирована таким образом, чтобы в случае отказа система продолжала работу без заметного прерывания.</p>\n<p>В HDFS существует концепция блока, размер которого по умолчанию составляет 64 Мбайт. Файлы HDFS разбиваются на блочные фрагменты, которые хранятся независимо друг от друга.</p>\n<p>Абстракция блоков в распределенной файловой системе имеет несколько преимуществ:</p>\n<ul><li>Размер файл может превышать размер отдельного диска в сети. Блоки файла имеют возможность использования любых дисков в кластере. Кроме того, когда файл хранится в кластере HDFS, блоки данного файла можно распределить по всем дискам кластера.</li><li>Блоки упрощают подсистему хранения. Блоки имеют фиксированный размер. Это позволяет системе вычислить какое количество блоков хранится на определенном диске. Также блоки предотвращают проблемы, связанные с хранением метаданных.</li><li>Блоки подходят для репликации. За счет блоков происходит улучшение отказоустойчивости и доступности системы. Каждый блок имею несколько копий на отдельных машинах (по умолчанию 3). В случае недоступности какого-либо блока происходит считывание копии данного блока из другого доступного места.</li></ul>\n<p>Кластер HDFS имеет 2 вида узлов (рисунок 3.2): Name Node (узел имен) и Data Node (узел данных). Name Node является управляющим узлом, а Data Node – управляемым.</p>\n<p>Name Node занимается управлением пространством узлах имен файловой системы, поддержкой метаданных и каталогов в дереве файловой системы. Локальный диск хранит информацию в виде 2 файлов: журнала изменений и образа файловой системы. Name Node содержит информацию о том, на каких именно узлах находятся все блоки файла, при этом информация о местонахождении блоков строится заново при запуске системы, а не хранится</p>\n<br/>\n<p>постоянно.</p>\n<p>Для обращения к файловой системе клиент связывается с Name Node и Data Node узлами. Интерфейс файловой системы схож с интерфейсом Portable Operating System Interface. Таким образом пользовательский код может не обладать никакой информацией об узлах Name Node и Data Node.</p>\n<br/>\n<p>Узлы данных выполняют запись и чтение блоков, когда этого требуют клиенты или узел имен. Кроме того, данные узлы периодически передают список сохраняемых ими блоков непосредственно узлу имен. Узлы, будучи частью системы, напрямую влияют на работоспособность файловой системы. В случае ликвидации машины, на которой работает Name Node, произойдёт потеря всех данных. Именно по этой причине устойчивость узла имен к возможным сбоям важна.</p>\n<p>Hadoop предоставляет два способа для осуществления устойчивости:</p>\n<p>1. <strong>Архивация файлов</strong>, которые определяют устойчивое состояние метаданных файловой системы. Имеется возможность настроить Hadoop так, чтобы Name Node был способен на запись своего устойчивого</p>\n<br/>\n<p>состояния в несколько файловых систем. Операции записи выполняются синхронно и атомарно.</p>\n<p>2. <strong>Запуск вторичного узла имен</strong>, не выполняющего функции узла имен. Его основной функцией является периодическое слияние образа пространства имен с журналом изменений во избежание чрезмерного разрастания последнего. Вторичный узел имен обычно работает на отдельной физической машине, так как для того, чтобы выполнить слияние, требуются значительная вычислительная мощность и такое же количество памяти, как на узле имен. Вторичный узел имен имеет копию объединенного образа пространства имен, который может быть использован в случае сбоя основного узла. Однако состояние вторичного узла имен немного отстает от состояния основного узла. При полном отказе основного узла не является возможным предотвратить потерю данных.</p>\n<h2>Технология Map Reduce</h2>\n<p>Map Reduce – технология распределённых вычислений. Основными целями Map Reduce являются разделение логики приложения и организация распределённого взаимодействия.</p>\n<p>Программист реализует только логику приложения. Распределённая работа в кластере обеспечивается автоматически. Map Reduce работает с данными как с парами <strong>ключ - значение, </strong>например:</p>\n<ul><li>смещение в файле: текст</li><li>идентификатор пользователя: профиль</li><li>пользователь: список друзей</li><li>временная метка: событие в журнале</li></ul>\n<p>Работа Map Reduce производится в 2 этапа (рисунок 3.3):</p>\n<p>1. <strong>Map: </strong>выполняется предварительная обработка входных данных. Главный узел разделяет полученные данные на части и передаёт их рабочим узлам. При этом порождаются пары ключ -значение. Как ключи, так и значения могут быть составными.</p>\n<br/>\n<p>2. <strong>Reduce: </strong>происходит свёртка заранее обработанных данных. Рабочие узлы отправляют ответы главному узлу, а он на основе этих данных формирует решение поставленной задачи.</p>\n<p>Операции Map и Reduce могут выполняться распределённым образом.</p>\n<br/>\n","examples":"<h3>Примеры применения MapReduce</h3>\n<ul><li><p>Масштабный статистический анализ и моделирование</p></li><li><p>Анализ и индексация данных</p></li><li><p>Построение масштабируемых алгоритмов машинного обучения</p></li><li><p>Сбор данных DNS по всему миру для обнаружения сетей распределения контента и проблем с конфигурацией</p></li><li><p>Построение карты всей сети Интернет</p></li><li><p>Распределенный grep</p></li><li><p>Сортировка</p></li><li><p>Поиск web-страниц</p></li></ul>\n<br/>\n<h2>Достоинства модели Map Reduce</h2>\n<ul><li><p>Автоматическое распараллеливание: функции Map и Reduce могут выполняться параллельно и независимо друг от друга</p></li><li><p>Масштабируемость: данные могут располагаться и обрабатываться на разных серверах</p></li><li><p>Отказоустойчивость: при отказе сервера функции Map и Reduce запускаются на другом сервере.</p></li></ul>\n<br/>\n<h2>Недостатки модели Map Reduce</h2>\n<ul><li><p>Фиксированный алгоритм обработки данных</p></li><li><p>Высокие накладные расходы на распараллеливание</p></li></ul>\n<br/>\n<h3>Архитектура Hadoop</h3>\n<p>На каждом компьютере должны присутствовать два компонента (рисунок 3.4):</p>\n<ul><li><p>Task Tracker: выполняет маленькую вычислительную задачу на узле</p></li><li><p>Data Node: управляют данными, переданными на узел.</p></li></ul>\n<p>Все маленькие компьютеры называют Slave. Также существует Master узел. Данный узел кроме Task Tracker и Data Node содержит ещё Job Tracker и Name Node. Task Tracker и Job Tracker являютсякомпонентами Mad Reduce, а Name Node и Data Node – HDFS. Роль и цель Job Tracker, которые исполняется на Master Node - это разбить большие задачи на маленькие кусочки и отправить каждую маленькую часть вычислений соответствующему Task Tracker на узле, которые в свою очередь, когда смогут закончить вычисления, отправят обратно информацию в Job Tracker, который объединит все результаты вычислений и отправит их обратно приложению.</p>\n\n<h3>Пример 9. Подсчёт слов с помощью MapReduce</h3>\n<p><strong>Задача.</strong> Посчитать, сколько раз каждое слово встречается в двух строках: «big data big» и «data analysis».</p><p><strong>Этап Map.</strong> Главный узел передаёт каждую строку отдельному рабочему узлу. Каждый узел для каждого слова порождает пару <code>(слово, 1)</code>:</p><ul><li>Узел 1: (big, 1), (data, 1), (big, 1)</li><li>Узел 2: (data, 1), (analysis, 1)</li></ul><p><strong>Группировка по ключу (shuffle).</strong> Пары с одинаковым ключом собираются вместе: big → [1, 1]; data → [1, 1]; analysis → [1].</p><p><strong>Этап Reduce.</strong> Для каждого ключа значения суммируются: <strong>(big, 2), (data, 2), (analysis, 1)</strong>.</p><p><strong>Что важно.</strong> Программист написал только две функции: «разбить строку на слова и выдать (слово, 1)» и «сложить список чисел». Распределение по узлам, передача данных и повтор при сбое выполняются Hadoop автоматически.</p>\n<h3>Пример 10. Размещение файла в HDFS</h3>\n<p><strong>Задача.</strong> В HDFS загружается файл размером 1 ГБ (1024 МБ). Размер блока — 64 МБ (значение по умолчанию в Hadoop 1.x; в Hadoop 2.x и новее — 128 МБ), коэффициент репликации — 3. Сколько блоков будет создано и сколько места займёт файл?</p><ol><li>Число блоков: 1024 / 64 = <strong>16 блоков</strong>.</li><li>Каждый блок хранится в 3 копиях на разных машинах: 16 × 3 = <strong>48 копий блоков</strong>.</li><li>Занимаемое место в кластере: 1 ГБ × 3 = <strong>3 ГБ</strong>.</li></ol><p><strong>Что происходит при отказе узла.</strong> Name Node знает, на каких Data Node лежат копии каждого блока. Если один Data Node вышел из строя, клиент прочитает блок с другой машины, а система создаст новую копию, чтобы снова было 3.</p>\n","tasks":"<h3>Задание 1. Проектирование задачи MapReduce</h3>\n<p><strong>Цель:</strong> Научиться формулировать задачу в виде функций Map и Reduce.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Дан журнал веб-сервера, каждая строка которого имеет вид: «дата IP-адрес страница».</li>\n<li>Опишите функцию Map для подсчёта числа посещений каждой страницы: что является ключом, что — значением.</li>\n<li>Опишите функцию Reduce.</li>\n<li>Выполните вручную Map и Reduce для 6 придуманных строк журнала, распределив их между двумя узлами.</li>\n<li>Измените решение так, чтобы подсчитывать число посещений по дням.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Описание функций Map и Reduce, промежуточные пары ключ–значение и итоговый результат для двух вариантов задачи.</p>\n<p><strong>Форма представления:</strong> Таблицы «Вход — Выход Map», «Ключ — Список значений», «Результат Reduce».</p>\n<details class='hint'><summary>Подсказка</summary><p>Сравните с примером подсчёта слов: ключом становится то, по чему группируем.</p></details>\n<h3>Задание 2. Расчёт хранения в HDFS</h3>\n<p><strong>Цель:</strong> Понять блочную организацию и репликацию HDFS.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Рассчитайте число блоков и занимаемое место для файлов 200 МБ, 5 ГБ и 1 ТБ при размере блока 64 МБ и репликации 3.</li>\n<li>Повторите расчёт для размера блока 128 МБ.</li>\n<li>Объясните, почему HDFS неэффективна для хранения миллионов маленьких файлов по 10 КБ (подумайте о метаданных на Name Node).</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Таблица расчётов и объяснение (3–4 предложения).</p>\n<p><strong>Форма представления:</strong> Таблица «Файл — Блоков (64 МБ) — Блоков (128 МБ) — Место в кластере» и текст.</p>\n","selfcheck":"","questions":[{"id":"q05-1","type":"input","level":1,"text":"Кто является создателем Hadoop? Введите фамилию.","answers":["Каттинг","Cutting","Дуг Каттинг","Doug Cutting"],"explain":"Создатель Hadoop — Дуг Каттинг. Проект назван в честь игрушечного слона его сына."},{"id":"q05-2","type":"single","level":1,"text":"Сколько копий каждого блока хранит HDFS по умолчанию?","options":["1","2","3","5"],"correct":2,"explain":"По умолчанию каждый блок имеет 3 копии на разных машинах."},{"id":"q05-3","type":"multiple","level":2,"text":"Какие функции выполняет Name Node? Отметьте все верные.","options":["Управляет пространством имён файловой системы","Хранит метаданные и сведения о расположении блоков","Хранит сами блоки данных","Выполняет вычисления Map"],"correct":[0,1],"explain":"Name Node — управляющий узел: пространство имён, метаданные, расположение блоков. Блоки хранят Data Node, вычисления выполняют Task Tracker."},{"id":"q05-4","type":"truefalse","level":2,"text":"Верно ли, что вторичный узел имён (Secondary Name Node) полностью заменяет основной без потери данных при его отказе?","correct":false,"explain":"Неверно. Вторичный узел периодически сливает образ и журнал; его состояние немного отстаёт, поэтому при полном отказе основного узла потери данных избежать нельзя."},{"id":"q05-5","type":"single","level":3,"text":"Почему в HDFS время чтения всего набора данных важнее задержки чтения первой записи?","options":["Потому что HDFS хранит только маленькие файлы","Потому что по схеме «запись один раз — чтение много раз» каждая операция анализа читает большую часть набора данных","Потому что HDFS не поддерживает последовательное чтение","Потому что первая запись всегда кэшируется"],"correct":1,"explain":"В аналитике задействуется весь или почти весь набор данных, поэтому важна пропускная способность, а не задержка."}],"tests":""},"06":{"theory":"<p>В Hadoop MapReduce 1.0 входит единственный узел Job Tracker. Данный узел занимается распределением задач по многочисленным узлам Task Tracker, которые выполняют эти задачи (рисунок 3.5).</p>\n<img src=\"images/lecture-06-01.png\"/>\n<p>При таком подходе происходит перегрузка CPU и сети. Большую часть времени Job Tracker затрачивает на поддержку жизненного цикла Map Reduce задач. Загрузка сети происходит из-за большого централизованного трафика.</p>\n<p>В Hadoop MapReduce 1.0 при сбое JobTracker возникает необходимость перезапуска JobTracker с чтением состояния из специальных журналов. Это приводит к простою кластера. Максимальная масштабируемость находится в пределах 4000 узлов. Map Reduce 1.0 не позволял запускать на Hadoop кластере MPI распределённых алгоритмов из-за сильной связанности фреймворка распределённых вычислений и библиотек, выполняющих распределённый алгоритм. В первой версии размер файла по умолчанию составляет 64мб.</p>\n<h2>Hadoop Map Reduce 2.0</h2>\n<p>В Map Reduce 2.0 ответственность по управлению ресурсами и координации за жизненным циклом выполнения приложений разделена между Application Master и Resource Manager (рисунок 3.6).</p>\n<p>Каждый узел вычисления разбит на произвольное количество контейнеров (Container). Каждый контейнер содержит определённое количество ресурсов. За контейнером следит Node Manager. В Hadoop MapReduce 2.0 сохраняется состояние компонентов Resource Manager и Application Master и обеспечивается система автоматического перезапуска перечисленных компонентов при сбое с подгрузкой последнего успешно сохраненного состояния. Теоретически Map Reduce 2.0 может содержать до 10000 вычислительных узлов. Во второй версии был выделен фреймворк распределенных вычислений YARN и фреймворк, базирующийся на основе YARN, – MR2. YARN не зависит от специфики распределённого алгоритма в</p>\n<br/>\n<p>отличие от MR2.</p>\n<p>YARN предоставляет компоненты и API, необходимые для разработки распределенных приложений различных типов, также он берет на себя ответственность по распределению ресурсов в ответ на запросы ресурсов от выполняемых приложений и ответственность за отслеживанием статуса выполнения приложений.</p>\n<p>Благодаря YARN на Hadoop-кластере возможно запускать не только</p>\n<p>«map/reduce»-приложения, но и распределенные приложения, созданные с использованием: Open MPI, Spark, Apache HAMA, Apache Giraph и др. Есть возможность реализовать и другие распределенные алгоритмы.</p>\n<h3>Варианты использования Hadoop</h3>\n<p>Существует несколько вариантов использования Hadoop:</p>\n<ul><li><p>Автономный режим (Standalone Mode) – используется для того, чтобы на локальной машине использовать Hadoop как кластер, состоящий из одного узла</p></li><li><p>Псевдо-распределенный режим (Pseudo Distributed Mode) – поддержка работы с HDFS, но на одном узле</p></li><li><p>Полностью распределенный режим (Fully Distributed Mode) - используется на реальном кластере</p></li></ul>\n<br/>\n<h2>Экосистема Hadoop</h2>\n<p>Экосистема Hadoop постоянно расширяется новыми продуктами и инструментами. Рассмотрим основные компоненты, которые составляют данную экосистему.</p>\n<ul><li><p>HBase: представляeт собой NoSQL базу данных. HBase обеспечивает отказоустойчивый способ хранения данных огромных объёмов. Данная база данных работает поверх распределённой файловой системы HDFS. Проект реализован на языке Java. Первая рабочая версия появилась в октябре 2007 года.</p></li><li><p>Hive: представляет собой систему управления базами данных. Hive является надстройкой для Hadoop. Система Hive позволяет хранить данные в виде таблиц, выполнять SQL подобные запросы и анализировать данные, которые хранятся в Hadoop. Данный проект был разработан компанией Facebook и передан Apache. Hive поддерживает Hive Query Language (HiveQL). Данный язык запросов основан на SQL. HiveQl имеет функции для работы с XML и JSON форматами, а также поддерживает нескалярные типы данных.</p></li><li><p>Pig: является высокоуровневым процедурным языком. Pig используется для выполнения запросов к слабоструктурированными данным больших объёмов. Первая реализация Apache появилась в 2008 году.</p></li><li><p>Mahout: представляет собой набор библиотек для выполнения машинного обучения. Данный проект реализует такие области машинного обучения, как рекомендательные системы, кластеризация и классификация.</p></li><li><p>HUE: представляет собой web-интерфейс к Hadoop. Hadoop User Experience позволяет выполнять мониторинг задач кластера и облегчить его обслуживание.</p></li><li><p>Sqoop: представляет собой инструмент для выполнения передачи данных между Hadoop и реляционными базами данных. Благодаря использованию технологии Map Reduce обеспечивается параллельная работа и отказоустойчивость при экспорте и импорте данных.</p></li><li><p>Avro: представляет собой систему для выполнения сериализации данных со встроенной схемой. Данная система выполняет обмен двоичными данными для сериализации.</p></li><li><p>ZooKeeper: представляет собой распределённый сервис синхронизации и конфигурирования, является key/value хранилищем.</p></li><li><p>Flume: представляет собой инструмент для управления потоками данных. Первая версия появилась в 2009 году. Flume предназначен для сбора данных из различных источников и направления этих же данных в централизованный центр. Данный инструмент обладает простой и гибкой архитектурой.</p></li></ul>\n<br/>\n<p>Apache Spark предназначен для реализации распределённой обработки слабоструктурированных и неструктурированных данных. Проект позиционируется как инструмент для «молниеносных кластерных вычислений».</p>\n<p>Spark состоит из ядра и нескольких расширений:</p>\n<ul><li><p>Spark SQL: поддерживает запросы данных либо при помощи SQL, либо посредством Hive Query Language. Библиотека возникла как порт Apache Hive для работы поверх Spark (вместо Map Reduce), а сейчас уже интегрирована со стеком Spark. Она не только обеспечивает поддержку различных источников данных, но и позволяет переплетать SQL-запросы с трансформациями кода; получается очень мощный инструмент.</p></li><li><p>Spark Streaming: поддерживает обработку потоковых данных в реальном времени; такими данными могут быть файлы логов рабочего веб-сервера (напр. Apache Flume и HDFS/S3), информация из социальных сетей, например, Twitter, а также различные очереди сообщений, например, Kafka. Spark Streaming получает входные потоки данных и разбивает данные на пакеты. Далее они обрабатываются движком Spark, после чего генерируется конечный поток данных (также в пакетной форме).</p></li><li><p>Spark MLlib: библиотека для машинного обучения, предоставляющая различные алгоритмы, разработанные для горизонтального масштабирования на кластере в целях классификации, регрессии, кластеризации, совместной фильтрации и т.д. Некоторые из этих алгоритмов работают и с потоковыми данными, например, линейная регрессия с использованием обычного метода наименьших квадратов или кластеризация по методу k-средних.</p></li><li><p>GraphX: библиотека для манипуляций над графами и выполнения с ними параллельных операций. Библиотека предоставляет универсальный инструмент для ETL, исследовательского анализа и итерационных вычислений на основе графов. Кроме встроенных операций для манипуляций над графами здесь также предоставляется библиотека обычных алгоритмов для работы с графами, например, PageRank.</p></li></ul>\n","examples":"<h3>Пример 11. Сравнение MapReduce 1.0 и 2.0</h3>\n<table><tr><th>Критерий</th><th>MapReduce 1.0</th><th>MapReduce 2.0 (YARN)</th></tr><tr><td>Управление ресурсами</td><td>Один Job Tracker</td><td>Resource Manager + Application Master для каждого приложения</td></tr><tr><td>Единица ресурсов</td><td>Слоты Task Tracker</td><td>Контейнеры (Container), за которыми следит Node Manager</td></tr><tr><td>Сбой управляющего компонента</td><td>Перезапуск Job Tracker с чтением журналов, простой кластера</td><td>Автоматический перезапуск с последнего сохранённого состояния</td></tr><tr><td>Масштаб</td><td>До ~4000 узлов</td><td>Теоретически до ~10000 узлов</td></tr><tr><td>Типы приложений</td><td>Только map/reduce</td><td>Map/reduce, Spark, Open MPI, Giraph, HAMA и др.</td></tr></table><p><strong>Вывод.</strong> Главная идея версии 2.0 — разделить управление ресурсами кластера и управление конкретным приложением. Это сняло нагрузку с единственного Job Tracker и позволило запускать на кластере не только MapReduce.</p>\n<h3>Пример 12. Запрос HiveQL вместо программы MapReduce</h3>\n<p><strong>Задача.</strong> В Hadoop хранится таблица продаж <code>sales(date, city, amount)</code>. Нужно найти суммарные продажи по городам.</p><p>Вместо написания функций Map и Reduce на Java аналитик пишет SQL-подобный запрос в Hive:</p><pre><code>SELECT city, SUM(amount) AS total\nFROM sales\nGROUP BY city\nORDER BY total DESC;</code></pre><p>Hive сам преобразует запрос в задания MapReduce (или Spark): Map выдаёт пары (city, amount), Reduce суммирует значения по каждому городу.</p><p><strong>Вывод.</strong> Компоненты экосистемы (Hive, Pig, Spark SQL) позволяют работать с большими данными без низкоуровневого программирования.</p>\n","tasks":"<h3>Задание 1. Подбор компонентов экосистемы Hadoop</h3>\n<p><strong>Цель:</strong> Научиться выбирать инструменты экосистемы Hadoop под задачу.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Для каждой ситуации выберите компонент экосистемы и обоснуйте выбор: (а) перенести таблицы из MySQL в Hadoop; (б) собирать логи с 50 веб-серверов в центральное хранилище; (в) выполнять SQL-подобные запросы к данным в HDFS; (г) построить рекомендательную систему; (д) хранить миллиарды строк с быстрым доступом по ключу; (е) обрабатывать поток сообщений Twitter в реальном времени.</li>\n<li>Нарисуйте схему, на которой выбранные компоненты связаны с HDFS и YARN.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Шесть ответов с обоснованием и схема.</p>\n<p><strong>Форма представления:</strong> Таблица «Ситуация — Компонент — Обоснование» и схема.</p>\n<h3>Задание 2. Режимы работы Hadoop</h3>\n<p><strong>Цель:</strong> Различать режимы развёртывания Hadoop.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Опишите, какой режим (автономный, псевдораспределённый, полностью распределённый) подходит для: отладки программы на ноутбуке; проверки работы с HDFS на одном компьютере; промышленной обработки 50 ТБ данных.</li>\n<li>Для каждого режима укажите, используется ли HDFS и сколько узлов задействовано.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Три обоснованных ответа и сравнительная таблица режимов.</p>\n<p><strong>Форма представления:</strong> Таблица «Режим — HDFS — Узлов — Назначение».</p>\n","selfcheck":"<h2>Контрольные вопросы для повторения и самопроверки темы</h2>\n<p>1. Что такое Apache Hadoop?</p>\n<p>2. В чем преимущества решений на базе Hadoop?</p>\n<p>3. Что такое MapReduce?</p>\n<p>4. Какими достоинствами и недостатками обладает MapReduce?</p>\n<p>5. Какому основному принципу следует HDFS?</p>\n<p>6. Какой размер блока по умолчанию в HDFS?</p>\n<p>7. Какие функции выполняет NameNode в HDFS?</p>\n<p>8. Какой узел отвечает за репликацию данных в Hadoop?</p>\n<p>9. Какие компоненты содержит Slave узел в Hadoop?</p>\n<p>10. Какие компоненты содержит Master узел в Hadoop?</p>\n<p>11. Какие компоненты являются частями HDFS?</p>\n<p>12. Какое API было добавлено в Hadoop v2.0?</p>\n<p>13. Для чего используется автономный режим Hadoop?</p>\n<p>14. Какой режим необходим для того, чтобы на локальной машине использовать Hadoop как кластер, состоящий из одного узла?</p>\n<br/>\n","questions":[{"id":"q06-1","type":"input","level":1,"text":"Как называется фреймворк управления ресурсами, выделенный в Hadoop 2.0? Введите аббревиатуру.","answers":["YARN"],"explain":"YARN (Yet Another Resource Negotiator) распределяет ресурсы кластера и следит за выполнением приложений."},{"id":"q06-2","type":"single","level":1,"text":"Для чего используется автономный режим Hadoop?","options":["Для работы на реальном кластере","Для использования Hadoop на локальной машине как кластера из одного узла","Для работы с HDFS на нескольких узлах","Для резервного копирования"],"correct":1,"explain":"Standalone Mode позволяет запускать Hadoop на одной машине как кластер из одного узла, обычно для отладки."},{"id":"q06-3","type":"multiple","level":2,"text":"Какие компоненты Hadoop 2.0 разделили обязанности Job Tracker? Отметьте все верные.","options":["Resource Manager","Application Master","Name Node","Hive"],"correct":[0,1],"explain":"Управление ресурсами и координация жизненного цикла приложения разделены между Resource Manager и Application Master."},{"id":"q06-4","type":"truefalse","level":2,"text":"Верно ли, что Hive разработан компанией Facebook и использует язык запросов HiveQL на основе SQL?","correct":true,"explain":"Верно. Facebook разработал Hive и передал его Apache; HiveQL основан на SQL."},{"id":"q06-5","type":"single","level":3,"text":"Какой узел отвечает за репликацию данных в Hadoop (вопрос для самопроверки из лекции)?","options":["Task Tracker","Name Node","Job Tracker","Application Master"],"correct":1,"explain":"Name Node знает расположение всех блоков и управляет их репликацией; Data Node выполняют копирование по его указанию."},{"id":"q06-6","type":"single","level":2,"text":"Какой компонент экосистемы является web-интерфейсом к Hadoop?","options":["HUE","Sqoop","Avro","Flume"],"correct":0,"explain":"HUE (Hadoop User Experience) — web-интерфейс для мониторинга задач и обслуживания кластера."}],"tests":""},"07":{"theory":"<h3>NoSQL. Not Only SQL</h3>\n<p><em>NoSQL (англ. Not Only SQL, не только SQL) </em>– термин для ряда подходов, преследующих цель решить такие проблемы, как масштабируемость, доступность, устойчивость к разделению и согласованность данных.</p>\n<p>В качестве одного из методологических обоснований подхода NoSQL используется эвристический принцип (теорема CAP), утверждающий, что в распределённой системе невозможно одновременно обеспечить согласованность данных, доступность и устойчивость к расщеплению распределённой системы на изолированные части.</p>\n<p>Таким образом, при необходимости достижения высокой доступности и устойчивости к разделению предполагается не фокусироваться на средствах обеспечения согласованности данных, обеспечиваемых традиционными SQL- ориентированными СУБД с транзакционными механизмами на принципах ACID.</p>\n<h2>Масштабируемость</h2>\n<p>Целью является достижение линейности масштабируемости при большом числе узлов, потому как горизонтальное масштабирование, применяемое на традиционных базах данных, обычно является трудоемким и дорогостоящим удовольствием.</p>\n<p>Существуют два вида масштабируемости:</p>\n<br/>\n<p><em>Вертикальное масштабирование: </em>масштабируемость в этом контексте означает возможность заменять в существующей вычислительной системе компоненты более мощными и быстрыми по мере роста требований и развития технологий. Увеличение производительности каждого компонента системы с целью повышения общей производительности. Это самый простой способ масштабирования, так как не требует никаких изменений в прикладных программах, работающих на таких системах.</p>\n<p><em>Горизонтальное масштабирование: </em>масштабируемость в этом контексте означает возможность добавлять к системе новые узлы, серверы, процессоры для увеличения общей производительности. Разбиение системы на более мелкие структурные компоненты и разнесение их по отдельным физическим машинам (или их группам) и (или) увеличение количества серверов, параллельно выполняющих одну и ту же функцию. Этот способ масштабирования может</p>\n<p>требовать внесения изменений в программы, чтобы программы могли в полной мере пользоваться возросшим количеством ресурсов.</p>\n<p>Для области Big Data интересно горизонтальное масштабирование, так как оно распределенное.</p>\n<h2>Репликация</h2>\n<p><em>Репликация </em>— это копирование данных на другие узлы при обновлении, позволяющее создать полный дубликат базы данных так, что вместо одного сервера их будет несколько, повысить отказоустойчивость, снизить нагрузку на каждый отдельный сервер и как добиться большей масштабируемости, так и повысить доступность и сохранность данных. Включает в себя два вида:</p>\n<ul><li>master-slave</li><li>peer-to-peer</li></ul>\n<p><em>Репликация Master-Slave </em>(рисунок 4.1):</p>\n<br/>\n<img src=\"images/lecture-07-01.png\"/>\n<p>Master – это основной сервер БД, куда поступают все данные и где происходят изменения в данных (добавление, обновление, удаление).</p>\n<p>Slave – это вспомогательный сервер БД, копирующий все данные с мастера, предназначен только для чтения и может быть в количестве больше одного.</p>\n<p>Потому как операций чтения (SELECT) данных часто намного больше, чем операций изменения данных (INSERT/UPDATE), то репликация позволяет таким образом разгрузить основной сервер за счет переноса операций чтения на слейв, потому что в его использовании два или больше одинаковых серверов вместо одного.</p>\n<p><em>Репликация Peer-to-peer </em>(рисунок 4.2):</p>\n<br/>\n<img src=\"images/lecture-07-02.png\"/>\n<p><em>Одноранговая сеть </em>– это сеть, которая основывается на равноправии всех участников сети. В данном виде сети отсутствует главный сервер, и каждый узел является как клиентом, так и выполняет функции сервера.</p>\n<p>Сама по себе репликация не самый удобный механизм масштабирования, так как происходит рассинхронизация данных и возможны задержки в копирования с мастера на слейв. Но вместе с тем это отличное средство для обеспечения отказоустойчивости, потому как всегда можно переключиться на слейв в случае отказа мастера. Для надежности обычно используется совместно с шардингом.</p>\n<p><em>Шардинг </em>(рисунок 4.3):</p>\n<img src=\"images/lecture-07-03.png\"/>\n<p><em>Шардинг </em>–это другая техника масштабирования работы с данными, суть которой заключается в разделении базы данных на отдельные части так, чтобы каждую из них можно было вынести на отдельный сервер. Этот процесс зависит от структуры базы данных и выполняется прямо в приложении, в отличие от репликации. Существуют два типа шардинга:</p>\n<p><em>Вертикальный шардинг </em>– это выделение таблицы или группы таблиц на отдельный сервер.</p>\n<p><em>Горизонтальный шардинг </em>– это разделение одной таблицы на разные сервера. Это необходимо использовать для огромных таблиц, которые не умещаются на одном сервере. Разделение таблицы на куски делается по такому принципу:</p>\n<p>1. На нескольких серверах создается одна и та же таблица (только структура, без данных).</p>\n<p>2. В приложении выбирается условие, по которому будет определяться нужное соединение (например, четные на один сервер, а нечетные – на другой).</p>\n<p>3. Перед каждым обращением к таблице происходит выбор нужного соединения (допустим, для нечетных пользователей мы будем работать с первым сервером, а для четных – со вторым).</p>\n<br/>\n<h2>CAP – теорема</h2>\n<p><em>Теорема CAP </em>(известная также как теорема Брюера), – эвристическое утверждение о том, что в любой реализации распределённых вычислений возможно обеспечить не более двух из трёх следующих свойств (рисунок 4.4):</p>\n<img src=\"images/lecture-07-04.png\"/>\n<p>1. Согласованность данных (англ. <strong>С</strong>onsistency) – во всех вычислительных узлах в один момент времени данные не противоречат друг другу. Как только мы успешно записали данные в наше распределенное хранилище, любой клиент при запросе получит эти последние данные.</p>\n<p>2. Доступность (англ. <strong>A</strong>vailability) – любой запрос к распределённой системе завершается корректным откликом. В любой момент клиент может получить данные из нашего хранилища или получить ответ об их отсутствии, если их никто еще не сохранял.</p>\n<p>3. Устойчивость к разделению (англ. <strong>P</strong>artition tolerance) – расщепление распределённой системы на несколько изолированных секций не приводит к некорректности отклика от каждой из секций. Потеря сообщений между компонентами системы (возможно даже потеря всех сообщений) не влияет на работоспособность системы. Здесь очень важный момент состоит в том, что если какие-то компоненты выходят из строя, то это тоже подпадает под этот случай, так как можно считать, что данные компоненты просто теряют связь со</p>\n<br/>\n<p>всей остальной системой.</p>\n<p><em>Следствие из теоремы CAP</em></p>\n<p><strong>CA</strong>: Система, во всех узлах которой данные согласованы и обеспечена доступность, жертвует устойчивостью к распаду на секции. Такие системы возможны на основе технологического программного обеспечения, поддерживающего транзакционность в смысле ACID. Примерами таких систем могут быть решения на основе кластерных систем управления базами данных или распределённая служба каталогов LDAP.</p>\n<p><strong>CP</strong>: Распределённая система, в каждый момент обеспечивающая целостный результат и способная функционировать в условиях распада в ущерб доступности, может не выдавать отклик. Устойчивость к распаду на секции требует обеспечения дублирования изменений во всех узлах системы, в этой связи отмечается практическая целесообразность использования в таких системах распределённых пессимистических блокировок для сохранения целостности.</p>\n<p><strong>AP</strong>: Распределённая система, отказывающаяся от целостности результата. Хотя системы такого рода известны задолго до формулировки принципа CAP (например, распределённые веб-кэши или DNS), рост популярности систем с этим набором свойств связывается именно с распространением теоремы CAP. Так, большинство NoSQL-систем принципиально не гарантируют целостности данных и ссылаются на теорему CAP как на мотив такого ограничения. Задачей при построении AP-систем становится обеспечение некоторого практически целесообразного уровня целостности данных, в этом смысле про AP-системы говорят как о «целостных в конечном итоге» (англ. eventually consistent) или как о «слабо целостных» (англ. weak consistent).</p>\n<p>Перейдем к определению ACID, что расшифровывается как:</p>\n<p><strong>A</strong>tomicity – транзакции атомарны, то есть либо все изменения транзакции фиксируются (commit), либо все откатываются (rollback).</p>\n<p><strong>C</strong>onsistency – транзакции не нарушают согласованность данных, то есть</p>\n<br/>\n<p>они переводят базу данных из одного корректного состояния в другое. Тут можно упомянуть допустимые значения полей, внешние ключи и более сложные ограничения целостности.</p>\n<p><strong>I</strong>solation – работающие одновременно транзакции не влияют друг на друга, то есть многопоточная обработка транзакций производится таким образом, чтобы результат их параллельного исполнения соответствовал результату их последовательного исполнения.</p>\n<p><strong>D</strong>urability – если транзакция была успешно завершена, никакое внешнее событие не должно привести к потере совершенных ей изменений.</p>\n<br/><h3>Основы NoSQL</h3>\n<p>В основе идеи NoSQL лежит следующее:</p>\n<p>Основные возможности:</p>\n<p>Нереляционная модель данных;</p>\n<ul><li><p>Открытый исходный код;</p></li><li><p>Хорошая горизонтальная масштабируемость;</p></li><li><p>Не требуют жестко заданной схемы данных. Другие характеристики:</p></li><li><p>Свободны от одного или нескольких свойств ACID;</p></li><li><p>Поддержка репликации:</p></li><li><p>Легкое API (если SQL, то только облегченный вариант).</p></li></ul>\n<p>Не полностью поддерживают возможности традиционных реляционных</p>\n<p>БД:</p>\n<ul><li><p>нет join операций, т.к. они требуют жестко заданной структуры и связей (Consistency)</p></li></ul>\n<p>История:</p>\n<p>Впервые термин NoSQL стал использоваться в конце 90-х, но реальный смысл в том виде, как он используется сейчас, приобрел только в середине 2009. В июне 2009 в Сан-Франциско Йоханом Оскарссоном была организована встреча, на которой планировалось обсудить новые веяния на ИТ рынке хранения и обработки данных. Главным стимулом для встречи стали новые opensource-продукты наподобие BigTable и Dynamo. Для яркой вывески для встречи требовалось найти емкий и лаконичный термин, который отлично укладывался бы в твиттеровский хэштег. Один из таких терминов предложил Эрик Эванс из RackSpace – «NoSQL». Термин планировался лишь на одну встречу и не имел под собой глубокой смысловой нагрузки, но так получилось, что он распространился по мировой сети наподобие вирусной рекламы и стал де-факто названием целого направления в ИТ-индустрии.</p>\n<p>Стоит еще раз подчеркнуть, что термин “NoSQL” имеет абсолютно стихийное происхождение и не имеет общепризнанного определения или научного утверждения за спиной. Это название скорее характеризует вектор развития информационных технологий в сторону от реляционных баз данных.</p>\n<p>Механизмы доступа к NoSQL:</p>\n<p>RESTful интерфейсы – это интерфейс, похожий на основной протокол интернета – HTTP. В рамках данного подхода предполагается, что каждый объект, c которым можно манипулировать, имеет свой уникальный адрес. Обращаясь по этому адресу, можно запрашивать, создавать, редактировать или удалять указанный объект. При этом на сервере не сохраняется никакого состояния, то есть каждый запрос обрабатывается независимо от других запросов.</p>\n<p>Языки запросов отличные от SQL</p>\n<ul><li><p>GQL – SQL-подобный язык для Google BigTable;</p></li><li><p>SPARQL – язык запросов семантического веба;</p></li><li><p>Gremlin – язык обхода графов;</p></li><li><p>Sones Graph Query Language – языкзапросовк Sones Graph. API запросов</p></li><li><p>Google BigTable DataStore API</p></li><li><p>Neo4j Traversal API</p></li></ul>\n<p>Категориями хранилищ в зависимости от размера и сложности NoSQL являются:</p>\n<p>Хранилище для Ключ/Значение – Key/value store:</p>\n<p>В этом случае база данных представляется как коллекция элементов ключ/значение, в каждой паре которых ключ обязательно является уникальным. Отсутствуют требования для нормализации, структуры данных сложные. Данные распределяются по разным узлам кластера на основе ключа.</p>\n<p>Основные операции:</p>\n<ul><li><p>insert(key,value);</p></li><li><p>delete(key);</p></li><li><p>update(key,value);</p></li><li><p>lookup(key);</p></li><li><p>execute(key, operation, parameters).</p></li></ul>\n<p>Имеют серьезные ограничения в языке запросов Дополнительные операции:</p>\n<ul><li><p>Вариации перечисленных выше операций – обратный lookup;</p></li><li><p>Итерации.</p></li></ul>\n<p>Хранилище колоночного типа – Column store</p>\n<p>Эта база представляет собой большую таблицу с тремя измерениями: колонки, строки и временные метки. Набор колонок не фиксирован и может различаться от строчки к строчке.</p>\n<p>Документо-ориентированные хранилища – Document store</p>\n<p>Такие базы немного напоминают Key-Value базы, но в данном случае база данных знает, что из себя представляют значения. Обычно значением является некоторый документ или объект, к структуре которого можно делать запросы.</p>\n<p>Основное понятие документа – слова, фразы, предложения, параграфы и т.д. Имеет гибкую структуру, в которой подкомпоненты структуры могут быть вложенными и различной формы. Поддерживаются метаданные – название, автор, время, встроенные теги. Форматы документов – PDF, XML, JSON, текст, сканированные рисунки.</p>\n<p>Основныеоперации:</p>\n<ul><li><p><strong>insert(key, document);</strong></p></li><li><p><strong>fetch(key);</strong></p></li><li><p><strong>update(key);</strong></p></li><li><p><strong>delete(key).</strong></p></li></ul>\n<p>Графо-ориентированныехранилища – Graph store</p>\n<p>Подобные базы ориентированы на поддержку сложных взаимосвязей между объектами. Это направленные графы, в которых узлы и грани содержат некие свойства. Структура данных в таких базах представляет собой набор узлов, связанных между собой ссылками. При этом и узлы, и ссылки могут обладать некоторым количеством атрибутов.</p>\n<br/>\n","examples":"<h3>Пример 13. Горизонтальный шардинг таблицы пользователей</h3>\n<p><strong>Ситуация.</strong> Таблица <code>users</code> содержит 400 млн записей и не помещается на одном сервере. Применим горизонтальный шардинг по правилу из лекции.</p><ol><li>На серверах S1 и S2 создаём одинаковую таблицу <code>users</code> (только структуру).</li><li>Правило выбора сервера: <code>id % 2 == 1</code> → S1 (нечётные), <code>id % 2 == 0</code> → S2 (чётные).</li><li>Перед каждым запросом приложение вычисляет сервер: пользователь с id = 1057 — нечётный, значит, обращаемся к S1; id = 2024 — к S2.</li></ol><p><strong>Добавим отказоустойчивость.</strong> Для каждого шарда настраиваем репликацию master–slave: S1 → S1-slave, S2 → S2-slave. Чтение (SELECT) можно выполнять на slave-серверах, а при отказе мастера переключиться на slave.</p><p><strong>Ограничение.</strong> Если позже понадобится третий сервер, правило «чёт/нечет» придётся заменить (например, на <code>id % 3</code>) и перераспределить данные — шардинг выполняется в приложении и зависит от структуры БД.</p>\n<h3>Пример 14. Выбор между согласованностью и доступностью (CAP)</h3>\n<p>Рассмотрим две системы, работающие на нескольких дата-центрах; связь между дата-центрами может прерываться (разделение сети неизбежно, значит, P нужно обеспечить).</p><ul><li><strong>Банковские переводы → CP.</strong> Если дата-центры потеряли связь, лучше временно отказать в операции, чем допустить, чтобы один и тот же остаток был списан дважды. Жертвуем доступностью.</li><li><strong>Счётчик лайков в соцсети → AP.</strong> Пользователь всегда должен видеть страницу; если в одном дата-центре показано 1520 лайков, а в другом 1523, это допустимо: данные станут согласованными позже (eventually consistent). Жертвуем согласованностью.</li></ul><p><strong>Вывод.</strong> Выбор между C и A при разделении сети определяется требованиями предметной области; большинство NoSQL-систем выбирают AP.</p>\n","tasks":"<h3>Задание 1. Схема масштабирования</h3>\n<p><strong>Цель:</strong> Применить репликацию и шардинг для конкретной системы.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Система онлайн-обучения хранит таблицы: студенты (5 млн), курсы (2 тыс.), ответы на тесты (3 млрд). 95% запросов — чтение.</li>\n<li>Определите, какие таблицы нужно шардировать вертикально, а какие — горизонтально.</li>\n<li>Предложите правило горизонтального шардинга для таблицы ответов.</li>\n<li>Выберите вид репликации и объясните, как она снизит нагрузку на чтение.</li>\n<li>Укажите, что произойдёт при отказе одного мастер-сервера.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Схема размещения таблиц по серверам с указанием мастеров и реплик и пояснения к каждому решению.</p>\n<p><strong>Форма представления:</strong> Рисунок схемы и список решений с обоснованием.</p>\n<h3>Задание 2. Классификация систем по теореме CAP</h3>\n<p><strong>Цель:</strong> Научиться определять, какие свойства CAP обеспечивает система.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Отнесите к CA, CP или AP следующие системы: DNS, кластерная СУБД с транзакциями ACID, корзина интернет-магазина, система бронирования последнего места в самолёте, распределённый веб-кэш.</li>\n<li>Для каждой системы укажите, каким свойством жертвуют и чем это грозит пользователю.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Классификация пяти систем с обоснованием.</p>\n<p><strong>Форма представления:</strong> Таблица «Система — Класс — Чем жертвуем — Последствия».</p>\n<details class='hint'><summary>Подсказка</summary><p>В лекции DNS и веб-кэши приведены как примеры AP, а LDAP и кластерные СУБД — как CA.</p></details>\n","selfcheck":"","questions":[{"id":"q07-1","type":"input","level":1,"text":"Как расшифровывается NoSQL? Введите расшифровку на английском.","answers":["Not Only SQL","not only sql"],"explain":"NoSQL — Not Only SQL, то есть «не только SQL»."},{"id":"q07-2","type":"single","level":1,"text":"Сколько из трёх свойств (C, A, P) можно одновременно обеспечить в распределённой системе по теореме CAP?","options":["Одно","Не более двух","Все три","Ни одного"],"correct":1,"explain":"Теорема Брюера: в распределённой системе можно обеспечить не более двух из трёх свойств."},{"id":"q07-3","type":"multiple","level":2,"text":"Какие свойства входят в ACID? Отметьте все верные.","options":["Atomicity","Consistency","Isolation","Durability","Availability"],"correct":[0,1,2,3],"explain":"ACID — атомарность, согласованность, изолированность, долговечность. Availability (доступность) — свойство из теоремы CAP."},{"id":"q07-4","type":"truefalse","level":2,"text":"Верно ли, что вертикальное масштабирование не требует изменений в прикладных программах?","correct":true,"explain":"Верно: компоненты заменяют более мощными, программы остаются прежними. Горизонтальное масштабирование может потребовать изменений."},{"id":"q07-5","type":"single","level":3,"text":"В каком типе NoSQL-хранилища база знает структуру значения и позволяет делать запросы к нему?","options":["Key/value store","Document store","Column store","Graph store"],"correct":1,"explain":"В документо-ориентированных хранилищах значением является документ (JSON, XML), к структуре которого можно делать запросы."}],"tests":""},"08":{"theory":"<p>Одним из инструментов для NoSQL является MongoDB, разрабатываемый компанией 10gen на языке C++. Общение с клиентом происходит через специализированный бинарный протокол, а для работы с документами используется BSON – посути тоже самое, что и JSON, но в бинарном виде. Главная причины выбора BSON вместо JSON - скорость парсинга данных. Бинарные данные расшифровываются намного быстрее. Имеет большой набор вариантов репликации и распределения данных. Для использования требуются специальные драйверы, которые созданы для большинства популярных языков программирования.</p>\n<p>Документы разделяются на коллекции по типу, что напоминает табличную структуру реляционных баз данных. Но в отличие от RDBMS коллекции разделяют данные только по смыслу. У каждого документа есть идентифицирующее поле _id и никакого поля, позволяющего следить за ревизиями, нет.</p>\n<p>Репликация вида master-slave: вся работа осуществляется с главным сервером, а изменения отправляются на подчинённый сервер. Если мастер отключается, то подчинённый не может автоматически занять его место. Репликационные множества (Replica sets): до 7 компьютеров, при потере мастера, автоматически выбирается новый.</p>\n<p>Шардинг поддерживается, начиная с версии 1.6. Отсутствует жёсткое</p>\n<br/>\n<p>ограничение на число серверов и каждая отдельная группа (shard) может быть представлена не одним сервером, а репликационным множеством.</p>\n<br/>\n<h2>Вывод</h2>\n<p>Нереляционные БД удобны при хранении плохо структурированной информации, масштабируются намного лучше RDBMS, и таким образом неизбежны при обработке очень крупных объёмов данных, эффективны для аналитической обработки данных и часто не имеют транзакционных механизмов.</p>\n<br/><h3>Сравнение NoSQL с базой данных</h3>\n<p>Достоинства NoSQL:</p>\n<p>В сравнении с реляционными базами данных лучшая производительность при индексировании больших объёмов данных и большим количеством запросов на чтение;</p>\n<ul><li><p>Легче масштабируются в сравнении с SQL-решениями;</p></li><li><p>Децентрализированы (данные распределены на нескольких нодах, отсутствует проблема single-point-of-failure);</p></li><li><p>Легко менять \"схему\" данных: не нужно выполнять никаких операций обновления для добавления новых полей;</p></li><li><p>Нет проблем с хранением неструктурированных данных;</p></li><li><p>Единое место хранения всей информации об объекте: меньше операций вида \"join\";</p></li><li><p>Простой интерфейс общения с БД: ключ → значение, нет SQL. Достоинства традиционных БД:</p></li><li><p>Теоретический базис;</p></li><li><p>Гибкость, организованность и надежность;</p></li><li><p>Риски известны.</p></li></ul>\n<p>Недостатки NoSQL:</p>\n<ul><li><p>Не поддерживает (операции Joins, Group by; ACID-принципы; SQL; интеграцию с приложениями, которые построены на SQL).</p></li><li><p>Отсутствие транзакционной логики и контроля целостности в большинстве реализаций (необходимо реализовывать её в логике приложения; специализированная логика может оказаться эффективнее общих алгоритмов реляционных БД).</p></li><li><p>Для обработки данных необходимо использование дополнительного языка программирования (плюс для программистов, которые этот язык уже знают, кроме того, иногда для этих целей можно использовать разные языки).</p></li></ul>\n<p>Недостатки традиционных БД:</p>\n<ul><li><p>Сложность создания запросов на SQL, которые выходят за рамки простого SELECT;</p></li><li><p>Посредственная масштабируемость на сверхвысокую нагрузку в виде большого количества запросов на чтение и запись;</p></li><li><p>Плохая адаптируемость к сетям распределённых вычислений;</p></li><li><p>Плохая поддержка объема данных больше 10-100 Тб;</p></li><li><p>Ограничение на жесткую структуру и схему данных;</p></li><li><p> Сложность при Join для данных на нескольких узлах.</p></li></ul>\n<p>Они плохо подходят под вызовы Big Data. В то время как NoSQL используется для:</p>\n<p> Аналитической обработки большого объёма данных;</p>\n<p>На сайтах с очень высокой нагрузкой, поскольку легко масштабируются горизонтально;Совместно с традиционными решениями на реляционных базах данных. Когда:</p>\n<ul><li><p>В приложениях, которые работают с огромными объемами полу- структурированных данных (анализ логов приложения/cистемы; анализ социальных сетей);</p></li><li><p>Большинство приложений в организациях используют небольшой объем данных и не имеют необходимости в высокой скорости выполнения запросов на обновление и выборку.</p></li></ul>\n<p>В этом случае традиционные РСУБД – правильный выбор.</p>\n<br/>\n","examples":"<h3>Пример 15. Документ MongoDB вместо трёх таблиц</h3>\n<p><strong>Ситуация.</strong> В реляционной базе информация о студенте хранится в трёх таблицах: <code>students</code>, <code>phones</code>, <code>grades</code>. Чтобы показать карточку студента, нужны две операции JOIN.</p><p>В MongoDB вся информация об объекте хранится в одном документе коллекции <code>students</code>:</p><pre><code>{\n  \"_id\": 1024,\n  \"name\": \"Айгерим Серикова\",\n  \"group\": \"ИС-21\",\n  \"phones\": [\"+7 701 000 00 00\", \"+7 727 000 00 00\"],\n  \"grades\": [\n    {\"course\": \"Анализ больших данных\", \"score\": 92},\n    {\"course\": \"Базы данных\", \"score\": 85}\n  ]\n}</code></pre><p>Основные операции (в оболочке MongoDB):</p><pre><code>db.students.insertOne({ _id: 1025, name: \"Даурен\", group: \"ИС-21\" })\ndb.students.find({ group: \"ИС-21\" })\ndb.students.updateOne({ _id: 1025 }, { $set: { group: \"ИС-22\" } })\ndb.students.deleteOne({ _id: 1025 })</code></pre><p><strong>Что видно из примера:</strong> нет жёсткой схемы (у второго студента нет поля phones), нет JOIN, поле <code>_id</code> обязательно; документ хранится в формате BSON — двоичном аналоге JSON.</p>\n<h3>Пример 16. Выбор между NoSQL и реляционной СУБД</h3>\n<table><tr><th>Система</th><th>Выбор</th><th>Причина</th></tr><tr><td>Бухгалтерия небольшой фирмы</td><td>Реляционная СУБД</td><td>Небольшой объём, нужны транзакции ACID и строгая целостность.</td></tr><tr><td>Анализ логов 2000 серверов</td><td>NoSQL</td><td>Огромные объёмы полуструктурированных данных, горизонтальное масштабирование.</td></tr><tr><td>Каталог интернет-магазина с разными характеристиками товаров</td><td>NoSQL (документная)</td><td>У телефона и у дивана разные поля — жёсткая схема неудобна.</td></tr><tr><td>Система бронирования билетов</td><td>Реляционная СУБД или их совместное использование</td><td>Нельзя продать одно место дважды — нужна транзакционная логика.</td></tr></table>\n","tasks":"<h3>Задание 1. Проектирование коллекции MongoDB</h3>\n<p><strong>Цель:</strong> Научиться переходить от реляционной модели к документной.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Дана реляционная схема блога: authors(id, name), posts(id, author_id, title, text), comments(id, post_id, author, text).</li>\n<li>Спроектируйте документ коллекции posts, включив в него данные автора и комментарии.</li>\n<li>Запишите пример документа в формате JSON.</li>\n<li>Запишите команды MongoDB: добавить пост, найти все посты автора, добавить комментарий к посту, удалить пост.</li>\n<li>Укажите один недостаток вашего решения (например, что делать, если у поста 100 000 комментариев).</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Пример документа, 4 команды и анализ недостатка.</p>\n<p><strong>Форма представления:</strong> Код JSON и команд в моноширинном шрифте, пояснения текстом.</p>\n<details class='hint'><summary>Подсказка</summary><p>Используйте insertOne, find, updateOne с оператором $push, deleteOne.</p></details>\n<h3>Задание 2. Сравнение NoSQL и РСУБД</h3>\n<p><strong>Цель:</strong> Аргументированно выбирать тип базы данных.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Составьте таблицу достоинств и недостатков NoSQL и традиционных БД (не менее трёх пунктов в каждой ячейке).</li>\n<li>Для трёх придуманных систем выберите тип БД и обоснуйте выбор, опираясь на таблицу.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Сравнительная таблица и три обоснованных выбора.</p>\n<p><strong>Форма представления:</strong> Таблица и список.</p>\n","selfcheck":"","questions":[{"id":"q08-1","type":"input","level":1,"text":"В каком формате MongoDB хранит документы? Введите аббревиатуру.","answers":["BSON"],"explain":"BSON — двоичный аналог JSON. Его выбрали из-за скорости разбора данных."},{"id":"q08-2","type":"single","level":1,"text":"Как называется обязательное идентифицирующее поле документа MongoDB?","options":["id","_id","key","oid"],"correct":1,"explain":"У каждого документа есть поле _id."},{"id":"q08-3","type":"truefalse","level":2,"text":"Верно ли, что в репликации master–slave MongoDB подчинённый сервер автоматически занимает место мастера при его отключении?","correct":false,"explain":"Неверно. В master–slave этого не происходит; автоматический выбор нового мастера обеспечивают репликационные множества (replica sets)."},{"id":"q08-4","type":"multiple","level":2,"text":"Какие операции, как правило, не поддерживаются в NoSQL? Отметьте все верные.","options":["JOIN","GROUP BY","Транзакции ACID","Чтение по ключу"],"correct":[0,1,2],"explain":"Большинство NoSQL-систем не поддерживают JOIN, GROUP BY и ACID. Чтение по ключу — базовая операция."},{"id":"q08-5","type":"single","level":3,"text":"Почему традиционные РСУБД плохо подходят под вызовы Big Data?","options":["Они не поддерживают SQL","У них посредственная масштабируемость на сверхвысокую нагрузку и плохая поддержка объёмов более 10–100 ТБ","Они не обеспечивают целостность данных","У них нет теоретического базиса"],"correct":1,"explain":"Также у РСУБД жёсткая схема и сложные JOIN для данных на нескольких узлах."}],"tests":""},"09":{"theory":"<h3>Визуализация данных и</h3>\n<p>Человек – сложная биологическая система, тем не менее, восприятие им информации сильно ограничено, поэтому нужны простые её представления. Принципиальное значение для этого, для ее интерпретации, имеет визуализация. Визуализация - наглядное представление результатов анализа. До сих пор ученые ведут исследования в области совершенствования современных методов представления данных в виде изображений, диаграмм и анимаций.</p>\n<p>Визуализация очень важна в современном мире, особенно с большими объемами данных. Все потому, что во всей получаемой информации существует множество связей и зависимостей, просто так их очень сложно заметить. Кроме того, она дает ответы на многие вопросы гораздо быстрее. К примеру, по колонке цифр не все так хорошо ясно, как по графику.</p>\n<p>На сегодняшний день рост информации достигает невероятных скоростей. Чтобы справиться с возрастающей сложностью и разнообразием данных необходимо использовать визуализацию. Смотреть на цветные картинки всем нравится больше, чем на скучные таблицы с цифрами. Вместе с тем, субъективное восприятие информации, доверие к ней на много выше, когда она подается визуально.</p>\n<br/>\n<p><strong>Рассмотрим области использования визуализации.</strong></p>\n<p><strong>Статистика и отчеты. </strong>Данные за некий период времени показываются вместе. Например, статической картинкой в приложении к отчету или настраиваемым графиком в сервисе статистики, с возможностью изменения параметров его отображения.</p>\n<p><strong>Справочная информация.</strong> Дополнение к основному тексту, наглядно иллюстрирующее его упоминаемыми данными. Например, дать общее представление о динамике одного из показателей, либо отобразить какой-то процесс и его этапы; может быть - показать структуру некоего явления.</p>\n<p><strong>Интерактивные сервисы.</strong> Продукты и проекты, в которых инфографика является частью функциональности. Так, в качестве средства навигации по сервисам может являться диаграмма процесса. Почти все, что связано с работой с картами в специализированных системах вроде диспетчерских и большей части компьютерных игр.</p>\n<p>Иллюстрации. Красивое отображение данных для создания самостоятельных иллюстраций.</p>\n<p><strong>Чертежи и схемы. </strong>Специализированные документы, показывающие структуру и процесс работы сложных инженерных и природных систем</p>\n<p><strong>Эксперименты и искусство. </strong>Визуализация данных в виде сложных и громоздких изображений, которые сложно “прочитать” бегло - объем данных и взаимосвязей между ними таков, что нужно разбираться с картинкой по частям; либо просто абстрактные изображения, автоматически сгенерированные. В последнее время направление все более популярно и периодически выходит за рамки компьютерной графики - например, в виде графиков-скульптур.</p>\n<h3>Типы визуализации</h3>\n<p>Выделим условно три типа визуализации.</p>\n<ul><li><p>Научная визуализация. При моделировании различных объектов или процессов появляются большие объемы данных.</p></li><li><p>Информационная визуализация. Описание/представление некой абстрактной информации, полученной при сборе и обработке многокатегориальных данных, для анализа которых необходимо применять различные количественные и качественные меры оценки.</p></li><li><p>Визуализация работы программного обеспечения.</p></li></ul>\n<p>Задачи визуализации</p>\n<p>Визуализация BigData имеет определенные задачи:</p>\n<ul><li><p>визуализация потоков данных;</p></li><li><p>визуальный интеллектуальный анализ данных;</p></li><li><p>визуальный поиск и рекомендации;</p></li><li><p>описание ситуаций на основе больших данных с использованием визуализации;</p></li><li><p>масштабируемые методы параллельной визуализации;</p></li><li><p>современные аппаратные средства и архитектуры для анализа и визуализации данных;</p></li><li><p>человеко-компьютерный интерфейс и визуализация больших данных;</p></li><li><p>приложения визуализации больших данных.</p></li></ul>\n<h3>Характеристики Big Data</h3>\n<p>Можно сформулировать требования к такого рода визуализации:</p>\n<ul><li><p>оценка пригодности (адекватности в визуализации) видов отображения,</p></li><li><p>естественность (привычность для пользователей),</p></li><li><p>устойчивость к масштабированию,</p></li><li><p>возможность вывода сверхбольших объемов данных,</p></li><li><p>возможности для представления сложных структур, а также объектов особого интереса, особых точек, аттракторов, сингулярностей.</p></li></ul>\n<p>Как решить проблемы визуализации BigData? Необходимо:</p>\n<ul><li><p>использовать достаточно простые, но четко интерпритируемые мотоды представления.</p></li><li><p>формализовывать описания объектов программного обеспечения</p></li><li><p>производить верификацию и валидацию визуализации.</p></li></ul>\n<br/>\n<h2>Традиционные виды визуализации</h2>\n<ul><li><p>Рассмотрим традиционные виды визуализации.</p></li><li><p>Графики и диаграммы</p></li><li><p>Инфографика и схемы</p></li><li><p>Бизнес аналитика и дашборды</p></li><li><p>Научная и медицинская визуализация</p></li></ul>\n<br/>\n","examples":"<h3>Пример 17. Почему график лучше таблицы</h3>\n<p>Таблица посещаемости сайта по месяцам:</p><table><tr><th>Месяц</th><th>Янв</th><th>Фев</th><th>Мар</th><th>Апр</th><th>Май</th><th>Июн</th><th>Июл</th><th>Авг</th><th>Сен</th></tr><tr><td>Визиты, тыс.</td><td>120</td><td>118</td><td>125</td><td>122</td><td>96</td><td>60</td><td>55</td><td>58</td><td>130</td></tr></table><p>По колонке чисел трудно сразу увидеть закономерность. На линейном графике сразу заметен <strong>резкий провал летом</strong> (май–август) и возврат в сентябре. Для сайта университета это объясняется каникулами; для интернет-магазина такой провал был бы тревожным сигналом.</p><p><strong>Вывод.</strong> Визуализация быстрее отвечает на вопрос «что происходит?» и помогает заметить зависимости, которые теряются в таблице.</p>\n<h3>Пример 18. Определение области и типа визуализации</h3>\n<table><tr><th>Ситуация</th><th>Область использования</th><th>Тип визуализации</th></tr><tr><td>График успеваемости в ежегодном отчёте ректора</td><td>Статистика и отчёты</td><td>Информационная</td></tr><tr><td>3D-модель потока воздуха вокруг крыла самолёта</td><td>Чертежи и схемы</td><td>Научная</td></tr><tr><td>Диаграмма вызовов функций при отладке программы</td><td>Чертежи и схемы</td><td>Визуализация работы ПО</td></tr><tr><td>Карта такси в диспетчерской службе</td><td>Интерактивные сервисы</td><td>Информационная</td></tr></table>\n","tasks":"<h3>Задание 1. Анализ визуализаций</h3>\n<p><strong>Цель:</strong> Научиться определять область использования, тип и качество визуализации.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Найдите в открытых источниках (новостные сайты, отчёты, сайты госорганов) 4 визуализации данных разных видов.</li>\n<li>Для каждой определите: область использования (статистика и отчёты, справочная информация, интерактивные сервисы и т. д.), тип (научная, информационная, визуализация ПО), традиционный вид (график, инфографика, дашборд, картограмма…).</li>\n<li>Оцените каждую по требованиям к визуализации Big Data: естественность, устойчивость к масштабированию, чёткость интерпретации.</li>\n<li>Предложите одно улучшение для самой неудачной визуализации.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Описание четырёх визуализаций с оценкой и одно предложение по улучшению.</p>\n<p><strong>Форма представления:</strong> Таблица с изображениями (скриншотами) и ссылками на источники.</p>\n<details class='hint'><summary>Подсказка</summary><p>Обращайте внимание на подписи осей, единицы измерения, легенду и лишние элементы «для красоты».</p></details>\n","selfcheck":"","questions":[{"id":"q09-1","type":"multiple","level":1,"text":"Какие три типа визуализации условно выделяют в лекции? Отметьте все верные.","options":["Научная","Информационная","Визуализация работы программного обеспечения","Музыкальная"],"correct":[0,1,2],"explain":"Выделяют научную, информационную визуализацию и визуализацию работы ПО."},{"id":"q09-2","type":"single","level":1,"text":"Что такое визуализация, согласно лекции?","options":["Хранение данных в виде изображений","Наглядное представление результатов анализа","Сжатие данных","Перевод текста в звук"],"correct":1,"explain":"Визуализация — наглядное представление результатов анализа."},{"id":"q09-3","type":"truefalse","level":2,"text":"Верно ли, что субъективное доверие к информации выше, когда она подаётся визуально?","correct":true,"explain":"Верно, это одна из причин важности визуализации, названных в лекции."},{"id":"q09-4","type":"single","level":2,"text":"К какой области использования визуализации относится графическое дополнение к основному тексту, показывающее динамику показателя?","options":["Статистика и отчёты","Справочная информация","Интерактивные сервисы","Эксперименты и искусство"],"correct":1,"explain":"Справочная информация — дополнение к основному тексту, наглядно иллюстрирующее упоминаемые данные."},{"id":"q09-5","type":"single","level":3,"text":"Что из перечисленного является способом решения проблем визуализации Big Data?","options":["Использовать как можно более сложные трёхмерные представления","Использовать простые, но чётко интерпретируемые методы представления и проводить верификацию визуализации","Отказаться от визуализации больших объёмов","Показывать только таблицы"],"correct":1,"explain":"Лекция называет три меры: простые и чётко интерпретируемые методы, формализация описаний объектов ПО, верификация и валидация визуализации."}],"tests":""},"10":{"theory":"<br/>\n<p>Наверное, самый привычный вид визуализации данных (рисунок 5.1).</p>\n<p>Используется как для презентации данных, так и для анализа. Встретить их можно и на работе, и в журнале, и в научном отчете. Обычно знания о существующих типах диаграмм и графиков мы получаем из школы или из стандартного набора в Excel. Однако мир графиков и диаграмм не ограничивается точечным графиком, столбиковой и круговой диаграммой. Существуют порядка 15 общеизвестных типов диаграмм, а всего их более 60, при этом их количество увеличивается с каждым днём – люди придумывают новые типы для визуализации сложных и необычных данных.</p>\n<img src=\"images/lecture-10-01.png\"/>\n<p>Рисунок 5.1 – Пример визуализации в виде графика</p>\n<h3>Инфографика</h3>\n<p>Инфографика стала очень популярна в последние годы, хотя существуют уже давно. Инфографика относится к журналистике данных, где графики и схемы объясняют какие-либо факты по выбранной теме. Обычно инфографика статична и представляет собой длинную «простыню» с картинками и текстом. Отличительной особенностью инфографики является то, что в ней приводятся уже готовые выводы, то есть читателя проводят за руку по выбранной теме и при этом приправляют это все цифрами и картинками. Часто используется рисованный или анимационный стиль. Часто используется не к месту или «для красоты», хотя конечно же есть замечательные и интересные примеры.</p>\n<br/>\n<h3>Презентация и анализ данных</h3>\n<p>Один самых привычных способов использования визуализации данных - презентация информации в виде диаграмм или инфографики. И если с этим все понятно, то использование визуализации для анализа информации в основном используется только бизнес-аналитиками и учеными. В чем заключается отличие?</p>\n<p>При анализе данных с помощью визуализации используют так называемое быстрое прототипирование – то есть создание большого количества различных визуальных представлений одних и тех же данных. Делается это для возможности нахождения скрытых, на первый взгляд, взаимосвязей и зависимостей, а также первичной оценки набора данных для возможности применения в дальнейшем более сложных инструментов анализа. Этот подход называется Exploratory data analysis (EDA), что на русский можно перевести как разведывательный анализ данных. Основное отличие от презентации данных - визуализация здесь может быть «черновой», но выполняется быстро и одним человеком или небольшой рабочей группой.</p>\n<br/>\n<h3>Интерактивный сторителлинг</h3>\n<p>Сторителлинг – это преподнесение какой-либо полезной информации в форме интересного рассказа. Интерактивный сторителлинг – рассказ, с которым слушатель может взаимодействовать. Пользователь может управлять отображением информации и находить те зависимости, которые не нашёл автор. В этом смысле он близок к разведывательному анализу данных, но отличается тем, что данные заранее обработаны и представлены в удобном для анализа виде, а также имеются подсказки или заранее прописанные сценарии использования.</p>\n<p>Поэтому, чаще всего интерактивный сторителлинг называют интерактивной инфографикой, но для того чтобы ей стать недостаточно просто к статичной инфографике добавить всплывающие окошки.</p>\n<br/>\n<h3>Дашборды и бизнес аналитика</h3>\n<p>Визуализация активно используется в бизнесе. Принцип «говорите с данными» помогает компаниям зарабатывать больше, а клиентам получать лучший сервис. Для разового анализа обычно используется Excel или R. Однако это неудобно если необходимо следит за какими-то показателями на постоянной основе. Для отслеживания используют дашборды – дисплеи, на которых выведены все необходимые показатели в одном месте в виде графиков, диаграмм и таблиц. Проектирование эффективных дашбордов – сложная и неординарная задача. Зачастую их перегружают ненужной информацией или стараются использовать все возможные типы шаблонных графиков. Часто для того, чтобы спроектировать хороший дашборд, необходимо создание новых типов визуализации информации. Тематика активно развивается за счет все большего применения аналитики в бизнесе. Также дашборды применяются и для личного использования (фитнес трекеры, анализ личных расходов и т. п.)</p>\n<img src=\"images/lecture-10-02.png\"/>\n<p>Рисунок 5.2 – Пример дашборда</p>\n<h3>Визуализация в медицине и науке</h3>\n<p>Специфический вид визуализации. Его целью обычно является выделение закономерностей или аномалий. От обычной визуализации данных отличается тем, что часто бывает трёхмерной и требует специальной подготовки для интерпретации.</p>\n<h3>Карты и картограммы</h3>\n<p>Карты – одни из древнейших способов визуализации, отображающих окружающую реальность. Картограмма – карта с нанесенной на неё информацией в виде цвета или других способов. Картограммы могут быть использованы для отображения любой информации – от плотности населения, до частоты использования мобильных телефонов в каждом районе страны.</p>\n<h3>Облако тегов</h3>\n<p>Каждому элементу в облаке тегов присваивается определенный весовой коэффициент, который коррелирует с размером шрифта. В случае анализа текста величина весового коэффициента напрямую зависит от частоты употребления (цитирования) определенного слова или словосочетания.</p>\n<p>Позволяет читателю в сжатые сроки получить представление о ключевых моментах сколько угодно большого текста или набора текстов.</p>\n<h3>Кластерграмма</h3>\n<p>Метод визуализации, использующийся при кластерном анализе (рисунок 5.3). Показывает, как отдельные элементы множества данных соотносятся с кластерами по мере изменения их количества. Выбор оптимального количества кластеров – важная составляющая кластерного анализа.</p>\n<img src=\"images/lecture-10-03.png\"/>\n<p>Рисунок 5.3 – Пример кластерграммы</p>\n<h3>Исторический поток</h3>\n<p>Помогает следить за эволюцией документа, над созданием которого работает одновременно большое количество авторов. В частности, это типичная ситуация для сервисов wiki в том числе. По горизонтальной оси откладывается время. По вертикальной - вклад каждого из соавторов, т.е. объем введенного текста. Каждому уникальному автору присваивается определенный цвет на диаграмме</p>\n<h3>Пространственный поток</h3>\n<p>Используется для отслеживания пространственного изменения информации.</p>\n","examples":"<h3>Пример 19. Выбор вида визуализации под задачу</h3>\n<table><tr><th>Задача</th><th>Вид визуализации</th><th>Почему</th></tr><tr><td>Руководитель ежедневно следит за продажами, остатками и жалобами</td><td>Дашборд</td><td>Все показатели в одном месте, обновляются постоянно.</td></tr><tr><td>Журнал объясняет читателям рост цен на жильё</td><td>Инфографика</td><td>Готовые выводы, проводит читателя по теме.</td></tr><tr><td>Аналитик впервые получил набор данных и ищет зависимости</td><td>Разведывательный анализ (EDA): много «черновых» графиков</td><td>Быстрое прототипирование, визуализация для себя.</td></tr><tr><td>Плотность населения по районам Казахстана</td><td>Картограмма</td><td>Данные привязаны к территории.</td></tr><tr><td>О чём 500 отзывов покупателей?</td><td>Облако тегов</td><td>Быстро показывает ключевые слова большого текста.</td></tr><tr><td>Кто и сколько написал в wiki-статье за год</td><td>Исторический поток</td><td>Время по горизонтали, вклад авторов по вертикали, у каждого свой цвет.</td></tr></table>\n<h3>Пример 20. Расчёт размеров шрифта в облаке тегов</h3>\n<p><strong>Задача.</strong> В отзывах слова встречаются: «доставка» — 120 раз, «цена» — 80, «качество» — 40, «упаковка» — 20. Минимальный размер шрифта — 12 px, максимальный — 48 px. Рассчитаем размер шрифта линейно по частоте (весовому коэффициенту).</p><p>Формула: <code>размер = 12 + (частота − 20) / (120 − 20) × (48 − 12)</code></p><ul><li>доставка: 12 + 100/100 × 36 = <strong>48 px</strong></li><li>цена: 12 + 60/100 × 36 = <strong>33,6 px</strong></li><li>качество: 12 + 20/100 × 36 = <strong>19,2 px</strong></li><li>упаковка: 12 + 0 = <strong>12 px</strong></li></ul><p>Читатель сразу видит, что главная тема отзывов — доставка.</p>\n","tasks":"<h3>Задание 1. Проект дашборда</h3>\n<p><strong>Цель:</strong> Научиться проектировать дашборд без перегрузки лишней информацией.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Выберите пользователя дашборда: декан факультета, владелец кофейни или фитнес-тренер.</li>\n<li>Определите 5–7 показателей, которые этот пользователь должен видеть постоянно.</li>\n<li>Для каждого показателя выберите вид графика и обоснуйте выбор.</li>\n<li>Нарисуйте макет дашборда (от руки или в любом редакторе).</li>\n<li>Укажите, какие показатели вы сознательно НЕ включили и почему.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Макет дашборда и пояснительная таблица.</p>\n<p><strong>Форма представления:</strong> Изображение макета и таблица «Показатель — Вид графика — Обоснование».</p>\n<details class='hint'><summary>Подсказка</summary><p>В лекции отмечено, что дашборды часто перегружают ненужной информацией — избегайте этого.</p></details>\n<h3>Лабораторная работа A4. Визуализация данных</h3>\n<p><strong>Цель: </strong>Научиться строить графики и диаграммы.</p>\n<br/>\n<h4><strong>Задания:</strong></h4>\n<p>1. <strong>Гистограмма</strong></p>\n<h4><strong>Постройте гистограмму распределения значений mpg:</strong></h4>\n<pre><code class=\"language-r\">library(ggplot2)\nggplot(mtcars, aes(x = mpg)) + geom_histogram(binwidth = 2) + labs(title\n= \"Гистограмма MPG\")</code></pre>\n<h4>2. <strong>Диаграмма размаха</strong></h4>\n<h4><strong>Постройте диаграмму размаха для переменной mpg:</strong></h4>\n<pre><code class=\"language-r\">ggplot(mtcars, aes(x = factor(cyl), y = mpg)) + geom_boxplot() + labs(title = \"Диаграмма размаха MPG по цилиндрам\")</code></pre>\n<h4>3. <strong>Точечный график</strong></h4>\n<h4><strong>Постройте точечный график для переменных mpg и wt (вес автомобиля):</strong></h4>\n<pre><code class=\"language-r\">ggplot(mtcars, aes(x = wt, y = mpg)) + geom_point() + labs(title = \"Точечный график MPG vs. Weight\")</code></pre>\n<h3>Лабораторная работа B5. Визуализация данных</h3>\n<p><strong>Цель: </strong>Создать графики для визуализации данных.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Постройте гистограмму для переменной Sepal.Length из набора данных iris.</p>\n<pre><code class=\"language-r\">library(ggplot2)\nggplot(iris, aes(x = Sepal.Length)) + geom_histogram(binwidth = 0.5) + labs(title = \"Гистограмма Sepal.Length\")</code></pre>\n<p>2. Постройте диаграмму размаха для переменной Sepal.Length.</p>\n<pre><code class=\"language-r\">ggplot(iris, aes(x = \"\", y = Sepal.Length)) + geom_boxplot() + labs(title = \"Диаграмма размаха Sepal.Length\")</code></pre>\n","selfcheck":"","questions":[{"id":"q10-1","type":"input","level":1,"text":"Как называется подход к анализу с помощью быстрого создания множества «черновых» визуализаций? Введите английскую аббревиатуру.","answers":["EDA"],"explain":"EDA — Exploratory Data Analysis, разведывательный анализ данных."},{"id":"q10-2","type":"single","level":1,"text":"Сколько всего существует типов диаграмм, по данным лекции?","options":["Около 15","Более 60","Ровно 3","Около 1000"],"correct":1,"explain":"Общеизвестных типов около 15, а всего их более 60, и число растёт."},{"id":"q10-3","type":"truefalse","level":2,"text":"Верно ли, что для превращения статичной инфографики в интерактивный сторителлинг достаточно добавить всплывающие окна?","correct":false,"explain":"Неверно. Интерактивный сторителлинг позволяет пользователю управлять отображением и находить новые зависимости; одних всплывающих окон недостаточно."},{"id":"q10-4","type":"single","level":2,"text":"Какой метод визуализации показывает, как элементы множества данных соотносятся с кластерами по мере изменения их количества?","options":["Облако тегов","Кластерграмма","Исторический поток","Картограмма"],"correct":1,"explain":"Кластерграмма помогает выбрать оптимальное количество кластеров."},{"id":"q10-5","type":"multiple","level":3,"text":"Чем визуализация в медицине и науке отличается от обычной? Отметьте все верные.","options":["Часто бывает трёхмерной","Требует специальной подготовки для интерпретации","Всегда содержит готовые выводы для читателя","Обычно нацелена на выделение закономерностей или аномалий"],"correct":[0,1,3],"explain":"Готовые выводы — отличительная черта инфографики, а не научной визуализации."}],"tests":""},"11":{"theory":"<p>Типы данных языка R: вектор, матрица, список, таблица данных. Статистические функции: cреднее, медиана, дисперсия, стандартное отклонение, межквантильный размах.</p>\n<p>Из стандартных операторов можно выделить суммирование, разность, умножение, деление, возведение в степень, остаток от деления, целочисленное деление, логические операции.</p>\n<p>Язык легко встраивается в OracleDB благодаря 100% совместимости с R- интефейсом и клиентскими приложениями. Данные сохраняются и статические вычисления уже выполняются в базе данных.</p>\n<br/>\n<h3>Amazon S3</h3>\n<p>Рассмотрим Amazon S3 (где S3 расшифровывается, как Simple Storage Service). Это веб-служба, предлагаемая AmazonWebServices, она предоставляет возможность хранения и получения любого объема данных в любое время из любой точки земного шара. Это очень надежное средство хранения объектов, которое легко масштабируется и отлично подходит для разработчиков. Оно очень удобно и оснащено простым интерфейсом. Платить придется только за используемый объем. Также есть бесплатная версия на 1 год.</p>\n<br/>\n<h3>Достоинства Amazon S3</h3>\n<ul><li><p>Доступность – AWS будет работать всегда</p></li><li><p>Масштабирование – не нужно решать сложные задачи распределения файлов между серверами</p></li><li><p>Нагрузка – внезапные всплески популярности не приведут к отказу железа</p></li><li><p>Надежность – предоставляется практически 100% гарантия целостности и доступности.</p></li><li><p>Общий объем хранимых данных и количество объектов неограничены</p></li><li><p>Размер отдельных объектов Amazon S3 может быть от 1 байта до 5 терабайт</p></li><li><p>Самый крупный объект, который можно загрузить через один запрос – 5 гигабайт.</p></li><li><p>Для объектов крупнее 100 мегабайт клиентам рекомендуется использовать функцию многокомпонентной загрузки.</p></li></ul>\n<h3>Язык R</h3>\n<p>Это интуитивно понятный язык сценариев. Позволяет импортировать и использовать большое количество пакетов для анализа и визуализации. Для подобного основанного на модели анализа можно также использовать другие научные инструменты визуализации, такие как, например, MATLAB, но R содержит различные пакеты, хорошо выполняющие многомерный анализ наборов данных, не являющихся научными по своей природе (визуализация бизнес-аналитики).</p>\n<p>Существует язык, основанный на R, который предназначен для статистических исследований и работы с графикой. Это opensource проект R</p>\n<p>Foundation. Широкий спектр различных функций (временные ряды, прогнозирование, классификация, кластеризация и др.). Важное отличие в том, что доступны простые средства построения самых сложных графиков и диаграмм. А также возможность расширения благодаря технологии разработки дополнительных пакетов участниками проекта</p>\n<h2>Отличия языка R</h2>\n<p>Инструменты, подобные MATLAB, предоставляют среду интерактивного научного и инженерного анализа для исследования моделей и данных инженерам и ученым; R предоставляет те же средства бизнес- аналитикам и аналитикам больших данных всех типов. Возможность интерактивного исследования больших данных при помощи таких инструментов, как R и BigQuery, отличает анализ больших данных от пакетного и глубинного анализа данных, которые часто выполняются с помощью MapReduce. В любом случае целью является формирование новых моделей и поддержка принятия решений с использованием больших данных.</p>\n<h2>Основные возможности R</h2>\n<ul><li><p>Можно вводить команды одну за другой в командной строке (&gt;) или запустить последовательность команд из файла-источника</p></li><li><p>Язык R содержит огромное количество различных типов данных, включая векторы (числовые, строковые, логические), матрицы, блоки данных и списки</p></li><li><p>Гибкость языка R обеспечивается посредством встроенных и пользовательских функций. Во время работы с R все пользовательские данные хранятся в памяти программы</p></li><li><p>Базовые функции доступны по умолчанию. Другие функции содержатся в особых статистических пакетах и могут быть загружены во время работы</p></li><li><p>R содержит встроенные базы данных, которые можно использовать для обучения</p></li></ul>\n<h3>Многокомпонентная загрузка</h3>\n<p>При многокомпонентной загрузке файл загружается по частям последовательно или параллельно через специальный API. Есть возможность шифрования данных при загрузке. Преимущества многокомпонентной загрузки: увеличение пропускной способности; быстрое восстановление загрузки при отказе машины (или сети); возможность приостановить и возобновить загрузку; возможность загрузки объекта в момент его создания.</p>\n<p>Загрузка проходит в 3 этапа</p>\n<ul><li><p>Инициирование загрузки</p></li><li><p>Загрузка всех частей файла</p></li><li><p>Завершение загрузки</p></li></ul>\n<p>После этого Amazon S3 строит объект (файл) из загруженных частей. Шифрование данных используется:</p>\n<ul><li><p>На стороне сервера (передача через SSL, Amazon S3 шифрует данные при записи, расшифровывает при чтении)</p></li><li><p>На стороне клиента (клиент сам шифрует данные, отправляет их в S3, управляя процессом шифрования, Amazon предоставляет соответствующий API)</p></li></ul>\n<h2>Особенности хранения в S3</h2>\n<p>Файлы хранятся в отдельных бакетах, в которых можно создавать директории и поддиректории (бакет - некоторый контейнер, содержащий директории и файлы; часть в файловой системе S3)</p>\n<ul><li><p>Бакеты хранятся в разных регионах (Region; регионы – ЦОД в различных регионах мира (США, Европа, Азия), есть возможность выбора региона)</p></li><li><p>Уникальные ключи</p></li><li><p>При хранении данных объектам назначается уникальный ключ, который может использоваться впоследствии для доступа к данным.</p></li><li><p>Ключ назначает пользователь.</p></li><li><p>Для запроса файла необходимо знать бакет, где он находится, и его ключ.</p></li><li><p>Ключи могут быть любой строкой кодировки UTF-8 не более 1024 байт, могут быть созданы таким образом, чтобы имитировать иерархические атрибуты</p></li><li><p>Ключи уникальны внутри одного бакета</p></li><li><p>Логирование (S3 может логировать запросы и складывать отчёты в отдельный бакет)</p></li><li><p>Версионирование (S3 предполагает версионность файлов, всегда можно восстановить файл предыдущей версии, т.е. откатиться до нужного состояния).</p></li></ul>\n<p>В S3 используется свободная масштабируемость. S3 автоматически масштабируется в зависимости от потребностей клиентов. Amazon предлагает не беспокоиться о возможностях масштабируемости системы и предоставляет гарантию на то, что резкий всплеск данных в хранилище не создаст никаких проблем.</p>\n<h2>Дедупликация данных</h2>\n<p>Дедупликация – технология, при помощи которой обнаруживаются и исключаются избыточные данные в дисковом хранилище. Есть два способа дедупликации:</p>\n<ul><li><p>Онлайн дедупликация (может осуществляться непосредственно в момент записи данных на диски (данные кэшируются))</p></li><li><p>Оффлайн дедупликация (может быть реализована «постпроцессом», в фоновом режиме после записи данных на диск)</p></li></ul>\n<p>Хорошо подходят для дедупликации резервные копии, виртуальные машины, любые данные с большим количеством повторяющихся блоков. Плохо подходят для дедупликации картинки, музыка, видео, сжатые данные.</p>\n<p>Сравним два способа дедупликации – онлайн и офлайн.</p>\n<p>Плюсы «оффлайн» дедупликации (минусы «онлайн» дедупликации):</p>\n<ul><li><p>можем использовать более эффективные и точные алгоритмы обнаружения дубликатов данных;</p></li><li><p>не нужно идти на компромиссы, чтобы не перегрузить работой процессор и не снизить производительность работы системы хранения с дедупликацией;</p></li><li><p>можем анализировать и обрабатывать значительно большие объемы данных;</p></li><li><p>можем делать дедупликацию тогда и там, когда и где удобно.</p></li></ul>\n<p>Минусы «оффлайн» дедупликации (плюсы «онлайн» дедупликации):</p>\n<ul><li><p>eсли записывать сильно дуплицированные данные (например, 90% - дупликаты), придется сначала выделить на запись место, заполнить его дупликатами, и лишь потом, в ходе процесса дедупликации, 90% этого пространства освободится;</p></li><li><p>повышается стоимость сервиса за счет использования трафика на 90% дуплицированных данных, запросов на обращение к этим же данным (для сравнения), запросов на удаление.</p></li></ul>\n<p>Таким образом, дешевле использовать «онлайн» дедупликацию, но это крайне медленно. Удобнее и эффективнее использовать «оффлайн» дедупликацию, но это дороже.</p>\n<p>Предлагается использовать оффлайн дедупликацию с временным хранилищем:</p>\n<ul><li><p>Данные с клиента записываются во временное хранилище (не в S3, а в другое (например, на основе HDFS))</p></li><li><p>Запускается “постпроцессная” дедупликация в хранилище</p></li><li><p>Данные дедуплицируются</p></li><li><p>Дедуплицированные данные загружаются в S3</p></li></ul>\n<p>Временное хранилище очищается</p>\n<p>Таким образом, достигается оптимальное соотношение между двумя подходами: минимизация стоимости, увеличение производительности (можно дедуплицировать, когда необходимо), увеличение скорости работы системы.</p>\n<p>Рассмотрим традиционный алгоритм дедупликации:</p>\n<ul><li><p>Входные данные разбиваются на блоки по определенному алгоритму и на блоки определенного размера.</p></li><li><p>Для каждого блока вычисляется хеш-функции (используются различные алгоритмы вычисления).</p></li><li><p>Хеш сравнивается с существующими (хэш хранится в таблицах).</p></li><li><p>Если хеш существует, то заменяем данные на ссылку.</p></li></ul>\n<p>Каждая служба облачной дедупликации (CDS) должна иметь:</p>\n<ul><li><p>Веб интерфейс</p></li><li><p>Модуль приема данных</p></li><li><p>Алгоритм дедупликации данных для записи и чтения</p></li><li><p>Алгоритм вычисления хэш-функцииМесто хранения</p></li></ul>\n<p>У службы должны быть следующие характеристики:</p>\n<ul><li><p>Гибкость</p></li><li><p>Доступность</p></li><li><p>Балансировка нагрузки</p></li></ul>\n<p>Каждый модуль должен хорошо сочетаться с облачной архитектурой.</p>\n<br/>\n","examples":"<h3>Пример 21. Основные типы данных и статистические функции R</h3>\n<pre><code class=\"language-r\"># вектор\nscores <- c(78, 92, 85, 60, 92, 71)\n\n# статистические функции\nmean(scores)     # среднее: 79.67\nmedian(scores)   # медиана: 81.5\nvar(scores)      # дисперсия\nsd(scores)       # стандартное отклонение\nIQR(scores)      # межквартильный размах\n\n# матрица 2 x 3\nm <- matrix(1:6, nrow = 2)\n\n# список с элементами разных типов\nstudent <- list(name = \"Асель\", age = 20, scores = scores)\n\n# таблица данных (data frame)\ndf <- data.frame(name = c(\"Асель\", \"Ерлан\"), score = c(92, 78))\nsummary(df)\n\n# операторы\n7 %% 3    # остаток от деления: 1\n7 %/% 3   # целочисленное деление: 2\n2 ^ 10    # возведение в степень: 1024</code></pre><p>Вектор хранит значения одного типа, список — значения разных типов, а таблица данных (data frame) — столбцы-векторы одинаковой длины.</p>\n<h3>Пример 22. Многокомпонентная загрузка и дедупликация в S3</h3>\n<p><strong>Задача 1.</strong> Нужно загрузить в Amazon S3 видеофайл 12 ГБ и резервную копию 300 МБ.</p><ul><li>12 ГБ больше 5 ГБ — один запрос не подходит, <strong>многокомпонентная загрузка обязательна</strong>. Например, 120 частей по 100 МБ: инициирование → загрузка частей (можно параллельно) → завершение, после чего S3 соберёт объект.</li><li>300 МБ можно загрузить одним запросом, но так как файл больше 100 МБ, <strong>рекомендуется</strong> многокомпонентная загрузка: при обрыве сети повторно загружается только одна часть.</li></ul><p><strong>Задача 2.</strong> Резервная копия разбита на 6 блоков с хешами: A1, B7, A1, C3, B7, A1. Сколько блоков реально нужно хранить после дедупликации?</p><ul><li>Уникальные хеши: A1, B7, C3 — <strong>3 блока</strong>; остальные 3 заменяются ссылками.</li><li>Экономия места: 3 из 6 блоков, то есть <strong>50%</strong>.</li></ul><p>Резервные копии хорошо поддаются дедупликации; видео и сжатые данные — плохо, так как повторяющихся блоков в них почти нет.</p>\n","tasks":"<h3>Задание 1. Схема хранения данных в Amazon S3</h3>\n<p><strong>Цель:</strong> Применить понятия бакета, ключа, региона, версионирования и дедупликации.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Университет хранит в S3 видеолекции (по 2–8 ГБ), сканы документов и еженедельные резервные копии базы данных.</li>\n<li>Предложите структуру бакетов и пример ключей объектов, имитирующих иерархию (например, «2025/ИС/lecture-01.mp4»).</li>\n<li>Укажите, для каких объектов нужна многокомпонентная загрузка и почему.</li>\n<li>Решите, для каких данных применять дедупликацию — онлайн или оффлайн — и обоснуйте выбор.</li>\n<li>Объясните, как версионирование поможет при случайном удалении файла.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Схема бакетов с примерами ключей и обоснованные решения по загрузке, дедупликации и версионированию.</p>\n<p><strong>Форма представления:</strong> Схема (дерево бакетов и ключей) и пояснения списком.</p>\n<details class='hint'><summary>Подсказка</summary><p>Ключи уникальны внутри бакета, их длина — до 1024 байт в UTF-8.</p></details>\n<h3>Лабораторная работа A1. Введение в RStudio</h3>\n<p><strong>Цель: </strong>Ознакомиться с интерфейсом RStudio, базовыми операциями и командами в R.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. <strong>Запуск и знакомство с RStudio</strong></p>\n<p>Откройте RStudio и изучите основные панели: консоль, скрипты, среды и графики.</p>\n<h4>2. <strong>Работа с консолью</strong></h4>\n<h4><strong>Введите следующие команды в консоли и проанализируйте результаты:</strong></h4>\n<pre><code class=\"language-r\">1 + 1\nsqrt(16)</code></pre>\n<h4>3. <strong>Создание и сохранение скрипта</strong></h4>\n<h4><strong>Создайте новый R скрипт (File -&gt; New File -&gt; R Script). Напишите и сохраните следующий код:</strong></h4>\n<pre><code class=\"language-r\">x &lt;- 10\ny &lt;- 20\nz &lt;- x + y\nprint(z)</code></pre>\n<h4>4. <strong>Использование функций справки</strong></h4>\n<h4><strong>Получите справочную информацию о функции mean():</strong></h4>\n<pre><code class=\"language-r\">?mean</code></pre>\n<h4>5. <strong>Работа с переменными</strong></h4>\n<h4><strong>Создайте переменную a и присвойте ей значение 5. Затем измените значение a на 10 и выведите его:</strong></h4>\n<pre><code class=\"language-r\">a &lt;- 5\na &lt;- 10\nprint(a)</code></pre>\n<h3>Лабораторная работа A2. Обработка данных</h3>\n<p><strong>Цель: </strong>Научиться загружать, очищать и предобрабатывать данные.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. <strong>Загрузка данных</strong></p>\n<h4><strong>Загрузите набор данных mtcars и просмотрите его:</strong></h4>\n<pre><code class=\"language-r\">data(mtcars)\nhead(mtcars)</code></pre>\n<h4>2. <strong>Очистка данных</strong></h4>\n<h4><strong>Удалите строки с пропущенными значениями (если есть):</strong></h4>\n<pre><code class=\"language-r\">mtcars_clean &lt;- na.omit(mtcars)</code></pre>\n<h4>3. <strong>Создание нового столбца</strong></h4>\n<h4><strong>Добавьте новый столбец в mtcars, который будет содержать среднее значение всех числовых столбцов:</strong></h4>\n<pre><code class=\"language-r\">mtcars_clean$mean_value &lt;- rowMeans(mtcars_clean[, sapply(mtcars_clean, is.numeric)])\nhead(mtcars_clean)</code></pre>\n<h4>4. <strong>Изменение значений</strong></h4>\n<h4><strong>Измените значения в столбце mpg (милей на галлон) на 20% больше и выведите результат:</strong></h4>\n<pre><code class=\"language-r\">mtcars_clean$mpg &lt;- mtcars_clean$mpg * 1.2\nhead(mtcars_clean)</code></pre>\n<h3>Лабораторная работа B1. Основы работы с RStudio</h3>\n<p><strong>Цель: </strong>Ознакомиться с основами работы в RStudio.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Откройте RStudio и исследуйте основные панели (Консоль, Скрипты, Графики, Среда).</p>\n<p>2. Создайте новый R-скрипт и выполните простые математические операции: сложение, вычитание, умножение и деление.</p>\n<p>3. Сохраните скрипт с расширением .R.</p>\n<h3>Лабораторная работа B2. Работа с данными</h3>\n<p><strong>Цель: </strong>Загрузить и просмотреть набор данных.</p>\n<h4><strong>Задания:</strong></h4>\n<h4>1. <strong>Загрузите встроенный набор данных iris и выведите его на экран.</strong></h4>\n<pre><code class=\"language-r\">data(iris)\nhead(iris)</code></pre>\n<h4>2. <strong>Сохраните набор данных iris в CSV-файл.</strong></h4>\n<pre><code class=\"language-r\">write.csv(iris, \"iris_data.csv\", row.names = FALSE)</code></pre>\n<h3>Лабораторная работа B3. Очистка данных</h3>\n<p><strong>Цель: </strong>Научиться очищать данные и обрабатывать пропуски.</p>\n<br/>\n<h4><strong>Задания:</strong></h4>\n<h4>1. <strong>Создайте набор данных с пропущенными значениями.</strong></h4>\n<pre><code class=\"language-r\">data_with_na &lt;- data.frame(\nA = c(1, 2, NA, 4),\nB = c(NA, 2, 3, 4)\n)</code></pre>\n<h4>2. <strong>Заполните пропущенные значения средними значениями.</strong></h4>\n<pre><code class=\"language-r\">data_with_na[is.na(data_with_na)] &lt;- sapply(data_with_na, function(x) mean(x, na.rm = TRUE))</code></pre>\n<h3>Лабораторная работа B6. Сводные таблицы</h3>\n<p><strong>Цель: </strong>Создать сводные таблицы для анализа данных.</p>\n<br/>\n<h4><strong>Задания:</strong></h4>\n<h4><strong>1. Создайте сводную таблицу, которая показывает среднее значение переменной Sepal.Length по группам из переменной Species.</strong></h4>\n<pre><code class=\"language-r\">library(dplyr)\niris_summary &lt;- iris %&gt;%\ngroup_by(Species) %&gt;%\nsummarise(mean_sepal_length = mean(Sepal.Length))\nprint(iris_summary)</code></pre>\n<h3>Лабораторная работа B7. Фильтрация и сортировка данных</h3>\n<p><strong>Цель: </strong>Научиться фильтровать и сортировать данные.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Отфильтруйте строки набора данных iris, где Sepal.Length больше 5.5.</p>\n<pre><code class=\"language-r\">filtered_iris &lt;- iris %&gt;% filter(Sepal.Length &gt; 5.5)</code></pre>\n<p>2. Отсортируйте данные по убыванию переменной Sepal.Length.</p>\n<pre><code class=\"language-r\">sorted_iris &lt;- iris %&gt;% arrange(desc(Sepal.Length))</code></pre>\n<h3>Лабораторная работа B8. Работа с датами</h3>\n<p><strong>Цель: </strong>Научиться работать с датами в R.</p>\n<h4><strong>Задания:</strong></h4>\n<h4><strong>1. Создайте вектор дат и найдите разницу между двумя датами.</strong></h4>\n<pre><code class=\"language-r\">dates &lt;- as.Date(c(\"2023-01-01\", \"2024-01-01\"))\ndiff &lt;- difftime(dates[2], dates[1], units = \"days\")</code></pre>\n","selfcheck":"","questions":[{"id":"q11-1","type":"multiple","level":1,"text":"Какие типы данных языка R названы в лекции? Отметьте все верные.","options":["Вектор","Матрица","Список","Таблица данных","Указатель"],"correct":[0,1,2,3],"explain":"В R нет указателей как типа данных; основные типы — вектор, матрица, список, таблица данных."},{"id":"q11-2","type":"input","level":1,"text":"Что вернёт выражение R: 17 %% 5 ? Введите число.","answers":["2"],"explain":"%% — остаток от деления: 17 = 3 × 5 + 2."},{"id":"q11-3","type":"single","level":2,"text":"Каков максимальный размер одного объекта Amazon S3?","options":["5 ГБ","100 МБ","5 ТБ","Не ограничен"],"correct":2,"explain":"Объект может иметь размер от 1 байта до 5 ТБ. 5 ГБ — это максимум для загрузки одним запросом."},{"id":"q11-4","type":"truefalse","level":2,"text":"Верно ли, что видео и сжатые данные хорошо подходят для дедупликации?","correct":false,"explain":"Неверно. В них мало повторяющихся блоков. Хорошо подходят резервные копии и образы виртуальных машин."},{"id":"q11-5","type":"single","level":3,"text":"Какой подход к дедупликации предлагается в лекции как оптимальный?","options":["Только онлайн-дедупликация","Оффлайн-дедупликация с временным хранилищем (например, на основе HDFS) и последующей загрузкой в S3","Отказ от дедупликации","Дедупликация на стороне клиента вручную"],"correct":1,"explain":"Данные пишутся во временное хранилище, дедуплицируются «постпроцессом», загружаются в S3, а хранилище очищается."}],"tests":""},"12":{"theory":"<p>Определение DataMining</p>\n<p>Data Mining (добыча данных, интеллектуальный анализ данных (ИАД), глубинный анализ данных) – собирательное название, используемое для обозначения совокупности методов обнаружения в данных ранее неизвестных, нетривиальных, практически полезных и доступных интерпретации знаний, необходимых для принятия решений в различных сферах человеческой деятельности. Термин введён Григорием Пятецким-Шапиро в 1989 году.</p>\n<h2>Предмет интереса для анализа</h2>\n<ul><li><ul><li>Нетривиальные знания</li></ul>\n</li><li><ul><li>Неявные зависимости</li></ul>\n</li><li><ul><li>Ранее неизвестные знания</li></ul>\n</li><li><ul><li>Практически полезные знания</li></ul>\n</li><li><ul><li>Доступные для интерпретации</li></ul>\n</li></ul>\n<br/>\n<img src=\"images/lecture-12-01.png\"/>\n<p>Рисунок 6.1 – Ключевые шаги DataMining</p>\n<h2>Отличия от традиционного анализа</h2>\n<ul><li><ul><li><ul><li><ul><li><p>Огромные объемы данных (требуются масштабированные алгоритмы для террабайтных БД)</p></li><li><p>Данные высокой размерности (до десятков тысяч измерений)</p></li><li><p> Высокая сложность данных</p></li><li><p> Данные временных рядов, временные данные, данные последовательностей событий</p></li><li><p>Структурные данные, графики, социальные отношения, данные со множественными ссылками</p></li><li><p>Гетерогенные источники данных, БД</p></li><li><p> Пространственные, пространственно-временные, мультимедиа, текстовые и Web-данные</p></li></ul></li></ul></li></ul></li></ul>\n<h2>Задачи ИАД</h2>\n<p>Описательные: наглядное описание имеющихся скрытых закономерностей</p>\n<p>Предсказательные: предсказание для тех случаев, для которых данных ещё нет</p>\n<h2>Виды ИАД</h2>\n<ul><li><p>Выявление ассоциативных связей</p></li><li><p>Определение закономерностей в событиях или процессах</p></li><li><p>Ассоциативная связь различных фактов одного событияРезультат:</p></li><li><p>Лучшее понимание природы процессов</p></li><li><p>Прогнозирование новых событий</p></li><li><p>Кластеризация объектов</p></li><li><p>Разделение исследуемого множества объектов на группы (кластеры) по принципу сходства.</p></li><li><p>В процессе кластеризации методами ИАД определяются схожие характеристики объектов, на их основе объекты объединяются.</p></li><li><p>Классификация</p></li><li><p>Отнесение объектов к одному из известных классов на основе их характеристик</p></li><li><p>Задачи регрессии</p></li><li><p>Задача определения значения одного из параметров анализируемого объекта на основе других характеристик</p></li><li><p>Все характеристики - количественные</p></li></ul>\n<h2>Типы Data Minig</h2>\n<p>Сфера применения Data Mining ничем не ограничена, Data Mining нужен везде, где имеются какие-либо данные.</p>\n<ul><li><p>Анализ рыночных корзин</p></li><li><p>Управление взаимоотношениями с клиентами</p></li><li><p>Анализ текстовой информации (Text Mining)</p></li><li><p>Анализ информации, порождаемой в сети Интернет (Web Mining)</p></li><li><p>Анализ социальных медиа (Social Mining)</p></li></ul>\n<p>Анализ рыночной корзины (market basket analysis) – это поиск наиболее типичных, шаблонных покупок в супермаркетах (поиск ассоциативных правил).</p>\n<p>Анализ рыночной корзины производится путем анализа баз данных с целью определения комбинаций товаров, которые связанны между собой. В каждой такой паре один товар будет ключевым, а товар, покупаемый вместе с ним – сопутствующим.</p>\n<p>Подобный анализ позволит выявить частоту покупки парных товаров, а также вероятность с которой сопутствующий товар покупается вместе с ключевым.</p>\n<br/>\n<h2>Text Mining</h2>\n<p>Анализ структурированной информации (например, в БД) уже довольно непростая задача. Но не все виды данных можно успешно структурировать. Например, текстовые документы практически невозможно структурировать без потери семантики и смысловых отношений.</p>\n<p>Методы анализа текстов лежат на стыке нескольких областей:</p>\n<ul><li><p>Data Mining</p></li><li><p>обработкаестественныхязыков (NLP - Natural Language Processing)</p></li><li><p>поиск и извлечение информации</p></li></ul>\n<br/>\n<p>Text Mining – это нетривиальный процесс обнаружения действительно новых, потенциально полезных и понятных шаблонов в неструктурированных текстовых данных. Ключевая особенность - \"неструктурированные текстовые данные\".</p>\n<p>Ключевые задачи интеллектуального анализа текстов:</p>\n<ul><li><p>Категоризация текстов, классификация</p></li><li><p>Извлечение информации и информационный поиск</p></li></ul>\n<br/>\n<h2>Web Mining</h2>\n<p>Web Mining – это использование методов интеллектуального анализа данных (Data mining, ИАД) для автоматического обнаружения веб-документов и услуг, извлечения информации из веб-ресурсов и сервисов.</p>\n<p>Веб-пространство – огромная, широко распространенная информационная сеть, которая включает:</p>\n<ul><li><p>Информационные сервисы</p></li><li><p>Новости, реклама, потребительская информация</p></li><li><p>Финансовые рынки, образовнаие, правительство</p></li><li><p>Электронная коммерция, развлекательные ресурсы, социальные медиа</p></li><li><p>Гипер-текстовая информация (Hyperlinks)</p></li><li><p>База данных статистики использования ресурсов Веб-информация – это:</p></li><li><p>Web Content – текст, изображения, таблицы и т.д.</p></li><li><p>Web Structure – гиперссылки, тэги, и т.д.</p></li><li><p>Web Usage – логи веб-серверов, прокси</p></li></ul>\n<br/>\n<p>Выделяют различные категории Web Mining в зависимости от предмета интереса:</p>\n<ul><li><p>Web Content Mining – извлечение знаний непосредственно из контента</p></li><li><p>Web Usage Mining – анализ использования веб-ресурсов</p></li><li><p>Web Structure Mining – выявление моделей, лежащих в основе ссылочной структуры сети</p></li></ul>\n<h2>Web Content Mining</h2>\n<p>Задача: автоматизация поиска информационных ресурсов в Интернете, включая в себя добычу содержимого из веб-данных</p>\n<p>Веб-данные:</p>\n<ul><li><p>Текст</p></li><li><p>Изображения</p></li><li><p>Аудио-данные</p></li><li><p>Видео-данные</p></li><li><p>Мета-данные и гиперссылки</p></li></ul>\n<h2>Web usage analysis</h2>\n<p>Каждая страница содержит какую-либо информацию. Гиперссылка – своеобразная “связь” между двумя страницами. Изучая поток кликов по ссылкам, можно понять, как пользователи перемещаются по веб-страницам, шаблоны их поведения</p>\n<h2>Web Usage Mining (анализ кликов)</h2>\n<p>Зачем анализировать использование веб-сайта, понимать паттерны пользователей?</p>\n<ul><li><p>Улучшение клиенто-ориентированности веб-сайта</p></li><li><p>Помощь в предотвращении дезориентации</p></li><li><p>Лучшие практики по размещению важной информации на странице (именно там, где ее ищет пользователь)</p></li><li><p>Предварительная загрузка и кеширование необходимых веб-страниц Вопросы, на которые можно получить ответы:</p></li><li><p>Есть ли различия в шаблонах действий различных пользователей, от чего они зависят?</p></li><li><p>Как меняется поведение пользователей с течением времени?</p></li><li><p>Как распределяется сетевая нагрузка в течение дня?</p></li></ul>\n<h2>Web structure mining</h2>\n<p>Гиперссылки – ключевая часть технологии Интернет. Через ссылки выражается взаимосвязь между отдельными веб-страницами. Внутри модели связи страниц в Интернете также могут лежать значимые знания и законы.</p>\n<p>Web Structure Mining – это процесс выявления структуры ссылок и модели, лежащей в основе ссылочной структуры в Интернете.</p>\n<p>Что может Web Structure Mining?</p>\n<ul><li><p>Модель, основанная на топологии гиперссылки может быть использована для классификации Веб-страницы (отнесения ее к какой-либо категории)</p></li><li><p>Получение информации о сходстве и отношениях между веб-сайтами</p></li><li><p>Определение наиболее авторитетных страниц по отношению к заданным критериям поиска.</p></li><li><p>Данный подход широко используется в веб-поиске и ранжировании страниц. (поисковые системы)</p></li></ul>\n<h2>Social media mining</h2>\n<p>Social Media – массовая коммуникация посредством сети Интернет. Изначальная идея – приложения в сети Интернет, основанные на идеях Web 2.0, позволяющие создавать и обмениваться пользовательским контентом (user- generated content). Большое количество такого контента сейчас создается на таких ресурсах, как Facebook, Twitter, Google+.</p>\n<p>Системный анализ, поиск скрытых ценных знаний из социальных медиа – Social Data Mining.</p>\n<p>Особенности:</p>\n<ul><li><p>Пользовательской информации очень много</p></li><li><p>Но и “шумов” в ней тоже много</p></li><li><p>Распределена по разным источникам</p></li><li><p>Слабоструктурированная, а большинство не структурирована вовсе</p></li><li><p>Динамичная, обновляется постоянно</p></li></ul>\n<h2>Почему важно?</h2>\n<ul><li><p>Каждый день количество информации, размещенной пользователями растет, очень малое количество обрабатывается</p></li><li><p>Платформа для маркетинга и рекламы</p></li><li><p>Моделирование поведенческих законов</p></li><li><p>Предсказательный анализ</p></li><li><p>Рекомендательный контент</p></li></ul>\n<h2>RapidMiner</h2>\n<p>RapidMiner – инструмент, созданный для Data Mining. Основная идея – аналитик не должен программировать при выполнении своей работы.</p>\n<ul><li><p>Свободная лицензия, Open Source</p></li><li><p>Разработан на Java, кроссплатформенность</p></li></ul>\n<p>Доступен на Github Достоинства:</p>\n<ul><li><p>Достаточно хороший набор операторов, решающих большой спектр задач получения информации из разнообразных источников</p></li><li><p>Базы данных</p></li><li><p>Файлы</p></li><li><p>URL</p></li><li><p>Большая коллекция операторов обработки информации</p></li><li><p>Фильтрация</p></li><li><p>Аггрегация</p></li><li><p>Сортировка Недостатки:</p></li><li><p>Несмотря на обилие моделей анализа в стандартном пакете, иногда их бывает недостаточно для выполнения сложных задач</p></li><li><p>Нет возможности добавлять собственные модели и операции</p></li></ul>\n<p>Идея – визуальное программирование. Процесс – совокупность операторов, соединенных между собой в заданном порядке для выполнения требуемой задачи анализа/обработки данных. Оператор – логическая единица процесса. Оператор производит действия над данными. У него есть вход-выход («порты»), на вход приходят данные, на выход идут обработанные оператором данные. Несколько операторов в рамках процесса позволяют составлять цепочки обработки данных. К примеру, начать с считывания транзакций из БД, найти самые большие, сконвертировать в доллары и выдать результат. Цепочки операторов возможно параллелить.</p>\n<p>Можно с уверенностью говорить, что RapidMiner – полноценный инструмент для ETL. Спектр решаемых задач:</p>\n<ul><li><p>Сбор информации с источников (файлы, БД, URL и др.)</p></li><li><p>Простая статистическая обработка данных (фильтрация, агрегация, и т.д.)</p></li><li><p>Аналитическое моделирование (классификация, нейронные сети и т.д.)</p></li><li><p>Валидация моделей</p></li><li><p>Визуализация результатов (хоть и идостаточно примитивная)</p></li></ul>\n<br/>\n","examples":"<h3>Пример 23. Анализ рыночной корзины</h3>\n<p><strong>Данные.</strong> 5 чеков супермаркета:</p><ol><li>хлеб, молоко</li><li>хлеб, масло</li><li>хлеб, молоко, масло</li><li>молоко, сок</li><li>хлеб, молоко, сок</li></ol><p>Рассмотрим пару «хлеб (ключевой товар) → молоко (сопутствующий)».</p><ul><li><strong>Частота пары</strong> (поддержка): хлеб и молоко вместе в чеках 1, 3, 5 — 3 из 5, то есть <strong>60%</strong>.</li><li><strong>Вероятность покупки молока вместе с хлебом</strong> (достоверность): хлеб есть в 4 чеках, из них молоко — в 3: 3 / 4 = <strong>75%</strong>.</li></ul><p><strong>Вывод для магазина.</strong> Три четверти покупателей хлеба берут и молоко: товары стоит ставить рядом или предлагать совместную скидку. Подробнее алгоритмы поиска ассоциативных правил рассматриваются в уроке 15.</p>\n<h3>Пример 24. Категории Web Mining на примере интернет-магазина</h3>\n<table><tr><th>Категория</th><th>Данные</th><th>Задача</th></tr><tr><td>Web Content Mining</td><td>Описания товаров, отзывы, фото</td><td>Автоматически определить тональность отзывов и рубрику товара</td></tr><tr><td>Web Usage Mining</td><td>Логи веб-сервера, поток кликов</td><td>Понять, на каком шаге покупатели бросают корзину; заранее загружать популярные страницы</td></tr><tr><td>Web Structure Mining</td><td>Гиперссылки между страницами и сайтами</td><td>Найти самые авторитетные страницы, которые ссылаются на магазин</td></tr></table>\n","tasks":"<h3>Задание 1. Постановка задач Data Mining</h3>\n<p><strong>Цель:</strong> Научиться определять вид задачи интеллектуального анализа данных.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Для каждой ситуации определите вид ИАД (ассоциация, кластеризация, классификация, регрессия) и тип задачи (описательная или предсказательная): (а) спрогнозировать стоимость квартиры по площади, району и этажу; (б) разделить студентов на группы по стилю обучения без заранее заданных групп; (в) определить, является ли письмо спамом; (г) найти товары, которые часто покупают вместе.</li>\n<li>Для двух ситуаций укажите, какие данные нужно собрать.</li>\n<li>Рассчитайте для своих 6 придуманных чеков частоту и вероятность для одной пары товаров, как в примере анализа рыночной корзины.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Четыре классификации с обоснованием, перечень данных и расчёт по корзине.</p>\n<p><strong>Форма представления:</strong> Таблица и расчёт по шагам.</p>\n<h3>Лабораторная работа B11. Работа с текстовыми данными</h3>\n<p><strong>Цель: </strong>Научиться работать с текстовыми данными.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Создайте вектор текстовых данных и найдите длину каждого элемента.</p>\n<pre><code class=\"language-r\">texts &lt;- c(\"This is a sentence.\", \"This is another sentence.\")\nnchar(texts)</code></pre>\n<p>2. Разделите текст на слова и посчитайте их частоту.</p>\n<pre><code class=\"language-r\">library(stringr)\nwords &lt;- unlist(str_split(texts, \" \"))\ntable(words)</code></pre>\n","selfcheck":"<h2>Контрольные вопросы для повторения и самопроверки темы</h2>\n<ol><li><p>Чем анализ больших данных отличается от традиционного анализа?</p></li><li><p>Какие основные типы Data Mining?</p></li><li><p>Какие категории Web Mining можно выделить?</p></li><li><p>В чем основная задача Web Content Mining?</p></li><li><p>В чем основные задачи интеллектуального анализа текстов?</p></li></ol>\n","questions":[{"id":"q12-1","type":"input","level":1,"text":"В каком году был введён термин Data Mining? Введите год.","answers":["1989"],"explain":"Термин ввёл Григорий Пятецкий-Шапиро в 1989 году."},{"id":"q12-2","type":"multiple","level":1,"text":"Какие категории Web Mining выделяют в зависимости от предмета интереса? Отметьте все верные.","options":["Web Content Mining","Web Usage Mining","Web Structure Mining","Web Design Mining"],"correct":[0,1,2],"explain":"Выделяют три категории: анализ контента, анализ использования и анализ ссылочной структуры."},{"id":"q12-3","type":"single","level":2,"text":"Чем анализ больших данных отличается от традиционного анализа (вопрос самопроверки)?","options":["Меньшим объёмом данных","Огромными объёмами, высокой размерностью и сложностью данных, гетерогенными источниками","Отсутствием необходимости в алгоритмах","Использованием только числовых данных"],"correct":1,"explain":"Требуются масштабируемые алгоритмы для терабайтных БД; данные могут иметь десятки тысяч измерений, быть временными, пространственными, мультимедийными, текстовыми."},{"id":"q12-4","type":"single","level":2,"text":"В чём основная задача Web Content Mining?","options":["Анализ логов веб-серверов","Автоматизация поиска информационных ресурсов в Интернете и добыча содержимого из веб-данных","Выявление модели ссылочной структуры","Ранжирование страниц по числу ссылок"],"correct":1,"explain":"Web Content Mining извлекает знания непосредственно из контента: текста, изображений, аудио, видео, метаданных."},{"id":"q12-5","type":"truefalse","level":1,"text":"Верно ли, что в RapidMiner аналитик строит процесс из операторов без программирования?","correct":true,"explain":"Верно. Основная идея RapidMiner — визуальное программирование: процесс собирается из операторов с входными и выходными портами."},{"id":"q12-6","type":"single","level":3,"text":"Какие ключевые задачи решает интеллектуальный анализ текстов (Text Mining)?","options":["Категоризация и классификация текстов, извлечение информации и информационный поиск","Сжатие текстовых файлов","Проверка орфографии","Перевод текстов на другие языки"],"correct":0,"explain":"Text Mining ищет новые полезные шаблоны в неструктурированных текстах; его ключевые задачи — категоризация, классификация, извлечение информации и поиск."}],"tests":""},"13":{"theory":"<p>Чтобы дать определение статистическим методам анализа данных, необходимо разделить его на главные составляющие и понять, что из себя представляют «Статистика», «Методы» и «Анализ данных».</p>\n<p><em>Статистика </em>(лат. status – состояние дел):</p>\n<ul><li>это отрасль знаний, описывающая вопросы сбора, измерения и анализа массовых статистических (количественных или качественных) данных;</li><li>это изучение количественной стороны массовых общественных явлений в числовой форме;</li><li>это некая совокупность цифровых данных, представляемых в отчётности предприятий, организаций, отраслей экономики, публикуемых в сборниках, справочниках, периодических изданиях;</li><li>это отрасль общественных наук, специальная научная дисциплина, изучаемая в учебных заведениях.</li></ul>\n<p>Статистическими данными являются значения, объединенные по некоторому признаку, свойственному определенным объектам изучения, которыми, как правило, являются массовые социально-экономические явления, процессы и прикладная статистика, представляющие количественную оценку в конкретных условиях места и времени.</p>\n<p><em>Методы </em>– это общая совокупность действий, направленных на решение задачи.</p>\n<p><em>Анализ данных </em>– это процесс, посредством которого извлекается необходимая для обработки информация, в последствии предоставляющая решение поставленной перед ним задачи/проблемы.</p>\n<p>Отсюда следует главное определение:</p>\n<p><em>Статистические методы анализа данных </em>– это совокупность неких шагов (действий), занимающихся фильтрацией и обработкой предоставленных статистических данных некоего объекта изучения, с целью получения решения поставленной задачи.</p>\n<br/>\n<p>Методы статистического анализа строятся на основе следующих шагов:</p>\n<ul><li>Сбор статистических данных, являющихся характеристикой отдельных единиц совокупности общих данных;</li><li>Статистическое исследование на основе полученных сведений, выявление общих закономерностей, свойственных каждой единице;</li><li>Создание методов анализа и обработки получаемых данных.</li></ul>\n<p>Самими методами статистического анализа являются статистические гипотезы и машинное обучение.</p>\n<h2>Статистические гипотезы</h2>\n<p>Основной целью статистического анализа является выявление свойств изучаемой <em>генеральной совокупности</em>, которая представляет собой полный набор объектов, связанных с поставленной перед изучением проблемой. И в случае, если изучаемая генеральная совокупность представляет собой большое или бесконечное множество элементов, тогда необходимо провести отбор из генеральной совокупности в виде некоего подмножества из N элементов, называемых <em>выборкой </em>с необходимым объемом данных, где выявленные в выборке свойства обобщаются на всю генеральную совокупность и называются <em>статистическим выводом</em>.</p>\n<p><em>Статистический вывод </em>– это утверждение о том, что представляют собой законы, лежащие в основе изучаемой генеральной совокупности; имеющий два раздела, являющихся по своей сути частными случаями задачи принятия решений:</p>\n<p>1. Оценивание параметров законов – вычисление по выборке точечных и интервальных оценок.</p>\n<p>2. Проверка статистических гипотез – установление справедливости данного утверждение по отношению к параметрам генеральной совокупности.</p>\n<p>Перейдём к определению самих статистических гипотез. Пусть в статистическом эксперименте доступна наблюдению случайная величина <em><strong>X</strong></em>,для которой выполняются следующие условия:</p>\n<ul><li>Распределение <em><strong>P </strong></em>известно полностью или частично;</li><li>Любое утверждение, касающееся <em><strong>P </strong></em>называется статистической гипотезой.</li></ul>\n<p>На практике, как правило, рассматривают простую гипотезу <em><strong>H</strong></em><em><strong><sub>0</sub></strong></em>(нулевая гипотеза), и противоречащую ей гипотезу <em><strong>H</strong></em><em><strong><sub>1</sub></strong></em><em><strong> </strong></em>(конкурирующая или альтернативная). Для проверки гипотезы используют критерии, позволяющие принять или опровергнуть гипотезу. Так называемые статистические критерии, о которых говориться далее.</p>\n<p>Потому как при принятии решения выявлялись статистические ошибки, их поделили на два типа:</p>\n<ul><li>Ошибка первого рода – обнаружение различий или связей, на самом деле не существующих. Вероятностью возникновения данной ошибки называется уровень значимости, и обозначается буквой α, откуда название ошибки α- error.</li><li>Ошибка второго рода – не обнаружение различий или связей, на самом деле существующих. Названия для вероятности данной ошибки не существует, но обозначением является греческая буква β (β-error). Вводится понятие мощности критерия (1 − β): чем она выше, тем меньше вероятность ошибки второго рода (β), то есть тем надёжнее критерий обнаруживает действительно существующие различия.</li></ul>\n<p>Для того, чтобы провести проверку статистических гипотез, выделили необходимую последовательность, состоящую из следующих этапов:</p>\n<p>1. Формулировка основной гипотезы <em><strong>H</strong></em><em><strong><sub>0</sub></strong></em><em><strong> </strong></em>и конкурирующей гипотезы <em><strong>H</strong></em><em><strong><sub>1</sub></strong></em>, задание значения <em><strong>α</strong></em>.</p>\n<p>2. Задание некоего критерия <em><strong>φ</strong></em>, такого что, его величина зависит от исходной выборки; по его значению можно делать выводы об истинности гипотезы <em><strong>H</strong></em><em><strong><sub>0</sub></strong></em>; сама статистика <em><strong>φ</strong></em>должна подчиняться какому-то известному закону распределения, так как сама <em><strong>φ</strong></em>является случайной в силу случайности <em><strong>X</strong></em>.</p>\n<p>3. Построение критической области. Из области значений <em><strong>φ</strong></em>выделяется подмножество <em><strong>С</strong></em>(критическая область) таких значений, по которым можно судить о существенных расхождениях с предположением. Ее размер выбирается с учетом выполнения равенства. Выделяются три вида критических областей:</p>\n<br/>\n<p>а) Двусторонняя критическая область, определяется интервалами <em>(-∞, x</em><em><sub>α/2</sub></em><em>) </em>∪ <em>(x</em><em><sub>1-</sub></em><em> </em><em><sub>α/2</sub></em><em>, +∞)</em>, где <em>x</em><em><sub>α/2</sub></em><em> </em>и <em>x</em><em><sub>1-α/2</sub></em>находят из условий: <em>P(φ&lt; x</em><em><sub>α/2</sub></em><em>) = α/2</em>, <em>P(φ&lt; x</em><em><sub>1-α/2</sub></em><em>) = 1 – α/2</em>. б) Левосторонняя критическая область определяется интервалом <em>(-∞, x</em><em><sub>α</sub></em><em>)</em>, где <em>x</em><em><sub>α</sub></em><em> </em>находят из условия: <em>P(φ&lt; x</em><em><sub>α</sub></em><em>) = α</em>.</p>\n<p>в) Правосторонняя критическая область определяется интервалом <em>(x</em><em><sub>1-α</sub></em><em>, +∞)</em>, где</p>\n<p><em>x</em><em><sub>1-α</sub></em><em> </em>находятся из условия: <em>P(φ&lt; x</em><em><sub>1-α</sub></em><em>) = 1 – α</em>.</p>\n<p>4. Вывод об истинности гипотезы. Наблюдаемые значения выборки подставляются в статистику <em><strong>ɸ</strong></em>и по попаданию (или непопаданию) в критическую область выносится решение об отвержении (или принятии) выдвинутой гипотезы <em><strong>H</strong></em><em><strong><sub>0</sub></strong></em>.</p>\n<h2>Статистические критерии</h2>\n<p>Задачей статистики является выбор критериев, при помощи которых будут доказываться гипотезы. И есть несколько типов статистических критериев:</p>\n<ul><li>Критерий значимости – это гипотезы о численных значениях известного закона распределения, где <em><strong>H</strong></em><em><strong><sub>0</sub></strong></em><em><strong> : α = α</strong></em><em><strong><sub>0</sub></strong></em><em><strong> </strong></em>– нулевая гипотеза, а <em><strong>H</strong></em><em><strong><sub>1</sub></strong></em><em><strong> : α &gt; α</strong></em><em><strong><sub>0</sub></strong></em><em><strong> (α &lt; α</strong></em><em><strong><sub>0</sub></strong></em><em><strong>)</strong></em>– конкурирующая или альтернативная гипотеза.</li><li>Критерий согласия – проверка подчинения предполагаемому закону распределения (в том числе, критерий Пирсона, Колмогорова и т.д.)</li><li>Непараметрические критерии – критерии, оперирующие частотой и рангом, не включающие параметров распределения в расчеты.</li><li>Параметрические критерии, которые берут в расчет параметры вероятностного распределения признака (средний и дисперсия). Такие как t- критерий Стьюдента, критерий Фишера и т.д.</li></ul>\n<p>Более подробно разберем параметрический критерий под названием <em>t</em>- критерий Стьюдента, который является общим названием для статистических тестов, в которых присутствует распределение Стьюдента. Он может быть использован для проверки равенства между средними значениями двух выборок, где нулевая гипотеза предполагает, что средние равны.</p>\n<p>Одним из требований данного критерия является то, что исходные</p>\n<br/>\n<p>данные имеют нормальное распределение, другим – в случае, если применяются двухвыборочные критерии для независимых друг от друга выборок, необходимым является соблюдение условий равенства дисперсии.</p>\n<h2>Машинное обучение</h2>\n<p>В этом методе, как очевидно, обучается машина. Но не при помощи исследователя или специалиста, а по данным, которые являются обучающей выборкой. И задачей исследователя становится умение строить алгоритмы, обучающиеся по данным. Обучение проводится по прецедентам (ситуаций или объектов), когда дано конечное множество данных о прецедентах, с собранными (измеренными) по каждому из них данными (описанием). Все имеющиеся описания прецедентов собираются воедино и называются это выборкой.</p>\n<p>Обучение проходит как с учителем, так и без. В случае, когда <em>обучение проходит с учителем </em>(supervised learning), каждый прецедент – это заданные пара «объект, ответ», и для нахождения функциональной зависимости ответов от описаний необходимо составить алгоритм, который на входе принимает описание, а на выходе дает ответ. В зависимости от ответов, выполняются разные задачи. При задаче классификации множество допустимых ответов конечно, их называют метками классов (множество объектов, имеющих данное значение метки). При задаче регрессии ответом является действительное число или числовой вектор. В случае, когда <em>обучение проходит без учителя </em>(unsupervised learning), ответы не задаются и приходится искать зависимости между заданными объектами. В этом случае выполняются задачи кластеризации, когда необходимо сгруппировать объекты в кластеры, пользуясь данными о сходстве парных объектов. И задача поиска ассоциативных правил, где исходные данные – это признаковые описания, и требуется найти наборы признаков и их значения, встречающиеся неслучайно часто в описаниях объектов.</p>\n<p>Обозначение в машинном обучении:</p>\n<ul><li><em><strong>X</strong></em>– множество объектов;</li><li><em><strong>Y</strong></em>– множество ответов;</li><li><em><strong>y: X → Y </strong></em>– неизвестная зависимость.</li></ul>\n<p>В рамках решения задачи, дано конечно множество точек:</p>\n<ul><li><em><strong>{x</strong></em><em><strong><sub>1</sub></strong></em><em><strong>,…, x</strong></em><em><strong><sub>n</sub></strong></em><em><strong>} ⸦ X </strong></em>– обучающая выборка;</li><li><em><strong>y</strong></em><em><strong><sub>1</sub></strong></em><em><strong>,…,y</strong></em><em><strong><sub>n</sub></strong></em><em><strong>, y</strong></em><em><strong><sub>i</sub></strong></em><em><strong> = y(x</strong></em><em><strong><sub>i</sub></strong></em><em><strong>) </strong></em>– известные ответы.</li></ul>\n<p>Задачей является нахождение такой функции <em><strong>α</strong></em>, которая аппроксимировала бы целевую зависимость: <em><strong>α:X → Y</strong></em>, решающую функцию, приближающую <em><strong>y </strong></em>на всем множестве <em><strong>X </strong></em>(не только на обучающей выборке).</p>\n<p>Типы ответов:</p>\n<ul><li><em><strong>Y = {-1, +1}</strong></em>– классификация на 2 класса;</li><li><em><strong>Y = {1, …, M} </strong></em>– на М непересекающихся классов;</li><li><em><strong>Y = {0, 1}</strong></em><em><strong><sup>M</sup></strong></em>– на М классов, могут пересекаться;</li><li><em><strong>Y = R </strong></em>– задача регрессии (прогнозирование вещественных значений).</li></ul>\n<p><em><strong>f</strong></em><em><strong><sub>i</sub></strong></em><em><strong>: X → D</strong></em><em><strong><sub>j</sub></strong></em><em><strong> </strong></em>– множество признаков объекта. Типы признаков:</p>\n<ul><li>бинарный <em><strong>{0, 1}</strong></em></li><li>номинальный<em><strong>Dj &lt; ∞</strong></em></li><li>количественный <em><strong>Dj = R</strong></em></li></ul>\n<p>Модель обучения:</p>\n<p>Неизвестная функция аппроксимации (целевая): <em><strong>α: X → Y</strong></em></p>\n<p>Для моделирования неизвестной функции вводится параметрическое семейство функций:</p>\n<p class=\"formula\">A = { g(x, θ) | θ ∈ Θ },&nbsp;&nbsp; где g: X × Θ → Y, Θ — множество допустимых значений параметра θ.</p>\n<p>Таким образом, задача обучения сводится к:</p>\n<ol><li>выбору вида функции g(x, θ), который зависит от решаемой задачи:<ul><li>линейные модели (g(x, θ) — линейная комбинация признаков с коэффициентами θ) — регрессия;</li><li>для классификации на два класса: g(x, θ) = sign Σ<sub>j</sub> θ<sub>j</sub> f<sub>j</sub>(x), Y = {−1, +1};</li></ul></li><li>определению значений параметров θ по обучающей выборке.</li></ol>\n<p>Метод обучения — это отображение µ: (X × Y)<sup>n</sup> → A, которое по произвольной выборке X<sup>n</sup> = (x<sub>i</sub>, y<sub>i</sub>)<sub>i=1</sub><sup>n</sup> строит некий алгоритм α ∈ A.</p>\n<h2>Как оценить качество обучения модели?</h2>\n<p><em><strong>L(α, x) </strong></em>– функция потерь – величина ошибки алгоритма <em><strong>α</strong></em>∈<em><strong>A </strong></em>на объекте</p>\n<p><em><strong>X</strong></em>.</p>\n<p>Функция потерь для задачи классификации:</p>\n<ul><li><em><strong>L(α, x) = [α(x)!= y(x)] </strong></em>– индикатор ошибки. Функция потерь для задачи регрессии:</li><li><em><strong>L(α, x) = |α(x) – y(x)| </strong></em>– абсолютное значение ошибки.</li><li><em><strong>L(α, x) = (α(x) – y(x))</strong></em><em><strong><sup>2</sup></strong></em>– квадратичная ошибка.</li></ul>\n<p>В качестве идеи каждого алгоритма зачастую лежат вполне определенные гипотезы, представления о природе данных:</p>\n<ul><li>Метрические классификаторы – идея об измеримости пространства, метрическом взаимоотношении между объектами;</li><li>Логические классификаторы – идея о логических закономерностях происхождения данных;</li><li>Линейные классификаторы – идея о наличии линейных разделяющих плоскостей между классами в пространстве объектов;</li><li>И т.д.</li></ul>\n","examples":"<h3>Пример 25. Проверка гипотезы о равенстве средних (t-критерий Стьюдента)</h3>\n<p><strong>Задача.</strong> Две группы студентов учились по разным методикам. Средний балл группы А (25 человек) — 74, группы Б (25 человек) — 79. Есть ли статистически значимое различие?</p><ol><li><strong>Гипотезы.</strong> H<sub>0</sub>: средние баллы групп равны; H<sub>1</sub>: средние различаются. Уровень значимости α = 0,05.</li><li><strong>Критерий.</strong> Двухвыборочный t-критерий Стьюдента для независимых выборок. Условия: баллы распределены нормально, дисперсии групп равны.</li><li><strong>Критическая область</strong> — двусторонняя, так как H<sub>1</sub> не указывает направление различия.</li><li><strong>Вывод.</strong> Пусть вычисленное значение t попало в критическую область (p-значение = 0,02 &lt; 0,05). Тогда H<sub>0</sub> отвергается: различие значимо.</li></ol><p>В R это делается одной командой:</p><pre><code class=\"language-r\">t.test(scores_a, scores_b, var.equal = TRUE)</code></pre><p><strong>Возможные ошибки.</strong> Если на самом деле методики не различаются, а мы отвергли H<sub>0</sub>, — это ошибка первого рода (вероятность не больше α = 0,05). Если различие есть, а мы его не обнаружили, — ошибка второго рода (β).</p>\n<h3>Пример 26. Функции потерь</h3>\n<p>Модель предсказывает цену квартиры (регрессия). Для трёх объектов:</p><table><tr><th>Объект</th><th>Истинный ответ y(x)</th><th>Прогноз α(x)</th><th>|α − y|</th><th>(α − y)²</th></tr><tr><td>1</td><td>30</td><td>28</td><td>2</td><td>4</td></tr><tr><td>2</td><td>45</td><td>50</td><td>5</td><td>25</td></tr><tr><td>3</td><td>60</td><td>59</td><td>1</td><td>1</td></tr></table><p>Средняя абсолютная ошибка: (2 + 5 + 1) / 3 ≈ <strong>2,67</strong>. Средняя квадратичная ошибка: (4 + 25 + 1) / 3 = <strong>10</strong>. Квадратичная ошибка сильнее «наказывает» большие промахи (объект 2).</p><p>Для классификации используется индикатор ошибки: L = 1, если α(x) ≠ y(x), иначе 0. Если модель ошиблась на 3 объектах из 20, средняя потеря равна 3/20 = 0,15 (доля ошибок).</p>\n","tasks":"<h3>Задание 1. Постановка задач машинного обучения</h3>\n<p><strong>Цель:</strong> Научиться формализовать задачу машинного обучения: объекты, ответы, признаки, тип задачи.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Для каждой задачи укажите множество объектов X, множество ответов Y, тип задачи (бинарная или многоклассовая классификация, регрессия, кластеризация, ассоциативные правила) и вид обучения (с учителем или без): (а) определить, сдаст ли студент экзамен; (б) предсказать температуру на завтра; (в) сгруппировать покупателей без заранее заданных групп; (г) определить жанры фильма (их может быть несколько); (д) найти товары, которые часто покупают вместе.</li>\n<li>Для задачи (а) предложите 5 признаков и укажите тип каждого (бинарный, номинальный, количественный).</li>\n<li>Для задач (а) и (б) укажите подходящую функцию потерь.</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Таблица из 5 задач, список признаков и функции потерь.</p>\n<p><strong>Форма представления:</strong> Таблица «Задача — X — Y — Тип — Обучение» и пояснения.</p>\n<details class='hint'><summary>Подсказка</summary><p>Y = {0, 1}^M соответствует классам, которые могут пересекаться.</p></details>\n<h3>Лабораторная работа A3. Анализ данных</h3>\n<p><strong>Цель: </strong>Научиться выполнять базовый анализ данных и создавать сводные таблицы.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. <strong>Основные статистики</strong></p>\n<h4><strong>Рассчитайте среднее, медиану и стандартное отклонение для столбца mpg в наборе данных</strong></h4>\n<p>mtcars:</p>\n<pre><code class=\"language-r\">mean(mtcars$mpg)\nmedian(mtcars$mpg)\nsd(mtcars$mpg)</code></pre>\n<h4>2. <strong>Сводные таблицы</strong></h4>\n<h4><strong>Создайте сводную таблицу, показывающую средние значения по переменной cyl</strong></h4>\n<p>(количество цилиндров):</p>\n<pre><code class=\"language-r\">library(dplyr)\nmtcars_summary &lt;- mtcars %&gt;%\ngroup_by(cyl) %&gt;%\nsummarise(mean_mpg = mean(mpg), count = n())\nprint(mtcars_summary)</code></pre>\n<h3>Лабораторная работа B4. Основные статистики</h3>\n<p><strong>Цель: </strong>Рассчитать основные статистические показатели.</p>\n<h4><strong>Задания:</strong></h4>\n<h4>1. <strong>Рассчитайте среднее, медиану и стандартное отклонение для переменной Sepal.Length в наборе данных iris.</strong></h4>\n<pre><code class=\"language-r\">mean(iris$Sepal.Length)\nmedian(iris$Sepal.Length)\nsd(iris$Sepal.Length)</code></pre>\n<h3>Лабораторная работа B12. Временные ряды</h3>\n<p><strong>Цель: </strong>Анализировать временные ряды.</p>\n<br/>\n<h4><strong>Задания:</strong></h4>\n<p>1. Создайте временной ряд и постройте его график.</p>\n<pre><code class=\"language-r\">ts_data &lt;- ts(cumsum(rnorm(100)), frequency = 12)\nplot(ts_data, main = \"Пример временного ряда\")</code></pre>\n<p>2. Постройте сезонные компоненты временного ряда.</p>\n<pre><code class=\"language-r\">library(forecast)\ndecomposed_ts &lt;- decompose(ts_data)\nplot(decomposed_ts)</code></pre>\n<h3>Лабораторная работа B13. Корреляция и ковариация</h3>\n<p><strong>Цель: </strong>Рассчитать корреляцию и ковариацию между переменными.</p>\n<h4>Задания:</h4>\n<p>1. Рассчитайте корреляцию между переменными Sepal.Length и Sepal.Width в наборе данных iris.</p>\n<pre><code class=\"language-r\">cor(iris$Sepal.Length, iris$Sepal.Width)</code></pre>\n<p>2. Рассчитайте ковариацию между теми же переменными.</p>\n<pre><code class=\"language-r\">cov(iris$Sepal.Length, iris$Sepal.Width)</code></pre>\n","selfcheck":"","questions":[{"id":"q13-1","type":"single","level":1,"text":"Как называется ошибка, при которой обнаружены различия, на самом деле не существующие?","options":["Ошибка первого рода","Ошибка второго рода","Ошибка выборки","Функция потерь"],"correct":0,"explain":"Ошибка первого рода (α-error). Её вероятность называется уровнем значимости."},{"id":"q13-2","type":"input","level":2,"text":"Как обозначается мощность критерия, если вероятность ошибки второго рода равна β? Введите выражение.","answers":["1-β","1 - β","1−β","1-b","1 - b"],"explain":"Мощность критерия равна 1 − β: чем она выше, тем меньше вероятность пропустить существующее различие (ошибка второго рода)."},{"id":"q13-3","type":"multiple","level":2,"text":"Какие задачи решаются при обучении без учителя? Отметьте все верные.","options":["Кластеризация","Поиск ассоциативных правил","Классификация","Регрессия"],"correct":[0,1],"explain":"Без учителя ответы не заданы: решаются кластеризация и поиск ассоциативных правил. Классификация и регрессия — обучение с учителем."},{"id":"q13-4","type":"truefalse","level":2,"text":"Верно ли, что t-критерий Стьюдента требует нормального распределения исходных данных?","correct":true,"explain":"Верно. Для двух независимых выборок также требуется равенство дисперсий."},{"id":"q13-5","type":"single","level":3,"text":"Какой тип ответов Y соответствует задаче регрессии?","options":["Y = {−1, +1}","Y = {1, …, M}","Y = {0, 1}^M","Y = R"],"correct":3,"explain":"Регрессия — прогнозирование вещественных значений, Y = R."}],"tests":""},"14":{"theory":"<h2>Метрические классификаторы</h2>\n<p><strong>Метрический классификатор</strong> — это алгоритм, который вычисляет оценку сходства предоставленных объектов. Метрические классификаторы основываются на <strong>гипотезе компактности</strong>, предполагающей, что похожие друг на друга объекты чаще всего принадлежат одному классу.</p>\n<p>Самым простым метрическим классификатором является <strong>метод ближайшего соседа</strong>: классифицируемый объект x относят к тому классу y, которому принадлежит ближайший к нему объект выборки.</p>\n<ul>\n<li><strong>Преимущества:</strong> простота реализации и интерпретируемость решений.</li>\n<li><strong>Недостатки:</strong> неустойчивость к погрешностям, отсутствие настраиваемых параметров, низкое качество классификации, необходимость хранить всю выборку полностью.</li>\n</ul>\n<p>Разновидностью этого метода является <strong>метод k ближайших соседей</strong>: берутся k ближайших соседей, и объект относится к тому классу, к которому принадлежит большинство из них. Преимущество — меньшая чувствительность к шуму; недостаток — близости к двум классам могут оказаться равными.</p>\n<p>В <strong>методе взвешенных ближайших соседей</strong> соседям приписываются веса, убывающие с ростом ранга (чем дальше сосед, тем меньше его вес). Это устраняет неоднозначность, в том числе при количестве классов более двух.</p>\n\n<h2>Линейный классификатор</h2>\n<p>Идея подхода — линейность пространства объектов. <strong>Линейный классификатор</strong> — это алгоритм классификации, основанный на построении разделяющей линейной поверхности. В случае двух классов эта поверхность является <strong>гиперплоскостью</strong>, делящей пространство признаков на два полупространства.</p>\n<p>Чтобы оценить, насколько глубоко объект «погружён» в свой класс (насколько далеко он от границы), используют понятие <strong>отступа</strong>. Чем меньше отступ, тем ближе объект к границе и тем выше вероятность ошибки.</p>\n<p>Для применения методов оптимизации пороговую функцию потерь заменяют её непрерывной аппроксимацией и минимизируют не сам функционал эмпирического риска, а его верхнюю оценку:</p>\n<p class=\"formula\">Q(w) = Σ<sub>i=1</sub><sup>n</sup> L(g(w, x<sub>i</sub>), y<sub>i</sub>) = Σ<sub>i=1</sub><sup>n</sup> L<sub>i</sub>(w) → min<sub>w</sub></p>\n<p>Для подбора весов w используется <strong>градиентный спуск</strong> — движение в направлении, противоположном градиенту (градиент указывает направление возрастания функции):</p>\n<p class=\"formula\">w<sup>(t+1)</sup> = w<sup>(t)</sup> − h · Σ<sub>i=1</sub><sup>n</sup> ∇L<sub>i</sub>(w<sup>(t)</sup>)</p>\n<p>где h — темп обучения (размер шага).</p>\n\n<h3>Стохастический градиентный спуск (SG)</h3>\n<p><strong>Вход:</strong> выборка X<sup>n</sup>, темп обучения h, темп забывания λ. <strong>Выход:</strong> вектор весов w.</p>\n<ol>\n<li>Инициализировать веса w<sub>j</sub>, j = 1, …, d.</li>\n<li>Инициализировать оценку функционала: Q̄ := (1/n) Σ<sub>i=1</sub><sup>n</sup> L<sub>i</sub>(w).</li>\n<li>Повторять:\n <ol type=\"a\">\n <li>выбрать объект x<sub>i</sub> из X<sup>n</sup> случайным образом;</li>\n <li>вычислить потерю: ε<sub>i</sub> := L<sub>i</sub>(w);</li>\n <li>сделать градиентный шаг: w := w − h · ∇L<sub>i</sub>(w);</li>\n <li>оценить функционал: Q̄ := (1 − λ) · Q̄ + λ · ε<sub>i</sub>;</li>\n </ol>\nпока значение Q̄ и/или веса w не сойдутся.</li>\n</ol>\n<ul>\n<li><strong>Преимущества:</strong> простая реализация; возможность работать со сверхбольшими выборками, даже не обрабатывая их полностью.</li>\n<li><strong>Недостатки:</strong> возможная расходимость или медленная сходимость, застревание в локальных минимумах, проблема переобучения.</li>\n</ul>\n\n<h2>Характеристики бинарного классификатора</h2>\n<p>Обозначения: TP — верно предсказанные положительные объекты, FP — ложно положительные, FN — ложно отрицательные, TN — верно отрицательные.</p>\n<ol>\n<li><strong>Точность (Precision)</strong> — доля действительно положительных среди объектов, предсказанных как положительные:\n<p class=\"formula\">Precision = TP / (TP + FP)</p></li>\n<li><strong>Полнота (Recall)</strong> — доля найденных положительных объектов от общего количества реальных положительных:\n<p class=\"formula\">Recall = TP / (TP + FN)</p></li>\n<li><strong>F-мера</strong> — характеристика, позволяющая оценить одновременно точность и полноту:\n<p class=\"formula\">F = 1 / ( α · (1 / Precision) + (1 − α) · (1 / Recall) ),&nbsp;&nbsp; 0 ≤ α ≤ 1</p>\n<p>При α = 0,5 получаем гармоническое среднее: F<sub>1</sub> = 2 · Precision · Recall / (Precision + Recall).</p></li>\n</ol>\n\n<h2>ROC-кривая</h2>\n<p><strong>ROC-кривая</strong> (receiver operating characteristic) — графическая характеристика бинарного классификатора, показывающая зависимость <strong>TPR</strong> (доля верных положительных классификаций, то есть полнота) от <strong>FPR</strong> (доля ложных положительных классификаций):</p>\n<p class=\"formula\">TPR = TP / (TP + FN),&nbsp;&nbsp;&nbsp; FPR = FP / (FP + TN)</p>\n<p>Кривая монотонно не убывает, и чем выше она лежит, тем лучше качество классификации.</p>\n<p>Площадь под ROC-кривой называется <strong>AUC</strong> (Area Under Curve). Это агрегированная характеристика качества классификации, не зависящая от соотношения цен ошибок. Показатель предназначен для сравнительного анализа нескольких моделей, но не содержит информации о конкретных значениях FPR и TPR модели.</p>\n","examples":"<h3>Пример 27. Метод k ближайших соседей вручную</h3>\n<p><strong>Данные.</strong> Студенты описаны двумя признаками: часы подготовки в неделю и посещаемость (%). Класс: «сдал» (+) или «не сдал» (−).</p><table><tr><th>Студент</th><th>Часы</th><th>Посещаемость</th><th>Класс</th></tr><tr><td>A</td><td>2</td><td>50</td><td>−</td></tr><tr><td>B</td><td>3</td><td>60</td><td>−</td></tr><tr><td>C</td><td>8</td><td>90</td><td>+</td></tr><tr><td>D</td><td>7</td><td>80</td><td>+</td></tr><tr><td>E</td><td>5</td><td>70</td><td>+</td></tr></table><p><strong>Новый объект:</strong> 4 часа, 70%. Чтобы признаки были сравнимы, посещаемость делим на 10: (4; 7).</p><p>Евклидовы расстояния до объектов: A (2; 5) — √(4+4) ≈ 2,83; B (3; 6) — √(1+1) ≈ 1,41; C (8; 9) — √(16+4) ≈ 4,47; D (7; 8) — √(9+1) ≈ 3,16; E (5; 7) — √(1+0) = 1,00.</p><ul><li><strong>1 ближайший сосед:</strong> E → класс «+».</li><li><strong>k = 3:</strong> E (+), B (−), A (−) → большинство «−», прогноз «не сдал».</li></ul><p><strong>Вывод.</strong> Результат зависит от k. Метод одного соседа неустойчив к погрешностям; при k = 3 решение принимается большинством, поэтому метод менее чувствителен к шуму.</p>\n<h3>Пример 28. Точность, полнота и F-мера</h3>\n<p>Классификатор спама проверили на 100 письмах, из них 20 — спам.</p><table><tr><th></th><th>Предсказан спам</th><th>Предсказано «не спам»</th></tr><tr><td>Действительно спам</td><td>TP = 15</td><td>FN = 5</td></tr><tr><td>Не спам</td><td>FP = 10</td><td>TN = 70</td></tr></table><ul><li><strong>Точность (Precision)</strong> = TP / (TP + FP) = 15 / 25 = <strong>0,60</strong>: из писем, помеченных как спам, 60% действительно спам.</li><li><strong>Полнота (Recall, TPR)</strong> = TP / (TP + FN) = 15 / 20 = <strong>0,75</strong>: найдено 75% всего спама.</li><li><strong>F-мера</strong> (при α = 0,5, гармоническое среднее): 2 · 0,60 · 0,75 / (0,60 + 0,75) ≈ <strong>0,67</strong>.</li><li><strong>FPR</strong> = FP / (FP + TN) = 10 / 80 = 0,125 — эта точка (0,125; 0,75) лежит на ROC-кривой классификатора.</li></ul><p>Если поднять порог «спамности», FP уменьшится (точность вырастет), но часть спама будет пропущена (полнота упадёт).</p>\n","tasks":"<h3>Задание 1. Оценка бинарного классификатора</h3>\n<p><strong>Цель:</strong> Научиться вычислять характеристики качества классификации.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Медицинский тест проверили на 200 пациентах, 40 из них больны. Тест дал положительный результат у 50 пациентов, из них 32 действительно больны.</li>\n<li>Постройте таблицу TP, FP, FN, TN.</li>\n<li>Вычислите точность, полноту, F-меру (α = 0,5) и FPR.</li>\n<li>Объясните, что важнее для такого теста — точность или полнота — и почему.</li>\n<li>Выполните лабораторную работу B9 и сравните коэффициенты модели с выводами, которые можно сделать по графику остатков (A5, B14).</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Таблица, четыре числовые характеристики, обоснованный вывод и результаты лабораторных работ.</p>\n<p><strong>Форма представления:</strong> Расчёты по шагам и скриншоты результатов R.</p>\n<details class='hint'><summary>Подсказка</summary><p>Пропустить больного пациента (FN) обычно опаснее, чем отправить здорового на дополнительное обследование (FP).</p></details>\n<h3>Лабораторная работа A5. Моделирование данных</h3>\n<p><strong>Цель: </strong>Изучить основы регрессионного анализа и моделирования данных.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. <strong>Линейная регрессия</strong></p>\n<h4><strong>Постройте линейную регрессионную модель, предсказывающую mpg на основе wt:</strong></h4>\n<pre><code class=\"language-r\">model &lt;- lm(mpg ~ wt, data = mtcars)\nsummary(model)</code></pre>\n<h4>2. <strong>Оценка модели</strong></h4>\n<h4><strong>Постройте график остатков модели:</strong></h4>\n<pre><code class=\"language-r\">plot(model, which = 1)</code></pre>\n<h4>3. <strong>Кластеризация</strong></h4>\n<h4><strong>Выполните кластеризацию данных с использованием алгоритма k-means для переменных</strong></h4>\n<p>mpg и wt:</p>\n<pre><code class=\"language-r\">kmeans_result &lt;- kmeans(mtcars[, c(\"mpg\", \"wt\")], centers = 3)\nmtcars$cluster &lt;- kmeans_result$cluster\nggplot(mtcars, aes(x = wt, y = mpg, color = factor(cluster))) + geom_point() + labs(title = \"Кластеризация данных\")</code></pre>\n<h3>Лабораторная работа B9. Линейная регрессия</h3>\n<p><strong>Цель: </strong>Выполнить линейную регрессию и интерпретировать результаты.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Постройте линейную регрессионную модель, предсказывающую Sepal.Length на основе</p>\n<p>Petal.Length.</p>\n<pre><code class=\"language-r\">model &lt;- lm(Sepal.Length ~ Petal.Length, data = iris)\nsummary(model)</code></pre>\n<p>2. Постройте график регрессионной линии.</p>\n<pre><code class=\"language-r\">ggplot(iris, aes(x = Petal.Length, y = Sepal.Length)) + geom_point() +\ngeom_smooth(method = \"lm\", se = FALSE) +\nlabs(title = \"Регрессионная линия: Sepal.Length ~ Petal.Length\")</code></pre>\n<h3>Лабораторная работа B14. Оценка модели</h3>\n<p><strong>Цель: </strong>Оценить качество модели и интерпретировать результаты.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Рассчитайте и визуализируйте остатки модели линейной регрессии.</p>\n<pre><code class=\"language-r\">residuals &lt;- residuals(model)\nggplot(data = data.frame(residuals), aes(x = residuals)) + geom_histogram(binwidth = 0.5) +\nlabs(title = \"Распределение остатков модели\")</code></pre>\n<p>2. Постройте Q-Q график остатков.</p>\n<pre><code class=\"language-r\">qqnorm(residuals)\nqqline(residuals)</code></pre>\n","selfcheck":"","questions":[{"id":"q14-1","type":"single","level":1,"text":"На какой гипотезе основаны метрические классификаторы?","options":["Гипотеза компактности","Гипотеза линейности","Нулевая гипотеза","Гипотеза нормальности"],"correct":0,"explain":"Гипотеза компактности: похожие друг на друга объекты чаще всего принадлежат одному классу."},{"id":"q14-2","type":"input","level":2,"text":"TP = 30, FP = 10. Чему равна точность (Precision)? Введите десятичную дробь.","answers":["0,75","0.75",".75"],"explain":"Precision = TP / (TP + FP) = 30 / 40 = 0,75."},{"id":"q14-3","type":"truefalse","level":2,"text":"Верно ли, что чем меньше отступ объекта, тем выше вероятность ошибки его классификации?","correct":true,"explain":"Верно. Малый отступ означает, что объект находится близко к разделяющей поверхности."},{"id":"q14-4","type":"multiple","level":2,"text":"Какие недостатки имеет метод одного ближайшего соседа? Отметьте все верные.","options":["Неустойчивость к погрешностям","Необходимость хранить всю выборку","Отсутствие настраиваемых параметров","Сложность интерпретации решений"],"correct":[0,1,2],"explain":"Интерпретируемость решений — как раз достоинство метода, наряду с простотой реализации."},{"id":"q14-5","type":"single","level":3,"text":"Что показывает ROC-кривая?","options":["Зависимость TPR (полноты) от FPR","Зависимость точности от объёма выборки","Изменение функции потерь во времени","Распределение остатков модели"],"correct":0,"explain":"ROC-кривая монотонно не убывает, и чем выше она лежит, тем лучше классификатор."}],"tests":""},"15":{"theory":"<h2>Кластеризация</h2>\n<p><strong>Кластеризация</strong> — это обучение без учителя. Это задача разделить множество объектов на различные группы, которые называются <strong>кластерами</strong>.</p>\n<p>Цели кластеризации:</p>\n<ul>\n<li><strong>упрощение дальнейшей обработки данных</strong> — разбиение пространства объектов на группы схожих объектов, чтобы работать с каждой группой отдельно (классификация, регрессия, прогнозирование);</li>\n<li><strong>сокращение объёма хранимых данных</strong> — оставление по одному представителю от каждого кластера (сжатие данных);</li>\n<li><strong>выделение нетипичных объектов</strong>, которые не подходят ни к одному кластеру (одноклассовая классификация);</li>\n<li><strong>построение иерархии</strong> множества объектов — таксономия.</li>\n</ul>\n<p><strong>Постановка задачи.</strong> Даны X — пространство объектов, X<sup>n</sup> = {x<sub>i</sub>}<sub>i=1</sub><sup>n</sup> — обучающая выборка и ρ: X × X → [0, ∞) — функция расстояния между объектами. Требуется найти множество кластеров Y и алгоритм кластеризации α: X → Y такие, что каждый кластер состоит из близких объектов, а объекты разных кластеров существенно различаются.</p>\n<p>Задача кластеризации <strong>некорректна (неоднозначна)</strong>, потому что:</p>\n<ul>\n<li>чёткой постановки задачи не существует;</li>\n<li>существует много критериев качества кластеризации;</li>\n<li>существует много эвристических методов деления на кластеры;</li>\n<li>число кластеров, как правило, заранее неизвестно;</li>\n<li>результат зависит от выбора метрики ρ, который субъективен.</li>\n</ul>\n<h3>Типы кластерных структур</h3>\n<p>1. Кластеры, расстояния внутри которых меньше, чем между ними.</p>\n<img src=\"images/practice-14-01.jpg\" alt=\"Кластеры с внутрикластерными расстояниями меньше межкластерных\"/>\n<p>2. Ленточные кластеры.</p>\n<img src=\"images/practice-14-02.jpg\" alt=\"Ленточные кластеры\"/>\n<p>3. Кластеры с центром.</p>\n<img src=\"images/practice-14-03.jpg\" alt=\"Кластеры с центром\"/>\n<p>4. Соединённые кластеры.</p>\n<img src=\"images/practice-14-04.jpg\" alt=\"Соединённые кластеры\"/>\n<p>5. Кластеры, наложенные на фон разреженных объектов.</p>\n<img src=\"images/practice-14-05.jpg\" alt=\"Кластеры на фоне разреженных объектов\"/>\n<p>6. Перекрывающиеся кластеры.</p>\n<img src=\"images/practice-14-06.jpg\" alt=\"Перекрывающиеся кластеры\"/>\n<p>Каждый метод кластеризации имеет свои ограничения и выделяет кластеры лишь некоторых типов. Понятие «тип кластерной структуры» зависит от метода и не имеет формального определения. Самые известные методы кластеризации — метод k-средних, метод c-средних, сеть Кохонена и другие.</p>\n\n<h2>Алгоритм k-means (k-средних)</h2>\n<ol>\n<li>Инициализировать центры кластеров μ<sub>1</sub>, …, μ<sub>k</sub> случайным образом.</li>\n<li>Вычислить расстояния ρ(x<sub>i</sub>, μ<sub>k</sub>) от каждого объекта до каждого центра.</li>\n<li>Отнести каждый объект к ближайшему центру. Так формируются кластеры X<sub>k</sub>.</li>\n<li>Вычислить новые центры кластеров как среднее значение всех точек кластера:\n<p class=\"formula\">μ<sub>k</sub> = (1 / s<sub>k</sub>) · Σ<sub>x ∈ X<sub>k</sub></sub> x,&nbsp;&nbsp; где s<sub>k</sub> — количество точек в кластере k.</p></li>\n<li>Если центры изменились (сдвинулись), повторить с шага 2; иначе завершить работу.</li>\n</ol>\n<p><strong>Функционал качества кластеризации:</strong></p>\n<p class=\"formula\">Q = c · d<sub>0</sub> / d<sub>1</sub> → min,</p>\n<p>где c — количество кластеров, d<sub>0</sub> — среднее внутрикластерное расстояние, d<sub>1</sub> — среднее межкластерное расстояние. Задача обучения — минимизация функционала качества.</p>\n<p><strong>Недостатки k-means:</strong></p>\n<ul>\n<li>нет гарантии достижения глобального минимума — только одного из локальных;</li>\n<li>результат зависит от выбора начальных центров, и их оптимальный выбор неизвестен;</li>\n<li>число кластеров нужно знать заранее;</li>\n<li>кластерный анализ не всегда даёт удовлетворительные результаты;</li>\n<li>необходим эвристический подбор параметров алгоритма, в частности начальных значений центров.</li>\n</ul>\n\n<h2>Алгоритм c-means (нечёткий метод c-средних)</h2>\n<p>Для заданного множества входных векторов x<sub>k</sub> и N выделяемых кластеров c<sub>j</sub> предполагается, что любой вектор x<sub>k</sub> принадлежит любому кластеру c<sub>j</sub> со степенью принадлежности µ<sub>jk</sub> ∈ [0, 1], где j — номер кластера, k — номер входного вектора.</p>\n<ol>\n<li><strong>Инициализация:</strong> задать количество кластеров N (2 &lt; N &lt; K), параметр q (обычно q = 1,5) и матрицу принадлежности U<sup>(0)</sup> = (µ<sub>jk</sub>)<sup>(0)</sup> с учётом начальных центров кластеров c<sub>j</sub>.</li>\n<li><strong>Уточнение центров:</strong> на t-м шаге по известной матрице U вычислить центры c<sub>j</sub><sup>(t)</sup>.</li>\n<li><strong>Корректировка принадлежности:</strong> по известным центрам c<sub>j</sub><sup>(t)</sup> вычислить µ<sub>jk</sub><sup>(t)</sup>.</li>\n<li><strong>Остановка:</strong> если матрица U не меняется — завершить, иначе перейти к шагу 2.</li>\n</ol>\n<p>В k-means неясно, как поступать с объектом, который в равной степени близок к нескольким кластерам или не близок ни к одному. Алгоритм c-means решает эту проблему: он вычисляет <strong>степень принадлежности</strong> объекта к каждому кластеру, которая определяется расстоянием объекта до центров кластеров. Кластеры здесь являются нечёткими множествами с нечёткими границами. Цель алгоритма — минимизация суммы взвешенных расстояний.</p>\n\n<h2>Поиск ассоциативных правил</h2>\n<p><strong>Обозначения:</strong></p>\n<ul>\n<li>X — пространство объектов;</li>\n<li>F = {f<sub>1</sub>, …, f<sub>k</sub>}, f<sub>j</sub>: X → {0, 1} — бинарные признаки;</li>\n<li>X<sup>n</sup> = {x<sub>1</sub>, …, x<sub>n</sub>} ⊂ X — обучающая выборка.</li>\n</ul>\n<p>Каждому подмножеству φ ⊆ F соответствует конъюнкция φ(x) = ∧<sub>f ∈ φ</sub> f(x), x ∈ X. Если φ(x) = 1, то «признаки из φ совместно встречаются у x».</p>\n<p><strong>Частота встречаемости (поддержка)</strong> набора φ в выборке X<sup>n</sup>:</p>\n<p class=\"formula\">v(φ) = (1/n) · Σ<sub>i=1</sub><sup>n</sup> φ(x<sub>i</sub>)</p>\n<p>Если v(φ) ≥ δ, то набор φ называется <strong>частым</strong>. Параметр δ — минимальная поддержка (MinSupp).</p>\n<p><strong>Ассоциативное правило</strong> φ → y — это пара непересекающихся наборов φ, y ⊆ F таких, что:</p>\n<ol>\n<li>наборы φ и y совместно часто встречаются: v(φ ∪ y) ≥ δ;</li>\n<li>если встречается φ, то часто встречается и y:\n<p class=\"formula\">v(y | φ) ≡ v(φ ∪ y) / v(φ) ≥ ϰ</p></li>\n</ol>\n<p>Величина v(y | φ) — <strong>значимость</strong> правила; параметр ϰ — минимальная значимость (MinConf).</p>\n<h3>Свойство антимонотонности</h3>\n<p>Задача — найти наборы элементов, встречающиеся наиболее часто. Простейший подход — перебор всех возможных наборов, но он слишком трудоёмок. Сократить пространство поиска позволяет свойство антимонотонности: с ростом набора его поддержка уменьшается или остаётся прежней.</p>\n<p class=\"formula\">Для любых ψ, φ ⊆ F: из φ ⊂ ψ следует v(φ) ≥ v(ψ).</p>\n\n<h3>Алгоритм Apriori</h3>\n<p><strong>Вход:</strong> обучающая выборка X<sup>n</sup>; минимальная поддержка δ; минимальная значимость ϰ.<br/><strong>Выход:</strong> R = {(φ, y)} — список ассоциативных правил.</p>\n<ol>\n<li>Множество всех частых исходных признаков: G<sub>1</sub> := { f ∈ F | v(f) ≥ δ };</li>\n<li>для всех j = 2, …, n:</li>\n<li>&nbsp;&nbsp;&nbsp;множество всех частых наборов мощности j:<br/>&nbsp;&nbsp;&nbsp;G<sub>j</sub> := { φ ∪ {f} | φ ∈ G<sub>j−1</sub>, f ∈ G<sub>1</sub> \\ φ, v(φ ∪ {f}) ≥ δ };</li>\n<li>&nbsp;&nbsp;&nbsp;если G<sub>j</sub> = ∅, то</li>\n<li>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;выход из цикла по j;</li>\n<li>R := ∅;</li>\n<li>для всех ψ ∈ G<sub>j</sub>, j = 2, …, n:</li>\n<li>&nbsp;&nbsp;&nbsp;AssocRules(R, ψ, ∅).</li>\n</ol>\n<p><strong>Процедура AssocRules(R, φ, y)</strong> — рекурсивно строит правила из частого набора:</p>\n<ol start=\"9\">\n<li>для всех f ∈ φ таких, что id<sub>f</sub> &gt; max<sub>g ∈ y</sub> id<sub>g</sub> (чтобы избежать повторов; id<sub>f</sub> — порядковый номер признака f в F = {f<sub>1</sub>, …, f<sub>n</sub>}):</li>\n<li>&nbsp;&nbsp;&nbsp;φ′ := φ \\ {f};&nbsp; y′ := y ∪ {f};</li>\n<li>&nbsp;&nbsp;&nbsp;если v(y′ | φ′) ≥ ϰ, то</li>\n<li>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;добавить ассоциативное правило (φ′, y′) в список R;</li>\n<li>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;если |φ′| &gt; 1, то</li>\n<li>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;AssocRules(R, φ′, y′).</li>\n</ol>\n","examples":"<h3>Пример 29. Одна итерация k-means вручную</h3>\n<p><strong>Данные</strong> (одномерные, например, время на сайте в минутах): 2, 3, 4, 10, 11, 12. Число кластеров k = 2.</p><ol><li><strong>Инициализация:</strong> случайно выбираем центры μ<sub>1</sub> = 2, μ<sub>2</sub> = 4.</li><li><strong>Расстояния и распределение по кластерам:</strong> точка 2 → μ<sub>1</sub> (0 против 2); 3 → μ<sub>1</sub> (1 против 1, при равенстве берём первый); 4, 10, 11, 12 → μ<sub>2</sub>. Кластеры: {2, 3} и {4, 10, 11, 12}.</li><li><strong>Новые центры</strong> как средние: μ<sub>1</sub> = 2,5; μ<sub>2</sub> = (4 + 10 + 11 + 12) / 4 = 9,25.</li><li><strong>Центры сдвинулись — повторяем.</strong> Точка 4: |4 − 2,5| = 1,5 против |4 − 9,25| = 5,25 → переходит в первый кластер. Кластеры: {2, 3, 4} и {10, 11, 12}; центры 3 и 11.</li><li>Следующая итерация не меняет кластеры — <strong>алгоритм остановлен</strong>.</li></ol><p><strong>Замечание.</strong> При других начальных центрах результат мог оказаться иным: k-means находит лишь локальный минимум, и число кластеров нужно знать заранее.</p><pre><code class=\"language-r\">x <- c(2, 3, 4, 10, 11, 12)\nkmeans(x, centers = c(2, 4))</code></pre>\n<h3>Пример 30. Поиск ассоциативных правил: поддержка и значимость</h3>\n<p><strong>Транзакции</strong> (n = 6): {хлеб, молоко}, {хлеб, масло}, {хлеб, молоко, масло}, {молоко, масло}, {хлеб, молоко}, {хлеб, молоко, масло}. Минимальная поддержка δ = 0,5; минимальная значимость ϰ = 0,7.</p><p><strong>Шаг 1. Частые одиночные признаки</strong> (G<sub>1</sub>): v(хлеб) = 5/6; v(молоко) = 5/6; v(масло) = 4/6 — все ≥ 0,5.</p><p><strong>Шаг 2. Частые пары</strong> (G<sub>2</sub>): v(хлеб, молоко) = 4/6 ≈ 0,67 ✓; v(хлеб, масло) = 3/6 = 0,5 ✓; v(молоко, масло) = 3/6 = 0,5 ✓.</p><p><strong>Шаг 3. Тройка:</strong> v(хлеб, молоко, масло) = 2/6 ≈ 0,33 &lt; 0,5 — не частая. По свойству антимонотонности большие наборы проверять не нужно.</p><p><strong>Шаг 4. Правила из пар</strong>, значимость v(y | φ) = v(φ ∪ y) / v(φ):</p><ul><li>хлеб → молоко: (4/6) / (5/6) = 0,8 ≥ 0,7 ✓</li><li>молоко → хлеб: 0,8 ✓</li><li>масло → хлеб: (3/6) / (4/6) = 0,75 ✓</li><li>хлеб → масло: (3/6) / (5/6) = 0,6 ✗</li></ul><p>Итог: найдено правило «кто покупает хлеб, в 80% случаев покупает и молоко».</p>\n","tasks":"<h3>Задание 1. Кластеризация и ассоциативные правила</h3>\n<p><strong>Цель:</strong> Закрепить работу алгоритмов k-means и Apriori.</p>\n<p><strong>Порядок выполнения:</strong></p><ol>\n<li>Выполните вручную k-means для точек 1, 2, 6, 7, 8, 15 при k = 2 и начальных центрах 1 и 2; запишите кластеры и центры на каждой итерации.</li>\n<li>Повторите расчёт с начальными центрами 7 и 15. Совпал ли результат? Объясните почему.</li>\n<li>Для 8 придуманных чеков из 4 товаров найдите все частые наборы (δ = 0,4) и правила со значимостью не ниже 0,6.</li>\n<li>Выполните лабораторную работу B10 и опишите, насколько полученные кластеры совпадают с видами ирисов (Species).</li>\n</ol>\n<p><strong>Ожидаемый результат:</strong> Протоколы двух запусков k-means, список частых наборов и правил, результат лабораторной работы с выводом.</p>\n<p><strong>Форма представления:</strong> Таблицы итераций, расчёты поддержки и значимости, график из R.</p>\n<details class='hint'><summary>Подсказка</summary><p>Для сравнения кластеров с видами используйте table(iris$cluster, iris$Species).</p></details>\n<h3>Лабораторная работа B10. Кластеризация</h3>\n<p><strong>Цель: </strong>Выполнить кластеризацию данных.</p>\n<h4><strong>Задания:</strong></h4>\n<p>1. Примените алгоритм k-means к переменным Sepal.Length и Sepal.Width.</p>\n<pre><code class=\"language-r\">kmeans_result &lt;- kmeans(iris[, c(\"Sepal.Length\", \"Sepal.Width\")], centers = 3)\niris$cluster &lt;- kmeans_result$cluster</code></pre>\n<p>2. Постройте график кластеризации.</p>\n<pre><code class=\"language-r\">ggplot(iris, aes(x = Sepal.Length, y = Sepal.Width, color = as.factor(cluster))) +\ngeom_point() +\nlabs(title = \"Кластеризация данных\")</code></pre>\n","selfcheck":"","questions":[{"id":"q15-1","type":"single","level":1,"text":"К какому виду обучения относится кластеризация?","options":["Обучение без учителя","Обучение с учителем","Обучение с подкреплением","Это не машинное обучение"],"correct":0,"explain":"Кластеризация — обучение без учителя: ответы (метки классов) заранее не заданы."},{"id":"q15-2","type":"multiple","level":2,"text":"Какие недостатки имеет алгоритм k-means? Отметьте все верные.","options":["Нет гарантии достижения глобального минимума","Результат зависит от начальных центров","Число кластеров нужно знать заранее","Не может работать с числовыми данными"],"correct":[0,1,2],"explain":"k-means работает именно с числовыми данными: центры вычисляются как средние."},{"id":"q15-3","type":"input","level":2,"text":"Объект встречается в 30 транзакциях из 120. Чему равна его поддержка v? Введите десятичную дробь.","answers":["0,25","0.25",".25"],"explain":"v = 30 / 120 = 0,25."},{"id":"q15-4","type":"truefalse","level":2,"text":"Верно ли, что в алгоритме c-means объект может принадлежать нескольким кластерам с разной степенью?","correct":true,"explain":"Верно. Кластеры в c-means — нечёткие множества, принадлежность µ лежит в отрезке [0, 1]."},{"id":"q15-5","type":"single","level":3,"text":"Что утверждает свойство антимонотонности?","options":["При расширении набора признаков его поддержка не увеличивается","При расширении набора поддержка всегда растёт","Значимость правила не зависит от поддержки","Число кластеров убывает с каждой итерацией"],"correct":0,"explain":"Если φ ⊂ ψ, то v(φ) ≥ v(ψ). Поэтому, если набор не частый, его расширения можно не проверять."}],"tests":""}},"thesaurus":[{"term":"ACID","definition":"Свойства транзакций: атомарность, согласованность, изолированность, долговечность.","lesson":7},{"term":"Amazon S3","definition":"Simple Storage Service — веб-служба Amazon для хранения и получения любого объёма данных.","lesson":11},{"term":"Apache Spark","definition":"Система распределённой обработки слабоструктурированных и неструктурированных данных; включает Spark SQL, Streaming, MLlib, GraphX.","lesson":6},{"term":"Application Master","definition":"Компонент Hadoop 2.0, координирующий жизненный цикл выполнения одного приложения.","lesson":6},{"term":"Apriori","definition":"Алгоритм поиска частых наборов и ассоциативных правил, использующий свойство антимонотонности.","lesson":15},{"term":"AUC","definition":"Area Under Curve — площадь под ROC-кривой, агрегированная характеристика качества классификации.","lesson":14},{"term":"BI-платформа","definition":"Программа с инструментами анализа практически любых данных; продвинутая система отчётности.","lesson":3},{"term":"BSON","definition":"Двоичный аналог JSON, используемый MongoDB для быстрого разбора данных.","lesson":8},{"term":"Business Intelligence (BI)","definition":"Методы и инструменты перевода необработанной информации в осмысленную форму для принятия бизнес-решений.","lesson":3},{"term":"c-means (нечёткий метод c-средних)","definition":"Алгоритм кластеризации, в котором объект принадлежит каждому кластеру со степенью от 0 до 1.","lesson":15},{"term":"Container","definition":"Единица ресурсов вычислительного узла в Hadoop 2.0; за ней следит Node Manager.","lesson":6},{"term":"Data Mining (ИАД)","definition":"Совокупность методов обнаружения в данных ранее неизвестных, нетривиальных, практически полезных и интерпретируемых знаний.","lesson":12},{"term":"Data Node","definition":"Управляемый узел HDFS, выполняющий запись и чтение блоков.","lesson":5},{"term":"Data Science","definition":"Область, использующая большие структурированные и неструктурированные данные для прогнозирования, оптимизации и статистического анализа.","lesson":4},{"term":"Document store","definition":"NoSQL-хранилище, где значением является документ (JSON, XML), к структуре которого можно делать запросы.","lesson":7},{"term":"EDA (Exploratory Data Analysis)","definition":"Разведывательный анализ данных: быстрое построение множества визуальных представлений для поиска скрытых зависимостей.","lesson":10},{"term":"ETL","definition":"Extract, Transform, Load — извлечение, преобразование и загрузка данных в хранилище.","lesson":3},{"term":"Eventually consistent","definition":"«Целостный в конечном итоге»: данные в AP-системе становятся согласованными спустя некоторое время.","lesson":7},{"term":"F-мера","definition":"Характеристика, одновременно учитывающая точность и полноту.","lesson":14},{"term":"Flume","definition":"Инструмент сбора потоков данных из различных источников в централизованное хранилище.","lesson":6},{"term":"Graph store","definition":"NoSQL-хранилище для сложных взаимосвязей: узлы и связи с атрибутами.","lesson":7},{"term":"Hadoop","definition":"Каркас с открытым исходным кодом для создания и запуска распределённых приложений, обрабатывающих большие объёмы данных.","lesson":5},{"term":"HBase","definition":"NoSQL база данных, работающая поверх HDFS.","lesson":6},{"term":"HDFS","definition":"Hadoop Distributed File System — распределённая файловая система для хранения очень больших файлов на кластерах из обычных машин.","lesson":5},{"term":"Hive","definition":"Надстройка над Hadoop для хранения данных в виде таблиц и выполнения SQL-подобных запросов (HiveQL).","lesson":6},{"term":"Job Tracker","definition":"Компонент MapReduce 1.0 на Master-узле, разбивающий задачу на части и распределяющий их по Task Tracker.","lesson":5},{"term":"JOIN","definition":"Операция соединения таблиц в реляционных БД; в большинстве NoSQL-систем не поддерживается.","lesson":8},{"term":"JSON","definition":"Текстовый формат обмена данными в виде вложенных объектов «ключ: значение» и массивов.","lesson":8},{"term":"k-means (метод k-средних)","definition":"Алгоритм кластеризации: точки относят к ближайшему центру, центры пересчитывают как средние, пока они не перестанут сдвигаться.","lesson":15},{"term":"Key/value store","definition":"NoSQL-хранилище в виде коллекции пар с уникальным ключом.","lesson":7},{"term":"MapReduce","definition":"Технология распределённых вычислений над парами ключ–значение в два этапа: Map (предварительная обработка) и Reduce (свёртка).","lesson":5},{"term":"MDS (Master Data Services)","definition":"Компонент SQL Server для управления мастер-данными компании.","lesson":4},{"term":"MDX","definition":"Язык запросов к многомерным OLAP-кубам.","lesson":4},{"term":"MongoDB","definition":"Документо-ориентированная NoSQL СУБД, написанная на C++ и хранящая документы в формате BSON.","lesson":8},{"term":"Name Node","definition":"Управляющий узел HDFS: пространство имён, метаданные, сведения о расположении блоков.","lesson":5},{"term":"NLP","definition":"Natural Language Processing — обработка естественного языка.","lesson":12},{"term":"NoSQL","definition":"Not Only SQL — ряд подходов к хранению данных без реляционной модели, ориентированных на масштабируемость и доступность.","lesson":7},{"term":"OLAP","definition":"Online Analytical Processing — технология сбора, хранения и анализа многомерных данных для поддержки управленческих решений.","lesson":3},{"term":"OLAP-куб","definition":"Многомерная структура: измерения (время, регион, товар) образуют оси, в ячейках хранятся числовые показатели.","lesson":3},{"term":"Pig","definition":"Высокоуровневый процедурный язык запросов к слабоструктурированным данным больших объёмов.","lesson":6},{"term":"Power BI","definition":"Инструмент Microsoft для создания интерактивных бизнес-отчётов и панелей с возможностью совместной работы.","lesson":4},{"term":"Power Query","definition":"Инструмент Excel для поиска, загрузки и преобразования данных из разных источников; имеет встроенную поддержку ETL.","lesson":4},{"term":"Pyramid Analytics","definition":"Облачная платформа бизнес-аналитики с интеллектуальным анализом, интерактивной визуализацией и интеграцией с R.","lesson":4},{"term":"R","definition":"Свободный язык программирования для статистического анализа и графики, развиваемый R Foundation.","lesson":11},{"term":"RapidMiner","definition":"Свободный инструмент Data Mining на Java с визуальным построением процессов из операторов.","lesson":12},{"term":"Replica set","definition":"Репликационное множество MongoDB, в котором при потере мастера автоматически выбирается новый.","lesson":8},{"term":"Resource Manager","definition":"Компонент Hadoop 2.0, управляющий ресурсами кластера.","lesson":6},{"term":"ROC-кривая","definition":"График зависимости доли верных положительных классификаций (TPR) от доли ложных (FPR).","lesson":14},{"term":"Sqoop","definition":"Инструмент передачи данных между Hadoop и реляционными базами данных.","lesson":6},{"term":"SSAS (SQL Server Analysis Services)","definition":"Компонент SQL Server для OLAP и data mining.","lesson":4},{"term":"SSIS (SQL Server Integration Services)","definition":"Компонент SQL Server для миграции и интеграции данных.","lesson":4},{"term":"t-критерий Стьюдента","definition":"Параметрический критерий для проверки равенства средних двух выборок при нормальном распределении.","lesson":13},{"term":"Task Tracker","definition":"Компонент MapReduce, выполняющий небольшую вычислительную задачу на узле.","lesson":5},{"term":"Text Mining","definition":"Обнаружение новых, полезных и понятных шаблонов в неструктурированных текстовых данных.","lesson":12},{"term":"Value","definition":"Характеристика Big Data: ценность накопленной информации для бизнеса.","lesson":1},{"term":"Variety","definition":"Характеристика Big Data: многообразие форматов, возможность одновременной обработки структурированной и неструктурированной информации.","lesson":1},{"term":"Velocity","definition":"Характеристика Big Data: скорость накопления и обработки данных, в том числе в реальном времени.","lesson":1},{"term":"Veracity","definition":"Характеристика Big Data: достоверность данных.","lesson":1},{"term":"Volume","definition":"Характеристика Big Data: гигантский объём накопленных данных, обработка которого традиционными способами трудоёмка.","lesson":1},{"term":"Web Mining","definition":"Применение методов ИАД к веб-документам, сервисам и данным об их использовании.","lesson":12},{"term":"YARN","definition":"Фреймворк распределения ресурсов Hadoop 2.0, не зависящий от специфики распределённого алгоритма.","lesson":6},{"term":"Анализ данных","definition":"Совокупность методов и средств извлечения из организованных данных информации для принятия решений.","lesson":2},{"term":"Анализ рыночной корзины","definition":"Поиск типичных комбинаций товаров, покупаемых вместе (ассоциативных правил).","lesson":12},{"term":"Антимонотонность","definition":"Свойство: при расширении набора признаков его поддержка не возрастает.","lesson":15},{"term":"Ассоциативное правило","definition":"Пара непересекающихся наборов φ → y, которые часто встречаются вместе, причём при φ часто встречается и y.","lesson":15},{"term":"Бакет","definition":"Контейнер в Amazon S3, содержащий директории и файлы.","lesson":11},{"term":"Блок HDFS","definition":"Фрагмент файла фиксированного размера (64 МБ в Hadoop 1.x), хранящийся независимо и реплицируемый на несколько узлов.","lesson":5},{"term":"Большие данные (Big Data)","definition":"Комплексный набор методов, подходов и инструментов обработки структурированных и неструктурированных данных колоссальных объёмов.","lesson":1},{"term":"Вектор (R)","definition":"Упорядоченный набор значений одного типа: числовых, строковых или логических.","lesson":11},{"term":"Версионирование","definition":"Хранение предыдущих версий файлов с возможностью восстановления нужного состояния.","lesson":11},{"term":"Вертикальное масштабирование","definition":"Замена компонентов системы более мощными и быстрыми.","lesson":7},{"term":"Визуализация","definition":"Наглядное представление результатов анализа в виде изображений, диаграмм, анимаций.","lesson":9},{"term":"Выборка","definition":"Подмножество из N элементов генеральной совокупности, по которому делают статистический вывод.","lesson":13},{"term":"Генеральная совокупность","definition":"Полный набор объектов, связанных с изучаемой проблемой.","lesson":13},{"term":"Гипотеза компактности","definition":"Предположение, что похожие объекты чаще всего принадлежат одному классу.","lesson":14},{"term":"Горизонтальное масштабирование","definition":"Добавление к системе новых узлов, серверов, процессоров.","lesson":7},{"term":"Дашборд","definition":"Дисплей, на котором все необходимые показатели выведены в одном месте в виде графиков, диаграмм и таблиц.","lesson":10},{"term":"Дедупликация","definition":"Технология обнаружения и исключения избыточных (повторяющихся) данных в хранилище.","lesson":11},{"term":"Детализация (drill-down)","definition":"Операция OLAP: переход на более подробный уровень иерархии измерения.","lesson":3},{"term":"Жизненный цикл аналитики данных","definition":"Последовательность действий от выявления проблемы до практической реализации результатов анализа.","lesson":3},{"term":"Значимость (confidence)","definition":"Условная частота v(y | φ) = v(φ ∪ y) / v(φ).","lesson":15},{"term":"Интерактивный сторителлинг","definition":"Рассказ на основе данных, с которым пользователь может взаимодействовать, управляя отображением информации.","lesson":10},{"term":"Инфографика","definition":"Статичная визуализация журналистики данных с готовыми выводами, графиками и схемами по выбранной теме.","lesson":10},{"term":"Информационная визуализация","definition":"Представление абстрактной информации, полученной при сборе и обработке многокатегориальных данных.","lesson":9},{"term":"Исторический поток","definition":"Диаграмма эволюции документа: время по горизонтали, вклад каждого соавтора по вертикали.","lesson":10},{"term":"Картограмма","definition":"Карта с нанесённой на неё информацией в виде цвета или других способов.","lesson":9},{"term":"Классификация","definition":"Отнесение объектов к одному из заранее известных классов на основе их характеристик.","lesson":12},{"term":"Кластер","definition":"Группа близких между собой объектов, существенно отличающихся от объектов других групп.","lesson":15},{"term":"Кластерграмма","definition":"Визуализация соотношения элементов данных с кластерами при изменении их количества.","lesson":10},{"term":"Кластеризация","definition":"Разделение множества объектов на группы (кластеры) по принципу сходства без заранее известных классов.","lesson":12},{"term":"Коллекция","definition":"Группа документов MongoDB, объединённых по смыслу; аналог таблицы без жёсткой схемы.","lesson":8},{"term":"Линейный классификатор","definition":"Алгоритм, строящий разделяющую линейную поверхность (гиперплоскость) в пространстве признаков.","lesson":14},{"term":"Машинное обучение","definition":"Построение алгоритмов, обучающихся по данным (прецедентам) из обучающей выборки.","lesson":13},{"term":"Метод k ближайших соседей (kNN)","definition":"Объект относится к классу, которому принадлежит большинство из k ближайших к нему объектов выборки.","lesson":14},{"term":"Метрический классификатор","definition":"Алгоритм классификации, основанный на оценке сходства (расстояния) между объектами.","lesson":14},{"term":"Многокомпонентная загрузка","definition":"Загрузка файла в S3 по частям последовательно или параллельно через специальный API.","lesson":11},{"term":"Монетизация данных (Data Asset Monetization)","definition":"Получение дохода от имеющихся данных, например, их продажа партнёрам.","lesson":2},{"term":"Мощность критерия","definition":"Величина 1 − β: вероятность обнаружить действительно существующее различие.","lesson":13},{"term":"Научная визуализация","definition":"Тип визуализации больших объёмов данных, получаемых при моделировании объектов и процессов.","lesson":9},{"term":"Неструктурированные данные","definition":"Данные без заранее заданной модели: тексты, изображения, аудио, видео.","lesson":1},{"term":"Облако тегов","definition":"Визуализация, где размер шрифта слова соответствует его весовому коэффициенту (частоте употребления).","lesson":10},{"term":"Отступ","definition":"Мера удалённости объекта от разделяющей поверхности; малый отступ означает высокий риск ошибки.","lesson":14},{"term":"Отток клиентов","definition":"Уход клиентов к конкурентам; анализ текучести позволяет заранее выявить «группу риска».","lesson":2},{"term":"Ошибка второго рода","definition":"Необнаружение существующих различий или связей; её вероятность обозначается β.","lesson":13},{"term":"Ошибка первого рода","definition":"Обнаружение несуществующих различий или связей; её вероятность — уровень значимости α.","lesson":13},{"term":"Поддержка (support)","definition":"Частота встречаемости набора признаков в выборке, v(φ).","lesson":15},{"term":"Полнота (Recall, TPR)","definition":"TP / (TP + FN) — доля найденных объектов среди всех реальных положительных.","lesson":14},{"term":"Регрессия","definition":"Определение значения одного количественного параметра объекта по другим его характеристикам.","lesson":12},{"term":"Репликация","definition":"Копирование данных на другие узлы при обновлении для отказоустойчивости и снижения нагрузки.","lesson":7},{"term":"Репликация (HDFS)","definition":"Хранение нескольких копий каждого блока на разных машинах для отказоустойчивости.","lesson":5},{"term":"Сводная таблица (pivot table)","definition":"Двумерный массив агрегированных данных: в заголовках строк и столбцов — значения двух измерений.","lesson":4},{"term":"Сегментация","definition":"Разделение клиентов на группы по общим признакам для адресных предложений.","lesson":2},{"term":"Скоринг","definition":"Оценка заёмщика (вероятности возврата кредита) на основе данных о клиенте.","lesson":2},{"term":"Статистика","definition":"Отрасль знаний о сборе, измерении и анализе массовых количественных и качественных данных.","lesson":13},{"term":"Статистическая гипотеза","definition":"Любое утверждение о распределении наблюдаемой случайной величины; обычно проверяют H0 против альтернативы H1.","lesson":13},{"term":"Стохастический градиентный спуск (SG)","definition":"Итерационный метод подбора весов, на каждом шаге использующий случайно выбранный объект выборки.","lesson":14},{"term":"Структурированные данные","definition":"Данные с заранее заданной структурой, допускающие классификацию (например, клиентские транзакции в таблице).","lesson":1},{"term":"Таблица данных (data frame)","definition":"Структура R из столбцов-векторов одинаковой длины, аналог таблицы.","lesson":11},{"term":"Таксономия","definition":"Иерархия множества объектов, построенная с помощью кластеризации.","lesson":15},{"term":"Теорема CAP","definition":"Теорема Брюера: в распределённой системе можно обеспечить не более двух из трёх свойств — согласованность, доступность, устойчивость к разделению.","lesson":7},{"term":"Точность (Precision)","definition":"TP / (TP + FP) — доля верных среди объектов, отнесённых к положительному классу.","lesson":14},{"term":"Функция потерь","definition":"Величина ошибки алгоритма на объекте: индикатор ошибки, абсолютная или квадратичная ошибка.","lesson":13},{"term":"Хеш-функция","definition":"Функция, вычисляющая короткий «отпечаток» блока данных; совпадение хешей указывает на одинаковые блоки.","lesson":11},{"term":"Хранилище данных","definition":"База данных — получатель, в которую помещаются извлечённые и преобразованные данные для анализа.","lesson":3},{"term":"Шардинг","definition":"Разделение базы данных на части, размещаемые на отдельных серверах.","lesson":7}],"reference":"<h2>Единицы измерения объёма данных</h2>\n<table>\n<tr><th>Единица</th><th>Обозначение</th><th>Десятичная система</th><th>Двоичная система</th></tr>\n<tr><td>Килобайт</td><td>КБ</td><td>10<sup>3</sup> байт</td><td>2<sup>10</sup> = 1024 байт</td></tr>\n<tr><td>Мегабайт</td><td>МБ</td><td>10<sup>6</sup></td><td>2<sup>20</sup></td></tr>\n<tr><td>Гигабайт</td><td>ГБ</td><td>10<sup>9</sup></td><td>2<sup>30</sup></td></tr>\n<tr><td>Терабайт</td><td>ТБ</td><td>10<sup>12</sup></td><td>2<sup>40</sup></td></tr>\n<tr><td>Петабайт</td><td>ПБ</td><td>10<sup>15</sup></td><td>2<sup>50</sup></td></tr>\n<tr><td>Эксабайт</td><td>ЭБ</td><td>10<sup>18</sup></td><td>2<sup>60</sup></td></tr>\n<tr><td>Зеттабайт</td><td>ЗБ</td><td>10<sup>21</sup></td><td>2<sup>70</sup></td></tr>\n</table>\n\n<h2>Характеристики Big Data («5V»)</h2>\n<table>\n<tr><th>Характеристика</th><th>Смысл</th></tr>\n<tr><td>Volume</td><td>Объём</td></tr>\n<tr><td>Velocity</td><td>Скорость поступления и обработки</td></tr>\n<tr><td>Variety</td><td>Многообразие форматов</td></tr>\n<tr><td>Veracity</td><td>Достоверность</td></tr>\n<tr><td>Value</td><td>Ценность</td></tr>\n</table>\n<p>Первые три образуют принцип «Трёх V».</p>\n\n<h2>Экосистема Hadoop</h2>\n<table>\n<tr><th>Компонент</th><th>Назначение</th></tr>\n<tr><td>HDFS</td><td>Распределённая файловая система (Name Node, Data Node)</td></tr>\n<tr><td>MapReduce</td><td>Модель распределённых вычислений (Map → Reduce)</td></tr>\n<tr><td>YARN</td><td>Управление ресурсами кластера (Hadoop 2.0)</td></tr>\n<tr><td>HBase</td><td>NoSQL база данных поверх HDFS</td></tr>\n<tr><td>Hive</td><td>SQL-подобные запросы (HiveQL)</td></tr>\n<tr><td>Pig</td><td>Процедурный язык запросов к слабоструктурированным данным</td></tr>\n<tr><td>Mahout</td><td>Библиотеки машинного обучения</td></tr>\n<tr><td>Sqoop</td><td>Обмен данными между Hadoop и реляционными БД</td></tr>\n<tr><td>Flume</td><td>Сбор потоков данных (логов)</td></tr>\n<tr><td>ZooKeeper</td><td>Синхронизация и конфигурирование</td></tr>\n<tr><td>Avro</td><td>Сериализация данных</td></tr>\n<tr><td>HUE</td><td>Web-интерфейс к Hadoop</td></tr>\n<tr><td>Spark</td><td>Быстрые кластерные вычисления: Spark SQL, Streaming, MLlib, GraphX</td></tr>\n</table>\n\n<h2>Теорема CAP и типы NoSQL-хранилищ</h2>\n<table>\n<tr><th>Класс</th><th>Обеспечивает</th><th>Жертвует</th><th>Пример</th></tr>\n<tr><td>CA</td><td>Согласованность, доступность</td><td>Устойчивость к разделению</td><td>Кластерные СУБД, LDAP</td></tr>\n<tr><td>CP</td><td>Согласованность, устойчивость к разделению</td><td>Доступность</td><td>Системы с распределёнными блокировками</td></tr>\n<tr><td>AP</td><td>Доступность, устойчивость к разделению</td><td>Согласованность</td><td>DNS, веб-кэши, большинство NoSQL</td></tr>\n</table>\n<table>\n<tr><th>Тип хранилища</th><th>Модель</th><th>Пример применения</th></tr>\n<tr><td>Key/value store</td><td>Уникальный ключ → значение</td><td>Кэш, сессии пользователей</td></tr>\n<tr><td>Column store</td><td>Строки × колонки × временные метки</td><td>Большие разреженные таблицы</td></tr>\n<tr><td>Document store</td><td>Документы JSON/XML с запросами к структуре</td><td>Каталоги товаров, профили (MongoDB)</td></tr>\n<tr><td>Graph store</td><td>Узлы и связи с атрибутами</td><td>Социальные связи, рекомендации</td></tr>\n</table>\n\n<h2>Формулы</h2>\n<table>\n<tr><th>Величина</th><th>Формула</th></tr>\n<tr><td>Точность (Precision)</td><td>TP / (TP + FP)</td></tr>\n<tr><td>Полнота (Recall, TPR)</td><td>TP / (TP + FN)</td></tr>\n<tr><td>Доля ложных срабатываний (FPR)</td><td>FP / (FP + TN)</td></tr>\n<tr><td>F-мера</td><td>1 / (α / Precision + (1 − α) / Recall); при α = 0,5: 2 · P · R / (P + R)</td></tr>\n<tr><td>Поддержка набора φ</td><td>v(φ) = (число объектов, содержащих φ) / n</td></tr>\n<tr><td>Значимость правила φ → y</td><td>v(y | φ) = v(φ ∪ y) / v(φ)</td></tr>\n<tr><td>Центр кластера (k-means)</td><td>μ<sub>k</sub> = (1 / s<sub>k</sub>) · Σ x, сумма по точкам кластера k</td></tr>\n<tr><td>Мощность критерия</td><td>1 − β</td></tr>\n<tr><td>Абсолютная ошибка</td><td>|α(x) − y(x)|</td></tr>\n<tr><td>Квадратичная ошибка</td><td>(α(x) − y(x))<sup>2</sup></td></tr>\n</table>\n\n<h2>Основные функции R, используемые в курсе</h2>\n<table>\n<tr><th>Функция</th><th>Назначение</th></tr>\n<tr><td><code>data(mtcars)</code>, <code>head()</code></td><td>Загрузить встроенный набор данных, показать первые строки</td></tr>\n<tr><td><code>mean()</code>, <code>median()</code>, <code>sd()</code>, <code>var()</code>, <code>IQR()</code></td><td>Среднее, медиана, стандартное отклонение, дисперсия, межквартильный размах</td></tr>\n<tr><td><code>summary()</code></td><td>Сводка по данным или модели</td></tr>\n<tr><td><code>na.omit()</code>, <code>is.na()</code></td><td>Удалить строки с пропусками, найти пропуски</td></tr>\n<tr><td><code>write.csv()</code>, <code>read.csv()</code></td><td>Сохранить и загрузить CSV</td></tr>\n<tr><td><code>filter()</code>, <code>arrange()</code>, <code>group_by()</code>, <code>summarise()</code></td><td>Пакет dplyr: фильтрация, сортировка, группировка, агрегирование</td></tr>\n<tr><td><code>ggplot() + geom_histogram()/geom_boxplot()/geom_point()</code></td><td>Пакет ggplot2: гистограмма, диаграмма размаха, точечный график</td></tr>\n<tr><td><code>lm(y ~ x, data)</code></td><td>Линейная регрессия</td></tr>\n<tr><td><code>kmeans(x, centers)</code></td><td>Кластеризация k-средних</td></tr>\n<tr><td><code>cor()</code>, <code>cov()</code></td><td>Корреляция и ковариация</td></tr>\n<tr><td><code>t.test()</code></td><td>t-критерий Стьюдента</td></tr>\n<tr><td><code>ts()</code>, <code>decompose()</code></td><td>Временной ряд и его разложение на компоненты</td></tr>\n<tr><td><code>as.Date()</code>, <code>difftime()</code></td><td>Работа с датами</td></tr>\n<tr><td><code>install.packages(\"dplyr\")</code>, <code>library(dplyr)</code></td><td>Установить и подключить пакет</td></tr>\n</table>\n\n<h2>Порядок выполнения лабораторных работ</h2>\n<ol>\n<li>Установите R (cran.r-project.org) и RStudio (posit.co).</li>\n<li>Установите пакеты один раз: <code>install.packages(c(\"dplyr\", \"ggplot2\", \"stringr\", \"forecast\"))</code>.</li>\n<li>Для каждой работы создайте отдельный скрипт (File → New File → R Script) и сохраните его с расширением .R.</li>\n<li>В отчёт включите: цель, код, результаты (вывод консоли и графики), выводы.</li>\n</ol>\n","labsExtra":"<h3>Дополнительные материалы по R</h3>\n<ul>\n<li>Официальная документация по R: R Documentation</li>\n<li>Руководство по ggplot2: ggplot2 Documentation</li>\n<li>Учебные пособия по dplyr: dplyr Documentation</li>\n</ul>\n","meta":{"_comment":"Выходные сведения ЭУИ (СТ РК 34.017-2005, §13). Поля со значением TODO заполняет автор курса.","title_ru":"Анализ больших данных","title_kk":"Үлкен деректерді талдау","subtitle_ru":"Электронное учебное пособие","subtitle_kk":"Электрондық оқу құралы","language_ru":"Язык текста: русский","language_kk":"Мәтін тілі: орыс тілі","organization":"Кызылординский университет имени Коркыт Ата","organization_kk":"Қорқыт ата атындағы Қызылорда университеті","organization_en":"Korkyt Ata Kyzylorda University","department":"ОП «Компьютерные науки»","department_kk":"«Компьютерлік ғылымдар» БББ","authors":["Даутбаева Айгуль Оспановна, кандидат технических наук, ассоциированный профессор (доцент)"],"authors_kk":["Даутбаева Айгуль Оспановна, техника ғылымдарының кандидаты, қауымдастырылған профессор (доцент)"],"authors_lat":["Dautbayeva Aigul Ospanovna"],"reviewers":["TODO: рецензент (при наличии)"],"year":"2026","city":"Кызылорда","city_kk":"Қызылорда","specialty":"6B06149 – Информационные системы; 6B06150 – Вычислительная техника и программное обеспечение","specialty_kk":"6B06149 – Ақпараттық жүйелер; 6B06150 – Есептеу техникасы және бағдарламалық қамтамасыз ету","udc":"TODO: УДК (факультативно)","copyright":"© Даутбаева А. О., 2026","publisher":{"name":"Издательство «Қорқыт Ата университеті» Кызылординского университета имени Коркыт Ата","address":"120014, г. Кызылорда, ул. Айтеке би, 29А, главный учебный корпус","email":"zhansap@korkyt.kz","phone":"8 (7242) 27-60-27"},"developer":{"name":"Даутбаева А. О.","address":"Кызылординский университет имени Коркыт Ата","email":"aicos@mail.ru","phone":"8 747 980 68 22"},"audience_ru":"Для студентов высших учебных заведений, обучающихся по направлению «Информационные технологии».","audience_kk":"«Ақпараттық технологиялар» бағыты бойынша білім алатын жоғары оқу орындарының студенттеріне арналған.","annotation_ru":"Электронное учебное пособие содержит систематическое изложение курса «Анализ больших данных» в объёме 3 модулей, 7 блоков и 15 уроков. Рассматриваются понятие и характеристики больших данных, бизнес-аналитика и OLAP, технологии распределённого хранения и обработки (Hadoop, MapReduce, YARN, Spark), NoSQL-базы данных и MongoDB, облачное хранение Amazon S3, визуализация данных, язык R, интеллектуальный анализ данных, статистические методы, машинное обучение, методы классификации, кластеризации и поиска ассоциативных правил. Каждый урок включает теорию, разобранные примеры, задания с порядком выполнения, интерактивные вопросы и тесты с пояснениями; предусмотрены 19 лабораторных работ на языке R, тезаурус и справочник. Пособие предназначено для студентов и преподавателей вузов и позволяет изучать материал самостоятельно по выбранной траектории с текущим, промежуточным, рубежным и итоговым контролем знаний.","annotation_kk":"Электрондық оқу құралында «Үлкен деректерді талдау» курсы 3 модуль, 7 блок және 15 сабақ көлемінде жүйелі түрде баяндалған. Үлкен деректер ұғымы мен сипаттамалары, бизнес-аналитика және OLAP, деректерді үлестірілген сақтау және өңдеу технологиялары (Hadoop, MapReduce, YARN, Spark), NoSQL дерекқорлары және MongoDB, Amazon S3 бұлттық қоймасы, деректерді визуализациялау, R тілі, деректерді зияткерлік талдау, статистикалық әдістер, машиналық оқыту, жіктеу, кластерлеу және ассоциативтік ережелерді іздеу әдістері қарастырылады. Әр сабақта теория, талданған мысалдар, орындау тәртібі көрсетілген тапсырмалар, интерактивті сұрақтар мен түсіндірмесі бар тесттер берілген; R тілінде 19 зертханалық жұмыс, тезаурус және анықтамалық қамтылған. Құрал жоғары оқу орындарының студенттері мен оқытушыларына арналған және материалды таңдалған траектория бойынша ағымдағы, аралық, межелік және қорытынды бақылаумен өз бетінше оқуға мүмкіндік береді.","system_requirements_ru":"Компьютер или мобильное устройство с современным браузером (Chrome, Firefox, Edge, Safari последних версий); экран от 360 пикселей по ширине; для работы в сети — доступ к Интернету; для офлайн-версии — 50 МБ свободного места. Для лабораторных работ: R 4.x и RStudio, Windows 10+, macOS 12+ или Linux. Звуковая система не требуется.","bibliography":["TODO: основная литература, утверждённая в силлабусе (оформить по ГОСТ 7.82 / ГОСТ 7.1)","White T. Hadoop: The Definitive Guide. 4th ed. — O'Reilly Media, 2015. — 756 p. (проверить по силлабусу)","Wickham H., Grolemund G. R for Data Science. — O'Reilly Media, 2017. — 520 p. (проверить по силлабусу)","Источник материала: учебный сайт «Анализ больших данных», https://sites.google.com/view/analyze-big-data"],"corrections":["Уроки 14–15: формулы, искажённые при копировании из Word, набраны заново (authored/overrides/14-theory.html, 15-theory.html).","Урок 15: шаги алгоритма Apriori и процедуры AssocRules расположены в правильном порядке; материал практик 14–15 объединён с лекцией.","Урок 13: исправлено утверждение о мощности критерия; формулы модели обучения набраны заново (authored/patches.json).","Все уроки: символы шрифта Symbol (∈, ⊆, ∪, ∅, ∧, ×, ∇) восстановлены; маркированные списки Word преобразованы в списки."],"size_mb":3.5},"build":"2026-11-21"};
